INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(63, 'plPL', 'Zew wody', 'Na wybrzeżu Srebrzystego Boru, na zachód od Grobowiska, znajdziesz kapliczkę skażoną przez zarazę. Duchy już nie przemawiają tam do naszego ludu i to od ciebie zależy, czy pokonasz manifestację i oczyścisz sadzawkę.$B$BWeź karwasze żywiołaka razem z ostatnimi kroplami mikstury Solanki i połóż je na koszu żarowym. Rytuał powinien wystarczyć, by przywołać czystego ducha, z którym się porozumiesz.$B$BPrzynieś mi dowód wykonania zadania, a nagrodzę cię twoim totemem.', 'Pokonaj skażoną manifestację wody i połóż karwasze skażonej manifestacji wraz z ostatnimi kroplami najczystszej wody na koszu żarowym Wiecznego Źródła w Srebrzystym Borze.', '', 'Odszukaj kosz żarowy Wiecznego Źródła przy Północnym Nurcie Przypływu w Srebrzystym Borze.', '', '', '', '', 0),
(65, 'plPL', 'Bractwo Nieskornych', 'Banda nędzników, która przegnała z tej ziemi dobrych ludzi z Zachodniego Skraju, nazywa siebie Bractwem Nieskornych. Musisz przeniknąć do tej zgrai zbirów. Musimy się dowiedzieć, kto stoi na czele tej szajki i gdzie się ukrywają. W Jeziernych Włościach, w karczmie, jest łotr imieniem Wiley, który jest mi winien przysługę.$b$bUdaj się do Jeziernych Włości w Górach Rudej Grani, na wschód od Elwynn, i dowiedz się, czego tylko zdołasz.', 'Gryan Mocnopłaszcz chce, żebyś $gporozmawiał:porozmawiała; z Wileyem w Jeziernych Włościach.', '', '', '', '', '', '', 0),
(96, 'plPL', 'Zew wody', 'Weź odłamek. Weź odłamek i daj życie.$B$BDaj życie i zrozum. Zrozum, woda to życie... skażenie zatrzymuje życie.$B$BTy chronić i dawać życie mocą wody.', 'Zanieś odłamek wody Islen Wodowieszczce na Schodach Tidusa na Pustkowiach.', '', '', '', '', '', '', 0),
(120, 'plPL', 'Posłaniec do Wichrogrodu', 'Nastały ciężkie czasy, $N. Nasze miasteczko jest nieustannie oblegane. Bez posiłków z pewnością czeka nas klęska. Wiadomość, którą ci teraz powierzam, ma ogromną wagę. Natychmiast dostarcz ten raport generałowi Marcusowi Jonathanowi w Wichrogrodzie. Gdy tylko go przekażesz, od razu wracaj do mnie z wieściami, dobrymi czy złymi.$b$bA teraz pośpiesz się!', 'Sędzia Solomon dał ci raport, który musisz dostarczyć generałowi Marcusowi Jonathanowi w Wichrogrodzie. Sędzia chce, żebyś $gwrócił:wróciła; do niego, gdy tylko go dostarczysz.', '', '', '', '', '', '', 0),
(121, 'plPL', 'Posłaniec do Wichrogrodu', 'Czekając na odpowiedź króla, chcę, żebyś $gzaniósł:zaniosła; ten list sędziemu Solomonowi.$b$bOdmaszerować, $N!', 'Zanieś list z odpowiedzią generała Marcusa Jonathana sędziemu Solomonowi w Jeziernych Włościach.', '', '', '', '', '', '', 0),
(132, 'plPL', 'Bractwo Nieskornych', 'To, co ci zaraz powiem, może mnie kosztować życie. Banda Nieskornych szykuje coś dużego. Ostatnio słyszałem, że współpracują z różnymi gnolami, koboldami, a nawet goblinami.$b$bZanieś ten liścik Mocnopłaszczowi. Jest w nim wszystko, co wiem na ten temat.', 'Zanieś liścik Wileya Gryanowi Mocnopłaszczowi w Zachodnim Skraju.', '', '', '', '', '', '', 0),
(135, 'plPL', 'Bractwo Nieskornych', 'Zastanawiam się, co Wiley miał na myśli, kiedy wspomniał o kamieniarzach. Może mu się wymsknęło. Czy banda Nieskornych może mieć coś wspólnego z kamieniarzami? Tylko jeden człowiek wie to na pewno: Mathias Shaw, szef WW:7. Pokaż mu liścik Wileya i sprawdź, czy może coś dodać do tej coraz bardziej zawiłej zagadki. Jeśli będziesz mieć kłopot ze znalezieniem Shawa, zajrzyj do koszar na Starym Mieście.', 'Zanieś liścik Wileya Mathiasowi Shawowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(137, 'plPL', '<NYI> <TXT> Pochwała z Wichrogrodu', 'Jeśli zdobędziesz pochwałę od któregoś z naszych marszałków, przynieś mi ją. Można ją wymienić na parę naszych rękawic z godłem lwa.', 'Generał Marcus Jonathan w Wichrogrodzie przyjmie pochwałę z Kniei Elwynn. W zamian za taki dokument otrzymasz do wyboru element zbroi.', '', 'Wróć do generała Marcusa Jonathana w Dolinie Bohaterów w Wichrogrodzie.', '', '', '', '', 0),
(141, 'plPL', 'Bractwo Nieskornych', 'Gildią Kamieniarzy kierował człowiek o nazwisku Edwin VanCleef. VanCleef odpowiadał za odbudowę Wichrogrodu po tym, jak orkowie zrównali go z ziemią podczas Pierwszej Wojny. Najwyraźniej VanCleef i jego ludzie byli niezadowoleni z tego, jak potraktował ich król po zakończeniu odbudowy. To mogłoby co nieco wyjaśniać.$b$bSporządziłem dokładniejszy raport dla twojego zwierzchnika w Zachodnim Skraju. Zanieś mu go natychmiast!', 'Zanieś raport Shawa Gryanowi Mocnopłaszczowi w Zachodnim Skraju.', '', '', '', '', '', '', 0),
(142, 'plPL', 'Bractwo Nieskornych', 'Musimy odkryć, gdzie jest kryjówka Nieskornych. $N, mój zwiadowca donosi, że na drogach między Księżycowym Potokiem, Kamieniołomem Złotego Wybrzeża i Kopalnią Jangolode widziano posłańca Nieskornych. Chcę, żebyś go $gpojmał:pojmała;. Jeśli będzie się stawiał, zabij go i przynieś mi wszystko, co ma przy sobie.', 'Wytrop posłańca Nieskornych w Zachodnim Skraju i przynieś jego wiadomość Mocnopłaszczowi.', '', 'Wróć do Gryana Mocnopłaszcza na Wzgórze Strażnicze w Zachodnim Skraju.', '', '', '', '', 0),
(155, 'plPL', 'Bractwo Nieskornych', 'Więc Mocnopłaszcz przysyła takie chuchro jak ty, żeby mnie chroniło? Cóż, musi wystarczyć. Lepiej weź też paru przyjaciół.$b$bZnasz umowę, co? Pilnujesz moich pleców, a ja zaprowadzę cię do kryjówki Nieskornych. Ale trzymaj się blisko mnie. Banda Nieskornych chce teraz mojej głowy. Jak zobaczą mnie z tobą, spróbują mnie zabić.$b$bDaj znać, kiedy ty i przyjaciele, których uda ci się zebrać, będziecie gotowi do drogi.', 'Eskortuj zdrajcę Nieskornych do tajnej kryjówki Bractwa Nieskornych. Gdy zdrajca pokaże ci, gdzie ukrywa się VanCleef i jego ludzie, wróć z tą informacją do Gryana Mocnopłaszcza.', 'Eskortuj zdrajcę Nieskornych, aby odkryć, gdzie ukrywa się VanCleef', 'Wróć do Gryana Mocnopłaszcza na Wzgórze Strażnicze w Zachodnim Skraju.', '', '', '', '', 0),
(166, 'plPL', 'Bractwo Nieskornych', 'Zostało ci tylko jedno zadanie. Edwin VanCleef musi zginąć. Choć smuci mnie skazywanie kogokolwiek na śmierć, dla dobra mieszkańców Zachodniego Skraju VanCleef musi raz na zawsze spocząć w grobie. Gdy to zrobisz, przynieś mi głowę tego łotra.', 'Zabij Edwina VanCleefa i przynieś jego głowę Gryanowi Mocnopłaszczowi.', '', 'Wróć do Gryana Mocnopłaszcza na Wzgórze Strażnicze w Zachodnim Skraju.', '', '', '', '', 0),
(167, 'plPL', 'Och, bracie...', 'Byliśmy głęboko w ogromnej kopalni w Zachodnim Skraju, ukrytej pod stodołą w Księżycowym Potoku. Nie mam pojęcia, skąd się wzięły te śmierdzące złodziejskie typy. W każdym razie tunel zawalił się nam na głowy. Ja się wydostałem, ale pozostali... cóż... o pozostałych nikt więcej nie słyszał.$b$bWyglądasz na kogoś, komu może tam lepiej pójść. Jeśli poszukasz mojego brata, będę ci wdzięczny. Zawsze nosił przy sobie odznakę Ligi Odkrywców. Jeśli go nie znajdziesz, ta odznaka przynajmniej da mi trochę spokoju.', 'Przynieś odznakę Ligi Odkrywców brygadzisty Ostopokrzywa Wilderowi Ostopokrzywowi w Wichrogrodzie.', '', 'Wróć do Wildera Ostopokrzywa w Wichrogrodzie.', '', '', '', '', 0),
(168, 'plPL', 'Zbieranie wspomnień', 'Wielu moich przyjaciół zginęło tego strasznego dnia, gdy zawalił się tunel. Jeśli przygody zaprowadzą cię do tamtego skrzydła kopalni w Księżycowym Potoku, wypatruj wszystkiego, co mogłoby pomóc ich zidentyfikować. Jeśli natkniesz się na ich legitymacje Związku Górników, przynieś mi je, a dopilnuję, żeby ich rodziny wreszcie poznały prawdę o tym strasznym wypadku.', 'Zdobądź 4 legitymacje Związku Górników i zanieś je Wilderowi Ostopokrzywowi w Wichrogrodzie.', '', 'Wróć do Wildera Ostopokrzywa w Wichrogrodzie.', '', '', '', '', 0),
(171, 'plPL', 'Opiekun z Przymierza', '$GByłeś:Byłaś; dla mnie $gtaki dobry:taka dobra;, $N. Nawet mi się nie śniło, że w Tygodniu Dziecka będzie tyle zabawy. Dziękuję. Nie chcę się smucić tym, co mnie spotkało i w ogóle – rodzice zawsze mi powtarzali, żeby nie dać się złym rzeczom, które się przytrafiają. Wiesz, jak dorosnę, chcę zostać bohaterem... takim jak ty.$B$BSmutno mi to mówić, ale czas już wracać do domu. Chodźmy, a ja opowiem opiekunce, jak super z ciebie osoba!', 'Odprowadź swojego podopiecznego do sierocińca w Wichrogrodzie, oddając gwizdek ludzkiej sieroty opiekunce sierocińca Nightingale w Dzielnicy Katedralnej.', '', 'Wróć do opiekunki sierocińca Nightingale w Wichrogrodzie.', '', '', '', '', 0),
(212, 'plPL', 'Danie na zimno', 'Jednym z moich najsłynniejszych dań jest schłodzony bazyliszek w winegrecie limonkowym. Kłopot w tym, że... tego mięsa nie da się utrzymać w świeżości, a dziś wieczorem muszę podać to danie na urodzinach pewnego szlachcica!$B$BJeśli więc szybko przyniesiesz mi schłodzony udziec bazyliszka ze świeżo zabitego zimnookiego bazyliszka, będę ci winien królewską ucztę!$B$BZimnookie bazyliszki podobno wędrują po nadmorskich wydmach w północno-zachodniej Dolinie Cierniodławów, więc czeka cię długa podróż. I pośpiesz się!', 'Zabij zimnookiego bazyliszka, zdobądź schłodzony udziec bazyliszka i zanieś go Angusowi Sternowi w „Błękitnym Samotniku”.', '', 'Wróć do Angusa Sterna nad Lustrzanym Jeziorem w Kniei Elwynn.', '', '', '', '', 0),
(220, 'plPL', 'Zew wody', 'Islen ma dla ciebie jeszcze jedno zadanie, zanim nagrodzi cię kolejnym totemem. Fiolka wody, którą ci dałam, będzie do niego potrzebna, jakiekolwiek by ono było.$B$BIdź teraz i ją odnajdź. Kiedyś jeszcze się spotkamy.', 'Zanieś fiolkę najczystszej wody Islen Wodowieszczce na Schodach Tidusa na Pustkowiach.', '', '', '', '', '', '', 0),
(269, 'plPL', 'W poszukiwaniu mądrości', 'Udaj się do Wichrogrodu i porozmawiaj z biskupem Farthingiem w Katedrze Światła. Daj mu dziennik Dygota i powiedz, że zamierzasz zmierzyć się z Morbentem Felem.$B$BChoć Wichrogród porzucił Mroczne Włości, Farthing to dobra dusza i bardzo mądry człowiek. Może pomóc ci w twojej misji ratowania nas.$B$BTwoje zadanie jest niebezpieczne, ale pośpiesz się, $N. Z każdą godziną cienie Kniei Zmierzchu gęstnieją coraz bardziej.', 'Daj ukończony dziennik Dygota biskupowi Farthingowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(270, 'plPL', 'Przeklęta flota', 'Przed laty Trzecia Flota Kul Tiras zatonęła u wybrzeży Bagnisk, rozległych moczarów na północ od krasnoludzkiego królestwa Żelaznej Kuźni. Na pokładzie jednego ze statków znajdował się ładunek żelaza z kuźni światła.$B$BTen metal jest dla nas cenny, bo wykuta z niego broń uderza świętą prawdą. Jeśli masz zmierzyć się z Morbentem Felem, będziesz potrzebować takiej broni.$B$BUdaj się do Przystani Menethilów i porozmawiaj z moim krasnoludzkim towarzyszem, Glorinem Stalobrwym. Jeśli ten zaginiony metal da się odnaleźć, on będzie wiedział, gdzie szukać.', 'Udaj się do Przystani Menethilów na Bagniskach i porozmawiaj z Glorinem Stalobrwym.', '', '', '', '', '', '', 0),
(293, 'plPL', 'Oczyszczenie oka', 'Nie potrafię zdjąć klątwy z Oka Paletha. Oczy Paletha wykonali ludzcy kapłani, więc musisz udać się do Wichrogrodu i tam poszukać pomocy. Porozmawiaj z arcybiskupem Benedyktem. Stoi na czele Katedry Światła w Wichrogrodzie. On może pomóc.$B$BMam taką nadzieję, przez wzgląd na ciebie.', 'Zanieś przeklęte oko Paletha arcybiskupowi Benedyktowi. Benedykt przebywa w Katedrze Światła w Wichrogrodzie.', '', '', '', '', '', '', 0),
(322, 'plPL', 'Błogosławiony oręż', 'W Dzielnicy Krasnoludów w Wichrogrodzie mieszka krasnoludzki kowal broni, który potrafi pracować z żelazem z kuźni światła. Nazywa się Grimand Elmore.$B$BZapakowałem znalezione przez ciebie żelazo do skrzynki. Zanieś ją Grimandowi i opowiedz mu swoją historię. Jestem pewien, że pomoże komuś, kto wypełnia taką misję jak twoja, i wykuje dla ciebie broń – broń, która zaniepokoi nawet Morbenta Fela!', 'Zanieś skrzynkę sztabek z kuźni światła Grimandowi Elmore\'owi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(325, 'plPL', 'W pełnej gotowości', 'Oto broń przeciwko temu potworowi, o którym $gmówiłeś:mówiłaś;. Jesteś $ggotów:gotowa;, $N. Powodzenia! Nie mogę się doczekać opowieści o twojej chwale!', 'Zanieś Zgubę Morbenta Svenowi w Kniei Zmierzchu.', '', '', '', '', '', '', 0),
(332, 'plPL', 'Reklama winiarni', 'Jeśli rozmawiasz z kimkolwiek o winie, to wiesz, że my, Gallinowie, sprzedajemy najlepsze wino w Wichrogrodzie. A mamy niedaleko – wciąż w Dzielnicy Handlowej, nad uroczymi miejskimi kanałami.$B$BProszę, weź tę ulotkę. Zanieś ją mojej siostrze Suzetcie do naszego sklepu, a dostaniesz w prezencie butelkę naszego słynnego pinot noir. Nie pożałujesz!', 'Udaj się do Winiarni Gallinów i oddaj Suzetcie Gallinie talon na wino, by otrzymać darmową butelkę wina.', '', '', '', '', '', '', 0),
(333, 'plPL', 'Harlan potrzebuje dostawy', 'Ostatnio mamy mnóstwo klientów. Wygląda na to, że wszyscy kupują zbroje i mocne ubrania. Zupełnie jakby spodziewali się zimnej, ciężkiej pory roku...$B$BAle to zmartwienia na przyszłość. Dziś martwi mnie to, że kończy mi się dziana odzież na sprzedaż. Potrzebuję kolejnego transportu od naszego dostawcy.$B$BJeśli zaniesiesz to zamówienie Remie Schneider do pracowni „Krawiec i Przymiarki nad Kanałem”, będę ci bardzo wdzięczny.', 'Udaj się do pracowni krawieckiej nad kanałem i zanieś Remie Schneider zamówienie na tkaninę od Harlana Bagleya.', '', '', '', '', '', '', 0),
(334, 'plPL', 'Paczka dla Thurmana', 'Mój syn Thurman terminuje w „Odzieży Larsona” w Dzielnicy Magów. Dziś bardzo się śpieszył i zapomniał nożyc i igieł. Wiem, że ktoś tak wspaniały jak ty ma pewnie na głowie ważne sprawy, ale bez narzędzi Thurman nie może wykonywać swojej pracy ucznia!$B$BProszę, $N. Zaniesiesz mu jego przybornik krawiecki? „Odzież Larsona” to jeden z dwóch sklepów odzieżowych w Dzielnicy Magów – ten położony dalej w głębi, przy wieży magów.', 'Udaj się do „Odzieży Larsona” w Dzielnicy Magów w Wichrogrodzie i oddaj Thurmanowi Schneiderowi jego przybornik krawiecki.', '', '', '', '', '', '', 0),
(335, 'plPL', 'Szlachetny trunek', 'Lord Wishock robi niezłe zamieszanie w Izbie Szlachty. Dowiedział się o naszym małym „przybytku” tu, na dole, i zabiega o wszczęcie pełnego śledztwa. Mam plan, jak zapewnić Wishockowi „zajęcie”, ale będę potrzebował twojej pomocy.$b$bW Ogrodzie Stalvana na obrzeżach Mrocznych Włości rośnie pewien kwiat. Ten mały biały kwiat znany jest jako Łza Tilloi. Potrzebuję też korzenia piżmaka, który rośnie wyłącznie u samego podnóża wodospadu, daleko poniżej Kamiennej Tamy na Bagniskach.', 'Zardeth z Czarnego Szponu chce, żebyś $gprzyniósł:przyniosła; mu Łzę Tilloi z Mrocznych Włości i korzeń piżmaka z Bagnisk.', '', 'Wróć do Zardetha z Czarnego Szponu w Wichrogrodzie.', '', '', '', '', 0),
(336, 'plPL', 'Szlachetny trunek', 'Lord Wishock, jak każdy człowiek, ma swoje słabości. Jego słabością jest zamiłowanie do trunków. Ta hipokryzja jest zdumiewająca. Ten nadęty głupiec całe dnie próbuje zamknąć naszą małą „tawernę”, a noce spędza na górze, nabijając rachunek, którego nigdy nie płaci. Cóż, zobaczmy, jak Wishockowi zasmakuje specjalny trunek, który dla niego przygotowałem: mocne piwo Czarnego Szponu. Ma niezłego kopa, $n.$b$bZanieś mu je i zobacz, jak mu smakuje. Ten stary głupiec najpewniej kręci się po Sali Petentów.', 'Zanieś mocne piwo Czarnego Szponu lordowi Wishockowi w Sali Petentów.', '', '', '', '', '', '', 0),
(337, 'plPL', 'Stara księga historyczna', 'Choć okładka tej księgi jest porysowana i oblepiona błotem, na grzbiecie wciąż da się odczytać tytuł „Historia Wichrogrodu”. Po otwarciu księgi na pierwszej stronie wyraźnie widać pieczęć Biblioteki Wichrogrodu.$B$BWygląda na to, że ktoś ją wypożyczył i nigdy nie oddał...', 'Zwróć księgę „Historia Wichrogrodu” do Biblioteki Wichrogrodu.', '', '', '', '', '', '', 0),
(343, 'plPL', 'Mowa o harcie', 'Wygłaszam przemowę o harcie ducha i chciałbym przytoczyć fragmenty pewnej książki o metalurgii – „Naprężenia żelaza”. Egzemplarz tej książki powinien się znajdować w Bibliotece Królewskiej w Twierdzy Wichrogród. Możesz mi go przynieść? Jeśli tak, niech błogosławieństwo Światłości będzie z tobą!$B$BBiblioteka Królewska jest ogromna, ale główny bibliotekarz, Milton Sheaf, zna każdą półkę jak własnego syna. Porozmawiaj z nim, on znajdzie dla ciebie tę książkę.', 'Udaj się do Biblioteki Królewskiej w Twierdzy Wichrogród i porozmawiaj z Miltonem Sheafem. Znajdzie dla ciebie książkę o metalurgii, której brat Kristoff potrzebuje do swojej przemowy.', '', '', '', '', '', '', 0),
(350, 'plPL', 'Zwróć się do starego przyjaciela', 'Że Marzon kontaktuje się z kimś z Nieskornych i ma powiązania z Lescovarem...$B$BSkoro $gzabiłeś:zabiłaś; VanCleefa i Thredda, trudno będzie postawić Lescovara przed sądem, bo bez ich zeznań twoje dowody są nic niewarte. Nie mówiąc już o tym, że Lescovar jest szlachcicem i ma rozległe koneksje. W praktyce stawia go to ponad prawem.$B$BBędziesz potrzebować innej pomocy. Bardzo niechętnie to robię, ale znam kogoś, kto nam pomoże. Triasa znajdziesz w Dzielnicy Handlowej.', 'Porozmawiaj z Ellingiem Triasem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(353, 'plPL', 'Przesyłka dla Gromdardy', 'Gromdardowie to szanowany krasnoludzki klan, słynący z wyrafinowanego i wybrednego gustu. Nic więc dziwnego, że Gringer Gromdarda, górski strażnik z Żelaznej Kuźni, zamówił u mnie broń.$B$BBroń jest gotowa, ale... górski strażnik Gromdarda jest daleko stąd, w odległym Loch Modan. Jeśli wybierasz się na północ, możesz dostarczyć mu tę paczkę?$B$BW ostatniej wiadomości górski strażnik Gromdarda pisał, że stacjonuje w północnej wieży strażniczej w Loch Modan.', 'Dostarcz paczkę dla Gromdardy górskiemu strażnikowi Gromdardzie w Loch Modan.', '', '', '', '', '', '', 0),
(373, 'plPL', 'Niewysłany list', 'Przeszukując ciało Edwina VanCleefa, znajdujesz między innymi niewysłany list. Jest zaadresowany do Barosa Alexstona, architekta miejskiego Wichrogrodu, Ratusz, Plac Katedralny.$B$BWygląda na to, że został niedawno napisany i zapieczętowany.', 'Dostarcz list do architekta miejskiego Barosowi Alexstonowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(387, 'plPL', 'Stłum bunt', 'Bunt trzeba stłumić! Potrzebuję twojej pomocy. Jeśli rozniesie się, że więźniowie opanowali więzienie, stracę posadę! Ktoś tu maczał palce, jestem tego pewien. Ale teraz najważniejsze jest zmuszenie więźniów do posłuszeństwa, dla bezpieczeństwa Wichrogrodu.$b$bKarą za bunt jest śmierć. Zabij kilku z tych wykolejeńców! To powinno opanować sytuację.', 'Strażnik Thelwater z Wichrogrodu chce, żebyś $gzabił:zabiła; w Kazamatach 10 więźniów z Nieskornych, 8 skazańców z Nieskornych i 8 buntowników z Nieskornych.', '', 'Wróć do strażnika Thelwatera w Wichrogrodzie.', '', '', '', '', 0),
(388, 'plPL', 'Kolor krwi', 'Gorycz płynie w moich żyłach jak zimna rzeka. Mój wnuk, Mac, był takim dobrym chłopcem. Miał zaledwie 14 lat. Kiedy armię wysłano na front, Mac chwycił za broń, by bronić miasta. Był strażnikiem w Kazamatach, gdzie trzymają bandę Nieskornych. Mac upomniał kilku więźniów, którzy darli wełniane koce, żeby robić z nich chusty – symbol ich bandy. Za to dostał nóż w plecy.$b$bPragnę zemsty. Przynieś mi 10 tych ich cennych wełnianych chust. Mają kolor krwi.', 'Nikova Raskol z Wichrogrodu chce, żebyś $gzebrał:zebrała; 10 czerwonych wełnianych chust.', '', 'Wróć do Nikovy Raskol na Starym Mieście w Wichrogrodzie.', '', '', '', '', 0),
(389, 'plPL', 'Bazil Thredd', 'VanCleef i ja byliśmy członkami Gildii Kamieniarzy. Naszym głównym zadaniem była odbudowa Wichrogrodu po wojnie.$B$BGdy wypełniliśmy swoje obowiązki, oszukano nas. Szlachta odmówiła zapłaty za naszą pracę. Kilku starszym kamieniarzom zaproponowano posady w administracji, ale VanCleef odmówił z lojalności wobec wszystkich kamieniarzy. Wszczął rozruchy i opuścił miasto, przysięgając zemstę.$b$bJego zastępca, Bazil Thredd, może wiedzieć więcej o planach VanCleefa. Jest przetrzymywany w Kazamatach.', 'Porozmawiaj ze strażnikiem Thelwaterem w Kazamatach.', '', '', '', '', '', '', 0),
(391, 'plPL', 'Bunt w Kazamatach', 'Postawmy sprawę jasno, $N: nie ufam ci. Ale w obecnej sytuacji i tak pewnie niczego nie zmienisz.$B$BWięc będzie tak: idź na dół i pogadaj sobie z Threddem. Jeśli naprawdę jesteś po naszej stronie, zabij go, a gdy skończysz, przynieś mi jego głowę. A jeśli okaże się, że jesteś po jego stronie, i nie wyjdziesz... kiedy cię znajdziemy, zginiesz razem z resztą tego robactwa.', 'Zabij Bazila Thredda i przynieś jego głowę strażnikowi Thelwaterowi w Kazamatach.', '', 'Wróć do strażnika Thelwatera w Wichrogrodzie.', '', '', '', '', 0),
(392, 'plPL', 'Osobliwy gość', 'Przez pierwsze lata odsiadki Thredda nikt go nie odwiedzał. Uznałem, że Bractwo nie ma już z niego pożytku i o nim zapomniało.$B$BW każdym razie kilka miesięcy temu to się zmieniło – zaczął mieć regularne wizyty... raz, może dwa razy w tygodniu. Odwiedzał go dziwny człowiek – z tych małomównych. Miałem swoje podejrzenia, ale wszystkie jego papiery były w porządku.$B$BWedług dokumentów nazywał się Maelik – oto jego rysopis. Nie sądzę, żeby jeszcze kiedyś odwiedził Thredda.', 'Zanieś zapieczętowany rysopis gościa Thredda Barosowi Alexstonowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(393, 'plPL', 'Cień przeszłości', 'Naprawdę nie mam pojęcia, $N. Jest ktoś jeszcze, kto może ci pomóc, i tak się składa, że jest mi winien przysługę za... zresztą nieważne. Mistrza Mathiasa Shawa z WW:7 znajdziesz w koszarach na Starym Mieście. Shaw trzyma rękę na pulsie większości podejrzanych i nieczystych interesów w mieście.$B$BJeśli ktoś wie, to właśnie on.', 'Zanieś zapieczętowany rysopis gościa Thredda mistrzowi Mathiasowi Shawowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(394, 'plPL', 'Głowa bestii', 'Znajdź Shawa na Starym Mieście. Powiedz mu, że zagrożenie ze strony Lescovara zostało zażegnane, i opowiedz o swoim udziale w sprawie spisków lorda przeciwko miastu. Na pewno będzie dumny, że wśród obywateli Wichrogrodu jest $gkolejny bohater:kolejna bohaterka;.$B$BNajpewniej wyśle cię na spotkanie z księciem albo jakimś innym szlachcicem. Tylko nie pozwól, żeby uderzyło ci to do głowy, $N. Szlachta może sobie myśleć, że rządzi miastem, ale niektóre sprawy pozostają poza jej zasięgiem.', 'Porozmawiaj z Mathiasem Shawem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(395, 'plPL', 'Koniec Bractwa', 'Ach, prawie zapomniałem. Pod twoją nieobecność przyszedł Alexston, chciał z tobą porozmawiać. Bez wątpienia chce zdać szlachcie relację z poczynań Bractwa Nieskornych.$B$BMała rada, $N: gdyby ktoś pytał, podaj wszystkie szczegóły poza tym, że to twoja ręka zabiła Lescovara. Zaufaj mi. Jestem... obeznany... z takimi sprawami.$B$BA co do Triasa, cóż, nie mów o nim nikomu... nigdy... jeśli tylko możesz tego uniknąć.', 'Porozmawiaj z Barosem Alexstonem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(396, 'plPL', 'Audiencja u króla', 'Przygotowałem raport dla króla. Uważam, że to ty $gpowinieneś:powinnaś; mu go dostarczyć wraz z relacją z tego, co $godkryłeś:odkryłaś;. Nie martw się, król z pewnością pochwali cię za wypełnienie obowiązku wobec mieszkańców Wichrogrodu.$B$BTwoja audiencja odbędzie się niebawem, więc lepiej się pośpiesz – do Twierdzy Wichrogród jest spory kawałek drogi.', 'Dostarcz raport Barosa Alexstona o Bractwie Nieskornych królowi Varianowi Wrynnowi w Twierdzy Wichrogród.', '', '', '', '', '', '', 0),
(397, 'plPL', 'Wierna służba', 'Słyszałem, że lordowi Wishockowi zasmakował jego trunek.$b$bDobrze nam $gsłużyłeś:służyłaś;, $N. Dzięki tobie my, czarnoksiężnicy Wichrogrodu, będziemy mogli bez przeszkód praktykować naszą sztukę. W nagrodę za twoje wysiłki przygotowałem dla ciebie specjalny dar. Porozmawiaj z moim sługą – nazywa się Zggi – i odbierz nagrodę.', 'Porozmawiaj ze sługą Zardetha z Czarnego Szponu, który nazywa się Zggi, i odbierz nagrodę.', '', '', '', '', '', '', 0),
(399, 'plPL', 'Skromne początki', 'Wydaje się, że minęła wieczność, odkąd jako chłopiec pracowałem na farmie w Zachodnim Skraju. Mówią, że do przeszłości nie ma powrotu, i to prawda. W moim przypadku podwójna – dom mojej rodziny spłonął i zajęli go złodzieje.$b$bRozmawiałem z ojcem o losie niektórych moich rzeczy, w tym mojego pierwszego kompasu. Nie zdołał ich uratować. Mówi jednak, że powinny być gdzieś ukryte w gospodarstwie.$b$bGospodarstwo Alexstona znajdziesz na zachód od Wzgórza Strażniczego. Może $gmógłbyś:mogłabyś; się tam wybrać i odzyskać dla mnie kompas?', 'Udaj się do domu Barosa Alexstona w Zachodnim Skraju, poszukaj jego kompasu, a potem zanieś mu go na Plac Katedralny w Wichrogrodzie.', '', 'Wróć do Barosa Alexstona w Wichrogrodzie.', '', '', '', '', 0),
(434, 'plPL', 'Atak!', 'Kiedy przebiorę szpiegobota, pójdzie porozmawiać z Lescovarem. Strażnicy powinni go bez problemu przepuścić.$B$BGdy $gzbierałeś:zbierałaś; dla mnie materiały, zająłem się powiadomieniem Marzona, że nadszedł czas na jego kolejne spotkanie z Lescovarem. Podrzuciłem nawet trochę fałszywych informacji.$B$BLescovar odprawi strażników i będzie czekał na Marzona tutaj, w ogrodzie. Gdy usłyszysz rozmowę o Nieskornych, do dzieła. Musisz zabić ich obu, zanim strażnicy wrócą! Kiedy skończysz, porozmawiaj z Triasem.', 'Zostań w ogrodzie, dopóki lord Gregor Lescovar i Marzon Ciche Ostrze nie odbędą rozmowy. Potem zabij ich obu i wróć do Ellinga Triasa w Wichrogrodzie.', 'Podsłuchaj rozmowę Lescovara z Marzonem', 'Wróć do Ellinga Triasa w Wichrogrodzie.', '', '', '', '', 0),
(538, 'plPL', 'Południowy Brzeg', '$N. Jeśli nie przeszkadza ci długa podróż, mam dla ciebie zadanie – znów pomożesz Wichrogrodowi uzupełnić bibliotekę.$B$BDawne królestwo Alterak upadło po wielkiej wojnie, a miało pokaźny księgozbiór. To tragedia, że miasto legło w gruzach, ale jeszcze większą tragedią jest utrata całej jego wiedzy! Musimy odzyskać, co się da.$B$BPołudniowy Brzeg to miasteczko położone najbliżej Ruin Alterak. Udaj się tam i porozmawiaj z mistrzem wiedzy Dibbsem. Wskaże ci drogę do ruin i powie, jakie księgi można tam znaleźć.', 'Porozmawiaj z mistrzem wiedzy Dibbsem w Południowym Brzegu.', '', '', '', '', '', '', 0),
(540, 'plPL', 'Ocalić wiedzę', 'Te bestialskie ogry zamieszkują teraz ruiny Alterak i drżę na myśl, co robią z cennymi księgami, które tam zostały. Musisz odzyskać, co się da!$B$BWejdź do Ruin Alterak i poszukaj ksiąg zrabowanych przez ogry. Zabierz wszystko, co znajdziesz, i przynieś mi, ale szukaj też jednej konkretnej księgi: „Ramię Gri\'leka”. Zawiera starożytną wiedzę trolli, którą muszę poznać, a Ruiny Alterak to ostatnie znane miejsce, gdzie znajdował się nienaruszony egzemplarz tej księgi.', 'Przynieś 5 odzyskanych ksiąg oraz zniszczoną skórzaną księgę zawierającą „Ramię Gri\'leka” mistrzowi wiedzy Dibbsowi w Południowym Brzegu.', '', 'Wróć do mistrza wiedzy Dibbsa w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(542, 'plPL', 'Powrót do Miltona', 'Muszę poświęcić trochę czasu na studiowanie „Ramienia Gri\'leka”, które mi $gprzyniosłeś:przyniosłaś;, choć jestem pewien, że Milton nie może się doczekać, aż pozostałe odzyskane księgi trafią do zbiorów Wichrogrodu.$B$BOto księgi, które $gzebrałeś:zebrałaś; w Ruinach Alterak – spakowane i skatalogowane. Zanieś je Miltonowi Sheafowi w Wichrogrodzie, na pewno będzie ci wdzięczny.', 'Zanieś księgi z Alterak Miltonowi Sheafowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(543, 'plPL', 'Tiara Perenolde\'ów', 'Tiara Perenolde\'ów to dawna pamiątka rodowa „szlachetnych” Perenolde\'ów – rodu, który panował w Alterak, zanim królestwo popadło w ruinę. Podobno wykonali ją mistrzowie jubilerscy z Żelaznej Kuźni i wysadzili najprzedniejszymi szmaragdami.$B$BGdy królestwo Alterak zostało zniszczone, tiara zaginęła, ale krążą plotki, że ogrzy mag, Grel\'borg Skąpiec, znalazł ją i teraz przemierza Ruiny Alterak w poszukiwaniu kolejnych skarbów.$B$BChcemy, żebyś $gzdobył:zdobyła; dla nas tę tiarę.', 'Przynieś tiarę Perenolde\'ów Remingtonowi Ridgewellowi w Wichrogrodzie.', '', 'Wróć do hrabiego Remingtona Ridgewella w Twierdzy Wichrogród w Wichrogrodzie', '', '', '', '', 0),
(563, 'plPL', 'Przeniesienie', 'Nie powinno być problemu z tym, żeby mój raport trafił do właściwych rąk. Nowy kapitan straży, major Samuelson, był moim mentorem, gdy stacjonowałem w Wichrogrodzie. To da mu aż nadto pretekstu, by przenieść mnie z powrotem do miasta. Musisz jednak zanieść mu mój raport... nie chciałbym, żeby stary Redpath się zorientował.', 'Dostarcz raport Farrena majorowi Samuelsonowi w Twierdzy Wichrogród.', '', '', '', '', '', '', 0),
(579, 'plPL', 'Biblioteka Wichrogrodu', '', '', '', 'Wróć do Donyala Tovalda w Kniei Elwynn.', '', '', '', '', 0),
(690, 'plPL', 'Prośba Malina', 'Witaj, $N. Wyglądasz na $gposzukiwacza:poszukiwaczkę; przygód, a ja mam zadanie, którym trzeba się zająć.$B$BArcymag Trelane, mój pierwszy mistrz, niedawno uciekł ze Stromgardu na Wyżynach Aratorskich i poprosił mnie o pomoc w odzyskaniu części rzeczy, które tam zostawił.$B$BMiasto zostało oblężone, a on próbował bronić Wieży Aratoru, lecz na próżno. Mam już na wyżynach swoich agentów, ale proszą o dodatkowe wsparcie. Jesteś $gzainteresowany:zainteresowana;?', 'Odnajdź Skuerta w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(697, 'plPL', 'Prośba Malina', 'Zanieś ten list do Wichrogrodu i daj znać Malinowi, że Kryten i ja niedługo wrócimy do domu. Sowicie cię wynagrodzi za pomoc, $N, co do tego nie mam wątpliwości.$B$BBezpiecznej drogi.', 'Zanieś zapieczętowany list arcymagowi Malinowi w Dzielnicy Magów w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1015, 'plPL', 'Nowe rubieże', 'Uwaga, bohaterowie!$B$BKrąg Cenariona szuka sprawnych ochotników, którzy pomogą mu badać rozległe, nowe rubieże Kalimdoru! Daleko na zachód od Tanaris i Gadżetonu leży zakazane pustkowie pełne niewyobrażalnych niebezpieczeństw, a Krąg potrzebuje chętnych i honorowych wysłanników, którzy będą działać w jego imieniu.$B$BWszyscy zainteresowani powinni zgłosić się do Kręgu Cenariona. Po więcej informacji udajcie się do arcydruida Fandrala Jeleniorogiego w Darnassus!', 'Porozmawiaj z arcydruidem Fandralem Jeleniorogim w Enklawie Cenariona w Darnassus o wezwaniu Kręgu Cenariona do badania rubieży Kalimdoru.', '', '', '', '', '', '', 0),
(1019, 'plPL', 'Nowe rubieże', 'Uwaga, bohaterowie!$B$BKrąg Cenariona szuka sprawnych ochotników, którzy pomogą mu badać rozległe, nowe rubieże Kalimdoru! Daleko na zachód od Tanaris i Gadżetonu leży zakazane pustkowie pełne niewyobrażalnych niebezpieczeństw, a Krąg potrzebuje chętnych i honorowych wysłanników, którzy będą działać w jego imieniu.$B$BWszyscy zainteresowani powinni zgłosić się do Kręgu Cenariona. Po więcej informacji udajcie się do arcydruida Fandrala Jeleniorogiego w Darnassus!', 'Porozmawiaj z arcydruidem Fandralem Jeleniorogim w Enklawie Cenariona w Darnassus o wezwaniu Kręgu Cenariona do badania rubieży Kalimdoru.', '', '', '', '', '', '', 0),
(1047, 'plPL', 'Nowe rubieże', 'Uwaga, bohaterowie!$B$BKrąg Cenariona szuka sprawnych ochotników, którzy pomogą mu badać rozległe, nowe rubieże Kalimdoru! Daleko na zachód od Tanaris i Gadżetonu leży zakazane pustkowie pełne niewyobrażalnych niebezpieczeństw, a Krąg potrzebuje chętnych i honorowych wysłanników, którzy będą działać w jego imieniu.$B$BWszyscy zainteresowani powinni zgłosić się do Kręgu Cenariona. Po więcej informacji udajcie się do arcydruida Fandrala Jeleniorogiego w Darnassus!', 'Porozmawiaj z arcydruidem Fandralem Jeleniorogim w Enklawie Cenariona w Darnassus o wezwaniu Kręgu Cenariona do badania rubieży Kalimdoru.', '', '', '', '', '', '', 0),
(1075, 'plPL', 'Zwój od Maurena', 'Dobra, teraz część planu ze zdalną detonacją... och, jeszcze tego nie wyjaśniłem, prawda?$B$BNo więc w skrócie: z pomocą odrobiny magii mogę sprawić, że ładunki wybuchną, kiedy będziesz daleko. Składam urządzenie, dzięki któremu wystarczy wcisnąć jeden guzik, a NG-5 wybuchnie, kiedy tylko zechcesz.$B$BAle potrzebuję zaklęcia od przyjaciela z Wichrogrodu – nazywa się Collin Mauren. Znajdziesz go w tamtejszej Dzielnicy Magów. To człowiek, więc łatwo go wypatrzysz.', 'Odnajdź Collina Maurena w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1076, 'plPL', 'Diabliki w Zachodnim Skraju', 'Ach, chyba już wiem. Zaklęcie przesyłania wiadomości... Myślę, że właśnie o taki efekt mu chodzi.$B$BBędę musiał sporządzić zwój z wpisanym w niego zaklęciem. Do tego potrzebuję szczątków pyłowego diablika.$B$BZanim zbiorę resztę składników, może udasz się do Zachodniego Skraju i odszukasz jedno z tych paskudnych stworzeń? Są niebezpieczne, ale skoro jesteś $ggotów:gotowa; poddać się jednemu z eksperymentów Gaxima, na pewno sobie z nimi poradzisz.$B$BBędę tu, kiedy wrócisz.', 'Przynieś szczątki pyłowego diablika Collinowi Maurenowi w Wichrogrodzie.', '', 'Wróć do Collina Maurena w Wichrogrodzie.', '', '', '', '', 0),
(1077, 'plPL', 'Przesyłka specjalna dla Gaxima', 'Proszę, $N. To powinno się sprawdzić.$B$BPozdrów ode mnie Gaxima, kiedy go zobaczysz. Chętnie posłucham o tej przygodzie, gdy dobiegnie końca.$B$BBywaj zdrów.', 'Zanieś zwój wiadomości Gaximowi Rdzawosykowi w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1078, 'plPL', 'Łuski dla Maurena', 'Podróżni ciągle wypytują mnie o Góry Szponogłazy. Wygląda na to, że to popularne miejsce dla poszukiwaczy przygód – nieważne, czy szuka się wywern, żywiołaków, czy ma się interesy ze spółką Gitgeszeft.$B$BW Zwęglonej Dolinie, w głębi Gór Szponogłazów, żył kiedyś gatunek bazyliszków, których łuski, starte na proch, były wspaniałym odczynnikiem do kilku opracowanych przeze mnie zaklęć.$B$BJeśli te bazyliszki wciąż tam żyją, bardzo chętnie zdobyłbym kilka ich łusek.$B$BNie spiesz się, to nic pilnego, ale dobrze zapłacę.', 'Przynieś 8 skrystalizowanych łusek Collinowi Maurenowi w Wichrogrodzie.', '', 'Wróć do Collina Maurena w Wichrogrodzie.', '', '', '', '', 0),
(1241, 'plPL', 'Zaginiony dyplomata', 'Niedawno wysłano do Theramore dyplomatę na spotkanie z Jainą Proudmoore. Ten dyplomata nigdy tam nie dotarł.$B$BPodejrzewam, że maczali w tym palce Nieskorni, ale nie wiem, w jaki sposób. Zniknięcie dyplomaty wciąż umyka uwadze opinii publicznej, ale to nie potrwa długo.$B$BAgenci króla już przeczesują miasto w poszukiwaniu tropów, ale chciałbym włączyć do sprawy także własne kontakty.$B$BW Dolinie Bohaterów przebywa mój stary przyjaciel, Jorgen. Znajdź go, daj mu ten liścik i postępuj zgodnie z jego wskazówkami.', 'Odnajdź Jorgena w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1242, 'plPL', 'Zaginiony dyplomata', 'Zanieś ten tu liścik Ellingowi Triasowi. Nic więcej mu nie gadaj. Bądź $guprzejmy:uprzejma; i czekaj, aż odpowie. I nie martw się, odpowie.$B$BPowtórzę ci to już tylko raz, $N: traktuj tę sprawę poważnie i trzymaj język za zębami.$B$BTriasa znajdziesz w jego sklepie z serami, „Sery Triasa”, w Dzielnicy Handlowej. Powodzenia.', 'Dostarcz zapieczętowany liścik od Jorgena Ellingowi Triasowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1243, 'plPL', 'Zaginiony dyplomata', 'Jorgen, ty stary sukin... A więc tak to ma wyglądać, co?$B$BDobra, jakoś to przełknę. Oby tym prędzej trafił do Wypaczonej Otchłani!$B$BPosłuchaj, jak to będzie, $N. Ja uruchomię tu swoje kontakty, ale większość bieganiny spadnie na ciebie, żebym zaoszczędził trochę grosza.$B$BUdaj się do Mrocznych Włości w Kniei Zmierzchu i odszukaj wartownika Backusa – zwykle patroluje północną drogę tuż za miastem. Powiedz mu po prostu, że na moją prośbę sprawdzasz, co porabiają Nieskorni, a przekaże ci wszystko, co wie.', 'Przekaż zapieczętowany liścik wartownikowi Backusowi w Kniei Zmierzchu.', '', '', '', '', '', '', 0),
(1244, 'plPL', 'Zaginiony dyplomata', 'Działalność Nieskornych? Cóż, zawsze coś się dzieje; nawet jeśli trzymają się na uboczu, uważamy ich za zagrożenie.$B$BAle skoro o tym mowa, niedawno doszło do dość dziwnego zdarzenia. To musiało być ze dwa tygodnie temu – kilku ich agentów zebrało się w okolicy Zagrody Addle\'a. Z raportu wnioskowałem, że wydarzyło się tam coś poważnego.$B$BMoże najpierw tam zajrzysz i przyniesiesz mi wszystko, co znajdziesz?$B$BZagroda leży na południe od drogi z Zachodniego Skraju, zaraz po wejściu do Kniei Zmierzchu.', 'Znajdź rejestr Nieskornych i zanieś go wartownikowi Backusowi w Kniei Zmierzchu.', '', 'Wróć do wartownika Backusa w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(1245, 'plPL', 'Zaginiony dyplomata', 'Oho, to wygląda na zbyt skomplikowane, żeby miało tylko wyprowadzić cię w pole. Nie powinienem nawet na to patrzeć. Zanieś to Triasowi – on się w tym połapie. I NIE pozwól, żeby ktokolwiek wszedł ci w drogę. To mnie przerasta. Może nawet i jego, ale zobaczymy.$B$BI zrób mi przysługę, $N: nikomu nie mów, że ci pomogłem. Gdyby przełożeni się dowiedzieli, że o tym wiedziałem i nic im nie powiedziałem, pewnie by mnie powiesili.', 'Przynieś rejestr Nieskornych Ellingowi Triasowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1246, 'plPL', 'Zaginiony dyplomata', 'No tak, skoro o tym mowa... Dashel... Dashel jakiśtam... Jak on się nazywał? PIĘŚĆ! Dashel Kamieniopięść. W pewnych kręgach mówią na niego Pięść – pewnie dlatego, że lubi się wdawać w bójki.$B$BZwykle znajdziesz go na Starym Mieście – w samym jego środku. Idź z nim pogadać. Jeśli będzie trzeba, użyj miecza albo czegoś ciężkiego i tępego, żeby go trochę rozgadać. I nie wahaj się. Jeśli siedzi w tym tak głęboko, jak wynika z tych papierów, z własnej woli nic ci nie powie.', 'Porozmawiaj z Dashelem Kamieniopięścią w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1247, 'plPL', 'Zaginiony dyplomata', 'No więc tak... eee... może coś tam wiem o tym spotkaniu w Zagrodzie Addle\'a. Było chyba parę tygodni temu. Ja naprawdę nie miałem z tym nic wspólnego. Moja robota skończyła się, jak plan A nie wypalił... przeklęci poszukiwacze przygód.$B$BGość, którego mieli w środku do planu B, przyszedł z Przystani Menethilów; mówią na niego Chudy. Tyle wiem o ich planie awaryjnym.', 'Porozmawiaj z Ellingiem Triasem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1248, 'plPL', 'Zaginiony dyplomata', 'Jeden z moich dawnych kontaktów osiadł na emeryturze na Bagniskach, w portowym mieście Przystań Menethilów. Powinien ci pomóc na samo twoje słowo, jeśli powiesz mu, że pracujesz dla mnie. Nazywa się Mikhail. Kiedy kilka lat temu wyjeżdżał z Wichrogrodu, wspominał, że zostanie karczmarzem.$B$BPorozmawiaj z nim, znajdź tego Chudego i dowiedz się, czy jest coś jeszcze, co powinniśmy wiedzieć o tym porwanym dyplomacie. Musimy ustalić, dokąd go zabrali, albo przynajmniej kim jest. W rejestrze nie ma ani słowa o tym, co zamierzali zrobić po jego pojmaniu.', 'Porozmawiaj z Mikhailem na Bagniskach.', '', '', '', '', '', '', 0),
(1249, 'plPL', 'Zaginiony dyplomata', 'Mówisz, że przysłał cię Elling? W takim razie moja gościnność jest teraz dziesięciokrotnie większa. Czego tylko potrzebujesz, wystarczy poprosić. Zrobię, co w mojej mocy, żeby ci pomóc.$B$BHmm, Chudy, powiadasz? Nie wiem, czy to imię coś mi mówi, ale będę się za nim rozglądał.$B$BTylko się teraz nie odwracaj, $N, ale ten jegomość przy wyjściu patrzy w naszą stronę. Przysłuchuje się naszej rozmowie odrobinę zbyt uważnie, jeśli rozumiesz, co mam na myśli. Na twoim miejscu zrobiłbym wszystko, żeby go obezwładnić, zanim rzuci się do drzwi.', 'Obezwładnij Tapoke Jahna, zanim ucieknie, a potem wróć do Mikhaila w Przystani Menethilów.', 'Pokonaj Tapoke Jahna', 'Wróć do Mikhaila w tawernie „Głęboka Woda” w Przystani Menethilów.', '', '', '', '', 0),
(1250, 'plPL', 'Zaginiony dyplomata', 'Nieskorni nie płacili mi tyle, żebym miał za nich umierać. Porwali króla. Tak, króla Wichrogrodu, a nie jakiegoś podrzędnego dyplomatę. Płynął do Theramore na spotkanie z Jainą Proudmoore – podobno to była wielka sprawa i wielka tajemnica. Ale nie tylko Nieskorni są w to zamieszani. Współpracują z kimś. Chyba wiedzieli, że to ich przerasta.$B$BMoja rola polegała tylko na tym, żeby wprowadzić ich człowieka na pokład królewskiego statku, kiedy stał w porcie. Ten gość nazywał się Hendel. Tylko tyle wiem. Przysięgam!', 'Porozmawiaj z Mikhailem na Bagniskach.', '', '', '', '', '', '', 0),
(1260, 'plPL', 'Morgan Stern', 'Przygotowuję nowe menu dla restauracji. Będzie pełne wiejskich potraw w bagiennym stylu. Myślę, że moim gościom w „Błękitnym Samotniku” bardzo przypadną do gustu!$B$BWysłałem mojego bratanka Morgana do Theramore, miasta na skraju Pyłowego Bagniska. Zbiera tam przepisy od miejscowych, a ja muszę wiedzieć, co dotąd znalazł.$B$BPodróż do Theramore jest długa. Dla mnie za długa. Ale założę się, że ktoś tak młody jak ty chętnie skorzysta z okazji do podróży, prawda?', 'Porozmawiaj z Morganem Sternem w Theramore.', '', '', '', '', '', '', 0),
(1264, 'plPL', 'Zaginiony dyplomata', 'Na początku każdego miesiąca żołnierze piechoty morskiej z Kul Tiras dostają żołd i zwykle wyruszają z Theramore gdzie indziej. Wielu z nich przychodzi tutaj, żeby uganiać się za kobietami, hulać i po prostu dobrze się bawić. Jedną z tych grup zaliczam do stałych bywalców naszej tawerny i sądzę, że jest wśród nich ten Hendel.$B$BDowódca Samaul z Theramore pomoże ci go znaleźć, jeśli Hendel wciąż tam stacjonuje. Jest całkowicie lojalny wobec Proudmoore, ale jeśli rzucisz imieniem Ellinga, powinien ci pomóc... dyskretnie.', 'Odnajdź dowódcę Samaula na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(1265, 'plPL', 'Zaginiony dyplomata', 'Hendel? Tak, znam go. Ale do czego ci jeden z moich żołnierzy?$B$BElling przysłał cię, żebyś go $godnalazł:odnalazła;? Hmm, nie podoba mi się to. Elling nie kazałby ci przychodzić najpierw do mnie, gdyby twoja sprawa nie była poważna. Rozumiem, jeśli nie możesz mi powiedzieć, o co chodzi, ale wiedz jedno: moim obowiązkiem jest chronić te ziemie. Jeśli zamierzasz wywołać zamieszanie, radzę ci powiedzieć mi tyle, ile możesz.$B$BO ile wiem, Hendel stacjonował w pierwszej wieży za Theramore. Bądź $gostrożny:ostrożna;.', 'Poszukaj w Posterunku Strażniczym jakichkolwiek śladów szeregowego Hendela.', 'Posterunek Strażniczy zbadany', 'Wróć do arcymaga Tervosha na Pyłowym Bagnisku.', '', '', '', '', 0),
(1266, 'plPL', 'Zaginiony dyplomata', 'Szeregowy Hendel jest na zachód stąd. Pełni wartę, pilnując odpoczywających infiltratorów z Theramore. Obserwują bazę Hordy w Paprotni i wypatrują wszystkiego, co mogłoby zagrozić naszym granicom.$B$BNie powinno być kłopotu z odnalezieniem go; wystarczy wypatrywać namiotów przy drodze.$B$BMuszę się zająć inną sprawą, ale wkrótce do ciebie dołączę. Gdybyś $gmiał:miała; jakiekolwiek kłopoty, zawsze znajdziesz mnie w wieży lady Proudmoore.', 'Odnajdź szeregowego Hendela na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(1267, 'plPL', 'Zaginiony dyplomata', '', 'Porozmawiaj z Jainą Proudmoore na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(1271, 'plPL', 'Uczta w „Błękitnym Samotniku”', '', '', '', '', '', '', '', '', 0),
(1274, 'plPL', 'Zaginiony dyplomata', 'Przepraszam, $gpanie:pani;. Biskup DeLavey poprosił mnie, żebym zagadywał poszukiwaczy przygód, którzy mogliby mu pomóc w pewnej delikatnej sprawie.$B$BJeśli po cichu udasz się do Twierdzy Wichrogród i porozmawiasz z nim przy najbliższej sposobności, z pewnością doceni twoją pomoc. Raz jeszcze proszę o dyskrecję. To sprawa niemałej wagi.', 'Odnajdź biskupa DeLaveya w Twierdzy Wichrogród.', '', '', '', '', '', '', 0),
(1301, 'plPL', 'James Hyal', 'Zanim zacząłem pracę tutaj, w „Błękitnym Samotniku”, szkolił mnie jeden z najlepszych kucharzy i karczmarzy, jakich w życiu spotkałem. Nazywał się James Hyal. Wszystko, co mam, i wszystko, co w życiu osiągnąłem, zawdzięczam jemu.$b$bCiekawe, jak mu się wiedzie. Razem z bratem, Vincentem, wyjechali do pracy w tawernie w Przystani Menethilów, ale ostatnio nie miałem od niego żadnych wieści.$b$bJeśli kiedyś będziesz w tamtych stronach, może pozdrowisz go ode mnie?', 'Porozmawiaj z Vincentem Hyalem w Przystani Menethilów.', '', '', '', '', '', '', 0),
(1302, 'plPL', 'James Hyal', 'Mój brat James wyruszył z lady Proudmoore za morze. Ostatnio słyszałem, że walki tam przycichły, a James otwierał gdzieś na kontynencie karczmę. Gdziekolwiek jest, na pewno dobrze mu się wiedzie. Diabelnie dobrze gotował.$b$bOd jakiegoś czasu nie mam od niego wieści – pewnie jest zbyt zajęty karczmą – ale urzędnik w Theramore pewnie wskaże ci drogę. Szukaj go na najwyższym piętrze twierdzy w środku miasta. Jak ona się nazywa... Cytadela Przyczółku, tak jest.', 'Porozmawiaj z urzędnikiem Lendrym w Cytadeli Przyczółku w Theramore.', '', '', '', '', '', '', 0),
(1324, 'plPL', 'Zaginiony dyplomata', 'Co?! Przychodzisz tu, oskarżasz mnie o konszachty z Nieskornymi i myślisz, że będę stał i słuchał, jak mnie obrażasz?! Coś mi mówi, że od dawna ci się to należało.', 'Pokonaj szeregowego Hendela na Pyłowym Bagnisku.', 'Obezwładnij szeregowego Hendela', 'Wróć do arcymaga Tervosha na Pyłowym Bagnisku.', '', '', '', '', 0),
(1338, 'plPL', 'Zamówienie Gromdardy', 'Jest pewien krasnoludzki płatnerz, którego prace bardzo podziwiam. Nazywa się Furen Długobrody i nie ma sobie równych. Potrzebuję nowej tarczy i muszę mieć tarczę jego roboty!$B$BKłopot w tym, że Furen jest daleko na południu, w Dzielnicy Krasnoludów w Wichrogrodzie. Na ziemiach ludzi! Nie mam pojęcia, czemu miałby tam mieszkać, tak daleko od Żelaznej Kuźni. Ludzie muszą mu płacić prawdziwą fortunę, żeby go tam zatrzymać!$B$BWięc jeśli masz ochotę na podróż i nie pogardzisz zarobkiem, zaniesiesz Furenowi moje zamówienie na tarczę?', 'Zanieś prośbę Gromdardy Furenowi Długobrodemu w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1363, 'plPL', 'Polecenie Mazena', 'Jako opiekun zbiorów biblioteki Akademii Sztuk i Nauk Tajemnych odpowiadam za to, by wszystkie magiczne księgi i zwoje zawsze były na swoim miejscu. Kto wie, do jakich szaleństw by doszło, gdyby któreś z tych zaczarowanych pism wpadło w niepowołane ręce?$b$bCo mi przypomina... mój asystent, Dellis, popełnił w zeszłym tygodniu straszny błąd. W bibliotece radzi sobie świetnie, ale gdy tylko wyjdzie za bramy Wichrogrodu, jest zupełnie nieporadny. Bądź $gbohaterem:bohaterką; i pomóż staremu Dellisowi, dobrze?', 'Porozmawiaj z akolitą Dellisem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1364, 'plPL', 'Polecenie Mazena', 'Polecenia mistrza Mazena były zupełnie jasne: dostarczyć bardzo ważny esej wartownikowi Mahar Ba w Strażnicy Otchłani.$b$bAle ja nigdy wcześniej nie byłem na Jałowych Ziemiach! Podróż była przerażająca!$b$bKiedy dotarłem do Moczarów Smutków, skręciłem nie tam, gdzie trzeba, i otoczyły mnie okropne bagienne stwory podobne do roślin. Ruszyły na mnie chwiejnie, jakby chciały zaatakować, więc uciekłem. Ale w pośpiechu upuściłem esej. Jestem pewien, że zabrała go któraś z tych bestii.$b$bCzy możesz spróbować go odzyskać i dostarczyć wartownikowi Mahar Ba?', 'Odzyskaj Eseje Khadgara o zbieżności wymiarów i dostarcz je wartownikowi Mahar Ba w Strażnicy Otchłani.', '', 'Wróć do wartownika Mahar Ba w Strażnicy Otchłani na Jałowych Ziemiach.', '', '', '', '', 0),
(1447, 'plPL', 'Zaginiony dyplomata', 'No tak, $gnajbystrzejszym:najbystrzejszą; z tych, co przyłażą do Wichrogrodu, to ty nie jesteś, ale zaraz będziesz $gjednym:jedną; z najgłupszych, którzy już stąd nie wyjdą.$B$B$GPoznałeś:Poznałaś; moich kumpli?', 'Pokonaj Dashela Kamieniopięść w Wichrogrodzie.', 'Pokonaj Dashela Kamieniopięść', 'Porozmawiaj z Dashelem Kamieniopięścią w Wichrogrodzie.', '', '', '', '', 0),
(1448, 'plPL', 'W poszukiwaniu świątyni', 'Kiedyś i ja byłem młody i pełen wigoru, tak jak ty.$b$bAle teraz jestem stary i nie mogę już przemierzać świata jak dawniej. Ach, czego ja nie widziałem!$b$bByła jednak jedna zagadka, której nie zdołałem rozwiązać. W ramach mojej ostatniej wyprawy Liga Odkrywców wysłała mnie na poszukiwanie Świątyni Atal\'Hakkar. Podobno miała się znajdować w Moczarach Smutków.$b$bZe względu na wątłe zdrowie szukałem jej z powietrza, na grzbiecie gryfa, ale nigdy jej nie znalazłem.$b$bPomożesz staremu krasnoludowi? Może tobie, na piechotę, lepiej się poszczęści.', 'Brohann Beczkobrzuch z Wichrogrodu chce, żebyś $godszukał:odszukała; Świątynię Atal\'Hakkar.', 'Odszukaj Świątynię Atal\'Hakkar', 'Wróć do Brohanna Beczkobrzucha w Wichrogrodzie.', '', '', '', '', 0),
(1449, 'plPL', 'Do Zaziemia', 'Jak już wspominałem, próbowałem sam wypatrzyć świątynię z powietrza. Cóż, nie całkiem sam.$b$bUdałem się do słynnej gryfiej ptaszarni w Orlim Gnieździe w Zaziemiu. Tam poprosiłem o pomoc jednego z ich najlepszych lotników. Ten lotnik spadł z wierzchowca prosto w bagno...$b$bNa starość nie mogę sobie przypomnieć imienia biedaka. Ale mistrz ptaszarni na pewno je pamięta.$b$bUdaj się tam i odszukaj Falstada Dzikiego Młota.$b$bMusimy się dowiedzieć, co się stało z tym lotnikiem.', 'Porozmawiaj z wielkim thanem Falstadem Dzikim Młotem w Orlim Gnieździe w Zaziemiu.', '', '', '', '', '', '', 0),
(1469, 'plPL', 'Opowieść Rhapsody\'ego', 'Przed lotem wypiłem całą beczułkę stouta. Hep!$b$bI co to był za lot! Śmigałem w tę i we w tę, a Brohann za mną. Tylko żadnej świątyni nie widziałem. Hep!$b$bZnaczy, nie widziałem, póki się trochę za bardzo nie wstawiłem i nie spadłem z wierzchowca. Wpadłem prosto do wody i coś mnie wciągnęło na dno. Patrzę, a tu wokół banda upiornych trolli. Ale żem stamtąd zwiewał wpław, aż miło! Nawet zwinąłem tę trollową pamiątkę. Masz, zanieś ją Brohannowi i powiedz mu, że jego świątynia naprawdę tam jest, na dnie. Hep!', 'Zanieś fragment tabliczki Atal\'ai Brohannowi Beczkobrzuchowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1471, 'plPL', 'Spętanie', 'Z pewnością $gwidziałeś:widziałaś; krąg przywołań pod nami? Tylko tam zdołasz przywołać niezwiązanego wędrowca Pustki.$b$bZa pomocą tych run go przywołasz, a potem musisz go ujarzmić siłą oręża i magii.$b$bKiedy zostanie poskromiony, będzie ci podległy. Wtedy przyjdź do mnie, a objaśnię ci zaklęcie przywołania, by służył ci w jakimkolwiek celu zechcesz.', 'Za pomocą Run przyzywania przywołaj i ujarzmij wędrowca Pustki, a potem zwróć Runy przyzywania Carendinowi Halgarowi w Dzielnicy Magów w Podmieście.', '', 'Wróć do Carendina Halgara na Polanach Tirisfal.', '', '', '', '', 0),
(1472, 'plPL', 'Pożeracz dusz', 'Sukkub to pożeracz dusz, niszczyciel serc, kusiciel mężczyzn. Istota głębokiego zła i jednego tylko pragnienia.$b$bNie da się go sprowadzić do naszego świata bez bodźca.$b$bDlatego obrócimy jego własną siłę przeciwko niemu. Serca dobrych mężczyzn, czystych mężczyzn, kochających mężczyzn – temu sukkub się nie oprze i przejdzie do naszego świata. Wtedy możesz go ujarzmić i uczynić swoim.$b$bPorozmawiaj z moim pomocnikiem, Godrickiem Farsanem, w Świątyni Potępionych. Pomoże ci znaleźć przynętę.', 'Porozmawiaj z Godrickiem Farsanem w Świątyni Potępionych.', '', '', '', '', '', '', 0),
(1474, 'plPL', 'Spętanie', 'Użyj tych serc, by w kręgu przywołań rzucić zaklęcie otwierające przejście, przez które przejdzie sukkub. Twoje moce są teraz większe i będziesz potrzebować ich wszystkich, by pokonać sukkuba.$b$bStrzeż się jego uroku, $n, niejeden silny umysł został spętany jego wolą. Gdy go pokonasz, sukkub wróci do pustki, a ja nauczę cię zaklęcia, którym przywołasz go na swój rozkaz.', 'Za pomocą Czystych serc przywołaj i ujarzmij sukkuba, a potem zwróć Czyste serca Carendinowi Halgarowi w Dzielnicy Magów w Podmieście.', '', 'Wróć do Carendina Halgara na Polanach Tirisfal.', '', '', '', '', 0),
(1475, 'plPL', 'W głąb Świątyni Atal\'Hakkar', 'Według legendy Świątynia Atal\'Hakkar to święty przybytek poświęcony pradawnemu bogu, Hakkarowi Duszożercy. Strzeże jej okrutne plemię trolli zwane Atal\'ai, a sama świątynia jest ponoć nie do zdobycia.$b$bTeraz, gdy spoczywa na dnie Sadzawki Łez, wydobycie z niej artefaktów jest jeszcze trudniejsze. Ale właśnie tego od ciebie potrzebuję, $n.$b$bPomóż mi, zbierając nienaruszone tabliczki Atal\'ai. Przynieś mi je, a wrócę do Ligi Odkrywców jako bohater. Razem podzielimy się chwałą.', 'Zbierz 10 tabliczek Atal\'ai dla Brohanna Beczkobrzucha z Wichrogrodu.', '', 'Wróć do Brohanna Beczkobrzucha w Wichrogrodzie.', '', '', '', '', 0),
(1477, 'plPL', 'Niezbędne zapasy', 'Nasi magowie prowadzą badania w Strażnicy Otchłani na Jałowych Ziemiach – badania kluczowe dla zrozumienia Mrocznych Portali. Potrzebują niemal nieustannych dostaw, ale nasz szlak zaopatrzenia do Strażnicy Otchłani jest niepewny.$B$BMusisz dopilnować, żeby zapasy dotarły na miejsce. Zgłoś się do komendanta warty Sorigala w Mrocznych Włościach i zrób, o co cię poprosi. To zadanie zaprowadzi cię na wrogie ziemie, $N. Przygotuj się.', 'Porozmawiaj z komendantem warty Sorigalem w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', '', '', 0),
(1530, 'plPL', 'Zew wody', 'Jeśli jest jedna lekcja o wodzie, którą musisz przyswoić, to ta: woda oznacza odrodzenie.$B$BJej moc płynie, żłobi i oczyszcza wszelkie rzeczy. Przekonasz się, że jej zdolność leczenia i odnawiania nie ma sobie równych – ale tylko wtedy, gdy jest czysta.$B$BKiedy zrozumiesz, że zanieczyszczona woda może spustoszyć wszystko, czego dotknie, docenisz, jak cennym jest zasobem.$B$BJeśli chcesz otrzymać saptę wody, odszukaj Solankę w głębi Południowych Pustkowi. Kolcozwierze nieustannie nękają jej dom.', 'Odszukaj Solankę na Grani Tarniny na Południowych Pustkowiach.', '', '', '', '', '', '', 0),
(1534, 'plPL', 'Zew wody', 'Weź ten bukłak i ruszaj w głąb bujnego lasu, który nocne elfy nazywają Jesionową Knieją. Leży daleko na północ od Pustkowi.$B$BGdy wejdziesz do lasu, idź na zachód. Wzdłuż gór oddzielających Szponogłazy od Jesionowej Kniei, za Jeziorem Mystral, znajdziesz święte miejsce: Ruiny Gwiezdnego Pyłu. Pośrodku jeziora jest mała fontanna.$B$BPrzynieś mi próbkę wody z tej fontanny. To ostatni składnik, jakiego potrzebujesz, zanim odeślę cię do Islen.', 'Napełnij pusty niebieski bukłak w Ruinach Gwiezdnego Pyłu w Jesionowej Kniei i wróć do Solanki na Pustkowiach.', '', 'Wróć do Solanki na Grani Tarniny na Pustkowiach.', '', '', '', '', 0),
(1535, 'plPL', 'Zew wody', 'Aby dojść do zrozumienia i otrzymać ode mnie saptę, musisz szukać tylko najczystszych postaci wody. Zbierając dla mnie próbki, zwracaj uwagę na otoczenie. Przyjrzyj się stworzeniom, które polegają na wodzie i które jej strzegą. Zobacz, jak wpływa na lasy i pustynie. Przekonaj się, jak ta sama substancja, która podtrzymuje życie, zmusza stworzenia do odbierania życia.$B$BZaczniemy od prostego zadania: poniżej mojej chaty jest sadzawka tej cennej cieczy. Napełnij nią ten bukłak i wróć do mnie.', 'Napełnij pusty brązowy bukłak przy wodopoju poniżej chaty Solanki i wróć z nim do niej na Pustkowiach.', '', 'Wróć do Solanki na Grani Tarniny na Pustkowiach.', '', '', '', '', 0),
(1536, 'plPL', 'Zew wody', 'Dawno temu wyruszyłam z towarzyszami do Międzygórza. Broniliśmy się przed zawziętymi ludźmi, którzy tam mieszkają, aż trafiliśmy do małego miasteczka zajętego przez Porzuconych: Smolnego Młyna.$B$BTo tam znalazłam coś bardzo osobliwego: pośrodku miasta była mała studnia ze świeżą wodą źródlaną. Nie jestem pewna, czy dotknięci zarazą mieszkańcy w ogóle zdają sobie sprawę z jej wartości – to maleńki święty okruch pośród nieuświęconego morza.$B$BPrzynieś mi w tym bukłaku próbkę tej wody.', 'Napełnij pusty czerwony bukłak przy studni w Smolnym Młynie i wróć do Solanki na Pustkowiach.', '', 'Wróć do Solanki na Grani Tarniny na Pustkowiach.', '', '', '', '', 0),
(1639, 'plPL', 'Pijak Bartleby', 'Jasne, mogę cię uczyć. Ale najpierw chcę zobaczyć, co już potrafisz.$B$BWidzisz tamtego pijaka na końcu baru? Bartleby\'ego? Chcę, żebyś $gzdobył:zdobyła; jego kufel.$B$BHa, a jeśli znasz Bartleby\'ego, to wiesz, że tak po prostu ci go nie odda.', 'Porozmawiaj z Bartlebym.', '', '', '', '', '', '', 0),
(1640, 'plPL', 'Pokonaj Bartleby\'ego', 'Chcesz czego?! Chyba cię pogięło!$B$BTen kufel dostaniesz tylko wtedy, gdy wyrwiesz mi go z zimnych, martwych palców...', 'Pokonaj Bartleby\'ego, a potem z nim porozmawiaj.', 'Pokonaj Bartleby\'ego', 'Porozmawiaj z Bartlebym w Wichrogrodzie.', '', '', '', '', 0),
(1650, 'plPL', 'Księga Męstwa', 'Dobrze! Brak wahania to pewny znak, że jesteś $ggotów:gotowa; i $gchętny:chętna;, by się sprawdzić. Niech więc tak będzie.$B$BNa samym krańcu Długiego Brzegu w Zachodnim Skraju stoi mały dom z widokiem na ocean. Mieszka tam para, Stilwellowie. Jordan to niezwykły kowal, a na jakiś czas wyjechał do Żelaznej Kuźni na spotkanie z krasnoludami. Przez to jego żona Daphne została sama, bez żadnej ochrony.$B$BZ raportów wynika, że Nieskorni praktycznie opanowali okolicę, więc Daphne może potrzebować ochrony przed tymi złoczyńcami. Udaj się tam.', 'Odnajdź Daphne Stilwell w Zachodnim Skraju.', '', '', '', '', '', '', 0),
(1651, 'plPL', 'Księga Męstwa', 'Założę się, że niedługo znowu przyjdą, więc się przygotuj.$B$BMam w domu strzelbę. Wezmę ją i będę gotowa ci pomóc, ale w większości musisz sobie radzić $gsam:sama;.$B$BNie mam pojęcia, ilu ich przyślą, ale na pewno więcej niż tych paru, co wcześniej.$B$BProś Światło o wszelkie błogosławieństwa, jakie się da, bo... słyszysz to? Chyba idą.$B$BBronimy się przy domu!', 'Obroń Daphne Stilwell przed atakiem Nieskornych.$B$BJeśli chcesz odnieść sukces, żadne z was nie może zginąć.$B$BPo zwycięstwie porozmawiaj ponownie z Daphne Stilwell.', 'Chroń Daphne Stilwell', 'Wróć do Daphne Stilwell w Zachodnim Skraju.', '', '', '', '', 0),
(1653, 'plPL', 'Próba prawości', 'Właściwie nie wątpię, że sam Jordan zechce ci podziękować, a skoro potrzebuję posłańca, który zaniesie mu wieść, że jego żona jest bezpieczna, myślę, że będziesz idealnym wyborem.$B$BJordan miał zostać paladynem Światłości, zanim oddanie rzemiosłu ojca poprowadziło go inną drogą – doskonale zna nasz sposób życia i uchodzi za jednego z najwierniejszych spośród nas.$B$BPowinien wciąż być w Żelaznej Kuźni – za dnia lubi pracować przed bramami, coś mówił o chłodnym górskim powietrzu.', 'Porozmawiaj z Jordanem Stilwellem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1665, 'plPL', 'Kufel Bartleby\'ego', 'No dobra, masz tu mój kufel. Czekaj! Najpierw dopiję, co w nim zostało... No, gotowe.', 'Zanieś kufel Bartleby\'ego Burlguardowi.', '', '', '', '', '', '', 0),
(1688, 'plPL', 'Surena Caledon', 'Miałem uczennicę imieniem Surena Caledon. Stała tam, gdzie ty teraz stoisz, spragniona wiedzy o magii czarnoksięskiej i obdarzona niemałym talentem. Co więcej, była młoda i miła dla oka. Gdybym tylko wtedy przejrzał tę zdradziecką ladacznicę!$b$bTa złodziejska dziewka uciekła z jednym z Nieskornych, Erlanem Drudgemoorem. Jej strata nie ma większego znaczenia, ale podarowałem jej obcisły naszyjnik z krwawnika, który muszę odzyskać.$b$bJej życie nic już dla mnie nie znaczy. Znajdziesz ją na dyniowym polu Brackwellów. Odzyskaj to, co moje.', 'Odzyskaj obcisły naszyjnik Sureny dla Gakina Mrokospętacza w Wichrogrodzie.', '', 'Wróć do Gakina Mrokospętacza w Wichrogrodzie.', '', '', '', '', 0),
(1689, 'plPL', 'Spętanie', 'Odzyskując mój naszyjnik i pokonując Surenę, $gudowodniłeś:udowodniłaś;, że jesteś co najmniej tak $gzdolny:zdolna; jak ona.$b$bMimo to widzę, że rozpaczliwie potrzebujesz szkolenia. Potrafisz kierować przepływami magii, owszem, ale bycie czarnoksiężnikiem to coś znacznie więcej.$b$bPokażę ci, jak rozkazywać wędrowcowi Pustki, ale najpierw musisz go przywołać w kręgu przywołań i ujarzmić wszelką bronią – fizyczną i magiczną – jaką masz do dyspozycji. Użyj magii tego naszyjnika w kręgu przywołań na dole.', 'Za pomocą obcisłego naszyjnika z krwawnika przywołaj i ujarzmij wędrowca Pustki, a potem zwróć naszyjnik Gakinowi Mrokospętaczowi w Wichrogrodzie.', '', 'Wróć do Gakina Mrokospętacza w Wichrogrodzie.', '', '', '', '', 0),
(1698, 'plPL', 'Yorus Jęczmieniowar', 'Yorus Jęczmieniowar rzucił wyzwanie wszystkim dzielnym wojownikom Przymierza. Czeka w karczmie w Jeziernych Włościach, w Rudej Grani, i obiecuje sowitą nagrodę każdemu, kto przejdzie jego próbę.', 'Porozmawiaj z Yorusem Jęczmieniowarem.', '', '', '', '', '', '', 0),
(1700, 'plPL', 'Grimand Elmore', 'Sporządziłem kopię notatek o technikach, których nauczyłem się przy robieniu twojej zbroi, i muszę je przesłać Grimandowi Elmore\'owi. Jest tu, w Dzielnicy Krasnoludów, w sklepie z bronią.$B$BI zrób unik, kiedy będziesz mu je wręczać. Jest diabelnie dumny ze swoich umiejętności i nie spodoba mu się myśl, że miałby się czegoś ode mnie uczyć...', 'Zanieś notatki Furena Grimandowi Elmore\'owi.', '', '', '', '', '', '', 0),
(1701, 'plPL', 'Hartowana w ogniu kolczuga', 'Dałem ci porządną tarczę, ale nie musimy na tym poprzestać. Znam sekret wykuwania niezwykle twardej kolczugi. To niełatwe i wymaga bardzo rzadkich surowców, ale jeśli zechcesz się nabiegać, zrobię ci taką.$B$BCo ty na to, $N? Jeśli podejmiesz wyzwanie, dam ci listę tego, co trzeba zdobyć, i gdzie tego szukać.', 'Zbierz surowce, których potrzebuje Furen Długobrody, i zanieś mu je do Wichrogrodu.', '', 'Wróć do Furena Długobrodego w Kniei Elwynn.', '', '', '', '', 0),
(1702, 'plPL', 'Kowal tarcz', 'Naprawdę $gpokazałeś:pokazałaś;, na co cię stać, kiedy $gprzeszedłeś:przeszłaś; ścieżkę zdrowia w Rethbanie, $N. A ja dotrzymuję słowa. Dostaniesz obiecaną nagrodę...$B$BTyle że jest w Wichrogrodzie.$B$BPorozmawiaj z moim przyjacielem, Furenem Długobrodym, w Dzielnicy Krasnoludów w Wichrogrodzie. To najlepszy kowal tarcz, jakiego spotkasz, a jest mi winien dużą przysługę.$B$BMasz, zanieś Furenowi tę beczkę Parzącego Jęczmiennego Browaru i poproś go o tarczę. Da ci porządną.', 'Zanieś beczkę Parzącego Furenowi Długobrodemu.', '', '', '', '', '', '', 0),
(1703, 'plPL', 'Mathiel', 'Sporządziłem kopię notatek o technikach, których nauczyłem się przy robieniu twojej zbroi, i trzeba je przesłać kowalowi Mathielowi. Mieszka w Darnassus, a to kawał drogi, ale jestem pewien, że będzie bardzo wdzięczny, gdy się dowie, czego się nauczyłem.', 'Zanieś notatki Furena Mathielowi.', '', '', '', '', '', '', 0),
(1704, 'plPL', 'Klockmort Kluczokręt', 'Sporządziłem kopię notatek o technikach, których nauczyłem się przy robieniu twojej zbroi, i potrzebuję kogoś, kto zaniesie je Klockmortowi Kluczokrętowi. To gnomi kowal z Żelaznej Kuźni, a kiedy się dowie, czego się nauczyłem... założę się, że z podniecenia wyrwie sobie brodę.', 'Zanieś notatki Furena Klockmortowi Kluczokrętowi.', '', '', '', '', '', '', 0),
(1705, 'plPL', 'Płonąca krew', 'Niechętnie to przyznaję, ale Furen chyba naprawdę coś odkrył. Żeby się jednak upewnić, muszę wypróbować jego techniki na nowej zbroi. Jeśli pomożesz mi zdobyć surowce, $N, zbroja będzie twoja.$B$BDo jej wykonania potrzebuję próbek płonącej krwi i płonącej skały.$B$BJedyne znane mi miejsce, gdzie można je zdobyć, to Knieja Zmierzchu. Worgeny Pożeracze Nocy, które zagnieździły się w kopalni w Zgubie Rolanda, mają płonącą krew, a skałę będzie miał ich przywódca, Flakowylew.$B$BOby szczęście dodało ci skrzydeł, $N.', 'Przynieś 20 fiolek płonącej krwi i 1 płonącą skałę Grimandowi Elmore\'owi w Wichrogrodzie.', '', 'Wróć do Grimanda Elmore\'a w Kniei Elwynn.', '', '', '', '', 0),
(1706, 'plPL', 'Zbroja Grimanda', '', '', '', '', '', '', '', '', 0),
(1716, 'plPL', 'Pożeracz dusz', 'Sukkub to pożeracz dusz, niszczyciel serc i władca umysłów. Nie zna niczego poza złem.$b$bTo właśnie tego demona nauczysz się przywoływać i kontrolować, ale nie da się go sprowadzić do naszego świata bez bodźca.$b$bZwabiony symbolem miłości z pewnością odpowie na twoje wezwanie. Wtedy możesz go pokonać i uczynić swoim narzędziem.$b$bTrudno jednak będzie znaleźć coś takiego. Porozmawiaj z Takarem Jasnowidzem. Znajdziesz go na Pustkowiach w Kalimdorze, niedaleko Obozu Taurajo.', 'Porozmawiaj z Takarem Jasnowidzem na Pustkowiach.', '', '', '', '', '', '', 0),
(1718, 'plPL', 'Wyspiarz', 'Twoja sława jako $gwojownika:wojowniczki; rośnie, $N. Czas zmierzyć się z równymi sobie i przekonać się, ile jesteś $gwart:warta;.$B$BU wybrzeży Pustkowi, na południe od Zapadki, leży wyspa. Nazywa się Wyspa Jatki i spotykają się na niej wojownicy.$B$BSpotykają się i walczą.$B$BOdszukaj przywódcę wojowników Wyspy Jatki, Klannoca Macleoda. Jeśli uzna cię za $ggodnego:godną;, poprowadzi cię dalej ścieżką wojownika.$B$BAby dotrzeć na Wyspę Jatki, poszukaj płycizn przy mieliźnie wzdłuż Wybrzeża Kupców.', 'Odszukaj Klannoca Macleoda i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(1738, 'plPL', 'Sercodrzew', 'Przygotowując się na twoje przybycie, użyłem swego wzroku, by spojrzeć na świat i przez mgły czasu. Znalazłem to, czego szukasz.$b$bW czasie Wojny Starożytnych dwoje kochanków poległo razem w bitwie. Tam, gdzie wydali ostatnie tchnienie, wyrosło drzewo zwane sercodrzewem – symbol ich nieśmiertelnej miłości.$b$bTo powinno wystarczyć, by skusić sukkuba. Znajdziesz je w Ruinach Ordil\'Aran, w północno-zachodniej części Jesionowej Kniei.', 'Zdobądź sercodrzew w Jesionowej Kniei i zanieś go Gakinowi Mrokospętaczowi w Dzielnicy Magów w Wichrogrodzie.', '', 'Wróć do Gakina Mrokospętacza w Wichrogrodzie.', '', '', '', '', 0),
(1739, 'plPL', 'Spętanie', 'Dzięki rdzeniowi sercodrzewu zdołasz rzucić w kręgu przywołań w krypcie na dole zaklęcie otwierające portal, przez który przejdzie sukkub.$b$bUważaj, $n, sukkuby zawładnęły już nawet najsilniejszymi umysłami.$b$bGdy go pokonasz i odeślesz z powrotem w pustkę, wróć do mnie, a pokażę ci, jak go przywoływać i nad nim panować.', 'Za pomocą rdzenia sercodrzewu przywołaj i ujarzmij sukkuba, a potem zwróć rdzeń Gakinowi Mrokospętaczowi w tawernie „Zarżnięte Jagnię”.', '', 'Wróć do Gakina Mrokospętacza w Wichrogrodzie.', '', '', '', '', 0),
(1782, 'plPL', 'Zbroja Furena', '', '', '', '', '', '', '', '', 0),
(1789, 'plPL', 'Symbol Życia', '', '', '', '', '', '', '', '', 0),
(1790, 'plPL', 'Symbol Życia', '', '', '', '', '', '', '', '', 0),
(1793, 'plPL', 'Księga Męstwa', '', '', '', '', '', '', '', '', 0),
(1794, 'plPL', 'Księga Męstwa', '', '', '', '', '', '', '', '', 0),
(1795, 'plPL', 'Spętanie', 'Jeśli jesteś $gdostatecznie przygotowany:dostatecznie przygotowana;, możemy zaczynać. Pozwól, że wyjaśnię ci przebieg.$b$bNajpierw utworzę podstawowy krąg przyzwania. Gdy skończę, moi akolici użyją prętów kanalizowania, by utworzyć większy krąg.$b$bGdy to się stanie, odczytaj inkantację z Księgi Sprzysiężenia, a łowca spaczenia zostanie ściągnięty do naszego świata. Uważaj, $n. Łowca spaczenia to groźny przeciwnik, a wolałbym, żeby twoja głowa została na karku.', 'Za pomocą Księgi Sprzysiężenia przyzwij i ujarzmij łowcę spaczenia, a potem zwróć Księgę Sprzysiężenia Strahadowi Farsanowi w Zapadce.', '', 'Wróć do Strahada Farsana na Pustkowiach.', '', '', '', '', 0),
(1798, 'plPL', 'W poszukiwaniu Strahada', 'Czas, żebyś $gnauczył:nauczyła; się przywoływać łowcę spaczenia, $n. Nie mam tu odczynników ani przedmiotów potrzebnych do tej nauki, więc musisz odszukać kogoś innego – Strahada Farsana, kolejnego członka naszego wewnętrznego kręgu.$b$bMieszka w Zapadce, goblińskim porcie. Wyślę mu wiadomość, żeby wiedział o twoim przybyciu.', 'Porozmawiaj ze Strahadem Farsanem na Pustkowiach.', '', '', '', '', '', '', 0),
(1861, 'plPL', 'Lustrzane Jezioro', 'Ten świat padł ofiarą potężnych zmagań mistycznych, które wyrwały prądy magii z niegdyś stabilnych kanałów. Próbujemy ustalić, jakie skutki wywołały te zmiany, a niektórzy z nas obawiają się najgorszego!$B$BAle więcej wyjawię ci później. Teraz musimy zebrać informacje.$B$BMasz, weź tę flaszkę. Idź do stóp wodospadu nad Lustrzanym Jeziorem, na południowy zachód od bram Wichrogrodu, i nabierz próbkę tamtejszej wody. Przynieś mi ją, żebym mogła zbadać, czy nie ma w niej magicznych skażeń.', 'Przynieś próbkę wody z Lustrzanego Jeziora Jennei Cannon w Wichrogrodzie.', '', 'Wróć do Jennei Cannon w Wichrogrodzie.', '', '', '', '', 0),
(1920, 'plPL', 'Zbadaj „Błękitnego Samotnika”', 'Zgłoszono zakłócenia w tawernie „Błękitny Samotnik” w Dzielnicy Magów. Po tawernie krążą teraz dziwne, niewidzialne stwory i obawiam się, że powstała tam szczelina many.$B$BChcę, żebyś $gzbadał:zbadała; tawernę i $gschwytał:schwytała; te stwory. Użyj w tawernie inkantacji manifestacji, żeby stwory stały się widoczne, obezwładnij je, a potem schwytaj za pomocą szkatuły izolującej. Gdy zbierzesz ich dość, wróć do mnie z napełnionymi szkatułami, pustymi szkatułami i inkantacją.', 'Weź inkantację manifestacji oraz szkatuły ze skrzyni szkatuł izolujących, która stoi za Jenneą Cannon. Przynieś 3 napełnione szkatuły izolujące Jennei do sanktuarium czarodziejów.', '', 'Wróć do Jennei Cannon w Wichrogrodzie.', '', '', '', '', 0),
(1921, 'plPL', 'Zbieranie materiałów', 'Dobrze $gsłużyłeś:służyłaś; innym magom i nadszedł czas, byś $gprzywdział:przywdziała; szatę czarodzieja. Wynne Larson może ją uszyć, ale musisz przynieść jej potrzebne materiały.$B$BSzata będzie z lnianego płótna, które łatwo znaleźć, ale musisz też zdobyć naładowane klejnoty szczeliny, a jedyne znane miejsce, gdzie można je znaleźć, to Kopalnia Srebrnego Strumienia w Loch Modan – zostawił je tam w skrzyniach krasnoludzki związek górników.$B$BZbierz płótno i klejnoty i zanieś je Wynne Larson do „Odzieży Larsona” w Dzielnicy Magów.', 'Przynieś 10 sztuk lnianego płótna i 6 naładowanych klejnotów szczeliny Wynne Larson w Wichrogrodzie.', '', 'Wróć do Wynne Larson w Wichrogrodzie.', '', '', '', '', 0),
(1938, 'plPL', 'Traktat Ura o magii cienia', 'Dawno temu w tej wieży studiowało trzech magów, aż jeden z nich uległ mrocznym sztukom. Nakłaniano go, by odwrócił się od tej złej magii, ale nie potrafił się jej oprzeć. Dlatego został wygnany.$B$BNową domeną upadłego maga jest Wieża Ilgalara w Rudej Grani, a zabrał ze sobą potężną księgę – Traktat Ura o magii cienia.$B$BMy, magowie Wichrogrodu, chcemy odzyskać tę księgę. Wejdź do Wieży Ilgalara, znajdź księgę w jego bibliotece i przynieś ją mnie.', 'Zanieś Traktat Ura o magii cienia arcyczarownikowi Andromathowi w Wichrogrodzie.', '', 'Wróć do arcyczarownika Andromatha w Wichrogrodzie.', '', '', '', '', 0),
(1939, 'plPL', 'Arcyczarownik Andromath', 'Arcyczarownik Andromath chce z tobą porozmawiać, $N. Przebywa na szczycie sanktuarium czarodziejów, w Dzielnicy Magów w Wichrogrodzie.$B$BRozsądnie byłoby z nim porozmawiać, bo Andromath to jeden z najpotężniejszych magów, których nie zamknięto w Dalaranie. Jego rada to rada najwyższej próby.', 'Porozmawiaj z arcyczarownikiem Andromathem.', '', '', '', '', '', '', 0),
(1940, 'plPL', 'Nieskazitelny pajęczy jedwab', 'Twoja służba była niezłomna, $N. Myślę, że może nadszedł czas, byś $gotrzymał:otrzymała; lepszy strój, bardziej odpowiedni dla twojej pozycji $gbiegłego maga:biegłej magini;. Jeśli zbierzesz potrzebne materiały, załatwimy uszycie szaty.$B$BMusisz udać się do Kniei Zmierzchu i zapolować na padlinowe samotniki. Wydobądź z nich jedwab, ale nada się tylko najlepszy, najbardziej nieskazitelny. Gdy zbierzesz go dość, zanieś go Wynne Larson tutaj, w Dzielnicy Magów, do „Odzieży Larsona”. Ona uszyje ci szatę.', 'Przynieś 8 sztuk nieskazitelnego pajęczego jedwabiu Wynne Larson w Wichrogrodzie.', '', 'Wróć do Wynne Larson w Wichrogrodzie.', '', '', '', '', 0),
(1941, 'plPL', 'Szata z tkaniny many', '', '', '', '', '', '', '', '', 0),
(1942, 'plPL', 'Odzienie astralnego węzła', '', '', '', '', '', '', '', '', 0),
(1947, 'plPL', 'Wyprawa na bagna', 'Teraz nadszedł czas, byś $gzasłużył:zasłużyła; na różdżkę maga. Aby rozpocząć to zadanie, porozmawiaj z Tabethą, ludzką pustelnicą z Pyłowego Bagniska. Jej chatę znajdziesz głęboko na bagnach, na zachód od Theramore.$B$BPorozmawiaj z nią, bo jej wiedza jest ogromna. Chatę Tabethy znajdziesz na zachód od Theramore, tuż na północ od Ruin Kamiennych Maczug.', 'Porozmawiaj z Tabethą.', '', '', '', '', '', '', 0),
(1953, 'plPL', 'Powrót na bagna', 'Nadszedł czas, $N, byś $gporozmawiał:porozmawiała; z Tabethą... pustelnicą z Pyłowego Bagniska. Nauczy cię, jak stworzyć potężne narzędzie maga.$B$BChata Tabethy stoi głęboko na Pyłowym Bagnisku, na zachód od Theramore.', 'Porozmawiaj z Tabethą.', '', '', '', '', '', '', 0),
(1961, 'plPL', 'Zbieranie materiałów', 'Czas, byś $gprzywdział:przywdziała; swoje pierwsze szaty maga, $N. Są oznaką twojej pozycji i świadectwem twojej wartości.$B$BAby je zdobyć, musisz zebrać klejnoty many od dalarańskich magów w Srebrzystym Borze. Ich przekonania nie różnią się bardzo od naszych, więc zabijanie ich jest nieco niesmaczne. Ale skoro brak im siły, by nam się oprzeć, nie zasługują na życie.$B$BZanieś klejnoty i zapas lnianego płótna Josefowi Gregorianowi do zakładu krawieckiego w Dzielnicy Magów.', 'Przynieś 10 sztuk lnianego płótna i 6 dalarańskich klejnotów many Josefowi Gregorianowi.', '', 'Wróć do Josefa Gregoriana na Polanach Tirisfal.', '', '', '', '', 0),
(2040, 'plPL', 'Podziemny szturm', 'Gnomoregan wpadł w łapy tych podłych troggów! Sytuacja jest poważna, ale może ty zdołasz pomóc, $N.$B$BGłęboko w Martwej Kopalni stoi sprawny gobliński rozdrabniacz. Znajdź go i przynieś jego nienaruszone źródło zasilania. Dzięki niemu dostarczymy naszym żyrowiertomatycznym ekskawatorom mocy potrzebnej do przebicia się przez skaliste podziemne granice Gnomoregan i otworzymy drogę do gnomiego szturmu!', 'Zdobądź Gnoam Sprecklesprocket w Martwej Kopalni i zanieś go Shoni Szichej w Wichrogrodzie.', '', 'Wróć do Shoni Szichej w Dzielnicy Krasnoludów w Wichrogrodzie.$B', '', '', '', '', 0),
(2041, 'plPL', 'Porozmawiaj z Shoni', 'Może... Może ty pomożesz nam w bitwie o Gnomoregan.$B$BW Wichrogrodzie znajdziesz dowódczynię naszego podziemnego oddziału szturmowego, Shoni Szichą. Shoni potrzebuje pomocy przy swoich żyrowiertomatycznych ekskawatorach.$B$BPewnie znajdziesz ją wśród krasnoludów w Wichrogrodzie.$B$BPowodzenia, $N.', 'Porozmawiaj z Shoni Szichą w Dzielnicy Krasnoludów w Wichrogrodzie.$B', '', '', '', '', '', '', 0),
(2206, 'plPL', 'Capnij i zmykaj', 'Nasi agenci w terenie donoszą o wzmożonej aktywności Nieskornych na południe od Złotych Włości. Z raportów wynika, że Nieskorni przejęli Przystań Jeroda i przemycają przez nią duże ilości kontrabandy z Rudej Grani do Zachodniego Skraju.$B$BMusisz przeniknąć do budynku portowego i zdobyć dla mnie ten harmonogram wysyłek, $N. Pewnie znajdziesz go głęboko w kieszeniach bosmana portowego.$B$B...i, $N, jeśli cię nakryją, WW:7 wyprze się jakiejkolwiek wiedzy o twoim istnieniu.', 'Znajdź bosmana portowego Nieskornych i odzyskaj harmonogram wysyłek dla mistrza Mathiasa Shawa.$B', '', 'Wróć do mistrza Mathiasa Shawa w siedzibie WW:7 w Wichrogrodzie.', '', '', '', '', 0),
(2260, 'plPL', 'Polecenie Eriona', 'Wieści o twoich czynach rozeszły się szeroko, $N. Tak szeroko, że wywiad Wichrogrodu zapytał o ciebie z imienia.$B$BPodróż jest męcząca i nie bez niebezpieczeństw, ale okazji do szkolenia pod okiem WW:7 nie należy lekceważyć.$B$BCzeka na ciebie nowy świat, $N. Udaj się na Stare Miasto w Wichrogrodzie i porozmawiaj z Renzikiem „Kosa” w siedzibie WW:7.$B', 'Udaj się do Wichrogrodu i zgłoś się do Renzika „Kosa”.', '', '', '', '', '', '', 0),
(2281, 'plPL', 'Spotkanie w Rudej Grani', 'Wysłanie cię teraz w teren byłoby samobójstwem. Renzik nie potrzebuje kolejnego martwego łotra na sumieniu. Ale nie martw się, $N – Renzik cię podszkoli.$B$BUdaj się w Góry Rudej Grani i porozmawiaj ze współpracownikiem WW:7 imieniem Lucius. Znajdziesz go w dokach Jeziernych Włości, gdzie kręci się z innymi podejrzanymi nicponiami.', 'Wyrusz do Jeziernych Włości w Górach Rudej Grani i porozmawiaj z Luciusem.', '', '', '', '', '', '', 0),
(2359, 'plPL', 'Wieża Klavena', 'Od tygodni obserwuję tę wieżę, $N. Niedawno przyszedł duży transport z Kniei Zmierzchu, a razem z nim ci strażnicy.$B$BCzym oni są? Wiem tyle, co ty. Jedno mogę ci powiedzieć – to nie są ludzie.$B$BTak czy inaczej, w transporcie była skrzynia – zakładam, że to jej pilnują te poczwary. Zombie z kolcami ma klucz, którego będziemy potrzebować.$B$BZdobądź ten klucz, dostań się do wieży i sprawdź, co jest w skrzyni. Ze swoimi odkryciami wróć do Mathiasa.', 'Wykradnij klucz do wieży Nieskornych, włam się do wieży i sprawdź zawartość skrzyni z Kniei Zmierzchu. Wszelkie znalezione informacje zanieś Mathiasowi Shawowi w Wichrogrodzie. Przeczytaj dziennik Kearnen, by dowiedzieć się więcej o wieży.$B', '', 'Wróć do mistrza Mathiasa Shawa w siedzibie WW:7 w Wichrogrodzie.', '', '', '', '', 0),
(2360, 'plPL', 'Mathias i Nieskorni', 'W samą porę, $N. Zwiad WW:7 donosi o niezwykle wzmożonej aktywności Nieskornych w Zachodnim Skraju.$B$BWygląda na to, że Nieskorni zajęli opuszczoną wieżę strażniczą Przymierza na południowy wschód od Wzgórza Strażniczego i wykorzystują ją jako bazę do przemytu towarów szlakiem zaopatrzeniowym z Rudej Grani.$B$BUdaj się do Zachodniego Skraju i skontaktuj się z agentką Kearnen, która przekaże ci szczegóły. Znajdziesz ją w ukryciu w pobliżu wieży.$B$B...i, $N, jeśli cię nakryją, WW:7 wyprze się jakiejkolwiek wiedzy o twoim istnieniu.', 'Udaj się do Zachodniego Skraju i odszukaj agentkę Kearnen, która przekaże ci szczegóły zadania.', '', '', '', '', '', '', 0),
(2745, 'plPL', 'Infiltracja zamku', 'Hmm, ciekawa historia i nie wolno jej lekceważyć. Tak, mogę ci pomóc, ale jeśli chcesz doprowadzić sprawę do końca, musisz wymierzyć sprawiedliwość w sposób niezupełnie... legalny.$B$BTrzeba się rozprawić z Lescovarem i Marzonem, i to szybko. Myślisz, że dasz radę?$B$BTwoja decyzja. Jeśli tak, pospiesz się do zamku i odszukaj mojego starego przyjaciela, gnoma imieniem Tyrion. Od paru tygodni obserwuje Lescovara. Powinien pomóc ci to zakończyć.', 'Porozmawiaj z Tyrionem w zamku Wichrogrodu.', '', '', '', '', '', '', 0),
(2746, 'plPL', 'Rzeczy niemałej wagi', 'Trias chce przyspieszyć harmonogram, co? Dobra, da się zrobić, ale nie jestem gotowy. I wiedz jedno: ja robię najtrudniejszą część, ale to ty ubrudzisz sobie ręce, jasne? Dobrze.$B$BDobra, zanim wprowadzę plan w życie, musisz mi zdobyć kilka rzeczy. Mam idealne przebranie, dzięki któremu szpiegobot prześlizgnie się obok strażników.$B$BPrzynieś mi trochę jedwabiu i parę jabłek. Jedwab zdobądź, jak chcesz, ale na małej farmie Clary tuż za miastem rosną jabłka idealnej wielkości.', 'Przynieś 3 sztuki jedwabnego płótna i 2 świeże jabłka Clary Tyrionowi w Wichrogrodzie.', '', 'Wróć do Tyriona w Wichrogrodzie.', '', '', '', '', 0),
(2758, 'plPL', 'Źródło kowalstwa', 'Kiedy byłem mniej więcej w twoim wieku, krasnolud imieniem Galvan wziął mnie pod swoje skrzydła i wyszkolił na płatnerza. Zanim wyjechał do Łupieżczej Zatoki, kazał mi obiecać, że będę uczyć każdego, kto ma chęć i determinację, by doskonalić się w sztuce kowalstwa – i oto jestem, po tylu latach.$B$BA teraz twoja kolej, żeby się czegoś nauczyć. Zrób mi sześć par karwaszy ze złotych łusek, a dowiesz się, skąd bierze się kowalstwo, $N.', 'Przynieś sześć par karwaszy ze złotych łusek Hankowi Młotowi w Wichrogrodzie.', '', 'Wróć do Hanka Młota w Dzielnicy Krasnoludów w Wichrogrodzie.', '', '', '', '', 0),
(2759, 'plPL', 'W poszukiwaniu Galvana', 'Choć Galvan opuścił Łupieżczą Zatokę wiele lat temu, członkowie zakonu wciąż mieszkają w mieście w nadziei, że pewnego dnia znajdą kogoś jeszcze godnego nauk Galvana.$B$BWeź tę odznakę i pokaż ją McGavanowi w Łupieżczej Zatoce.$B$BJeśli naprawdę tam dotrzesz, będzie wiedział, że jesteś $ggodzien:godna;. Wierzę w ciebie, $N!', 'Porozmawiaj z McGavanem w Łupieżczej Zatoce.', '', '', '', '', '', '', 0),
(2861, 'plPL', 'Zadanie Tabethy', 'Chodzą słuchy, że Tabetha, zaprzyjaźniona magini, która mieszka w głębi Pyłowego Bagniska, ma kość niezgody z pewną piaskową trollicą z Zul\'Farrak. Jeśli porozmawiasz z Tabethą, powie ci więcej.$B$BI weź ze sobą przyjaciół, $N. Jeśli Tabetha pośle cię do Zul\'Farrak, lepiej nie idź tam w pojedynkę.$B$BChatkę Tabethy znajdziesz na zachód od Theramore, tuż na północ od Ruin Kamiennych Maczug.', 'Porozmawiaj z Tabethą na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(2923, 'plPL', 'Majster Nadiskra', 'Majster Nadiskra bardzo się przejmuje losem swojego mechanicznego dzieła, Techbota. Pamiętam Techbota jako życzliwe i pomocne narzędzie gnomów, ale Nadiskra mówi mi, że coś się w nim popsuło.$B$BBardzo smutne. Ale przy odrobinie szczęścia może da się go naprawić!$B$BPorozmawiaj z majstrem Nadiskrą w Majsterkowie w Żelaznej Kuźni. Z radością przyjmie twoją pomoc.', 'Porozmawiaj z majstrem Nadiskrą w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2928, 'plPL', 'Żyrowiertłomatyczne wykopywacze', 'To straszne, $N. Nie starczy nam części, żeby dostarczyć naszą flotę żyrowiertłomatycznych wykopywaczy do Dun Morogh.$B$BPotrzebujemy części zamiennych, $N. A gdzie lepiej zdobyć części do naszych maszyn niż w Gnomoregan? Słyszałam, że boty i mechy łażą tam jak bydło po otwartym pastwisku.$B$BChcę, żebyś $gposzedł:poszła; do Gnomoregan i $grozebrał:rozebrała; te roboty na części. Przynieś mi ich robotyczne flaki. Dwa tuziny powinny wystarczyć.$B', 'Przynieś dwadzieścia cztery robomechaniczne flaki Shoni w Wichrogrodzie.', '', 'Wróć do Shoni Szichej w Dzielnicy Krasnoludów w Wichrogrodzie.', '', '', '', '', 0),
(3001, 'plPL', 'W poszukiwaniu Strahada', 'Uczyłem cię już wcześniej, ale nadszedł czas, by uczył cię ktoś inny. Jest w Zapadce i nazywa się Strahad. To człowiek, ale niech cię to nie zwiedzie – nie jest słaby ani nie jest twoim wrogiem... przynajmniej na razie. Jest potężny i należy mu się szacunek. Nauczy cię potężniejszych przywołań – czuję, że jesteś na nie $ggotów:gotowa;. Idź do niego teraz.$B$BZnajdziesz go w Zapadce... ponad portowym miasteczkiem, przy tamtejszej wieży.', 'Odnajdź Strahada Farsana w Zapadce.', '', '', '', '', '', '', 0),
(3526, 'plPL', 'Goblińska inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie odrębne dyscypliny: gnomią i goblińską. Rzecz jasna, goblińska inżynieria to wybór wszystkich błyskotliwych inżynierów. Naucz się podporządkowywać sobie świat rozważnym użyciem silnych materiałów wybuchowych i fantastycznego sprzętu!$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz się nauczyć goblińskiej inżynierii, zanieś go Nixxowi Sprężynotrybowi w Gadżetonie. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że właśnie tego chcesz, zanim wykonasz jego zadanie.', 'Jeśli chcesz dowiedzieć się więcej o goblińskiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych Nixxowi Sprężynotrybowi w Gadżetonie.', '', '', '', '', '', '', 0),
(3629, 'plPL', 'Goblińska inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie odrębne dyscypliny: gnomią i goblińską. O goblińskiej inżynierii wspominam tylko dlatego, że jestem uczciwym nauczycielem. Gobliny lubią robić rzeczy, które wybuchają, i rzadko przejmują się tym, co stoi na drodze – nawet jeśli to one same.$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz się nauczyć, jak wysadzić się w powietrze, zanieś go Nixxowi Sprężynotrybowi w Gadżetonie. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że właśnie tego chcesz, zanim wykonasz jego zadanie.', 'Jeśli chcesz dowiedzieć się więcej o goblińskiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych Nixxowi Sprężynotrybowi w Gadżetonie.', '', '', '', '', '', '', 0),
(3630, 'plPL', 'Gnomia inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie dyscypliny: gnomią i goblińską. Gnomia inżynieria jest zdecydowanie lepsza z nich dwóch! Chodzi w niej o konstruowanie wspaniałych gadżetów i urządzeń, które ułatwiają życie!$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz dowiedzieć się więcej o gnomiej inżynierii, zanieś go majstrowi Nadiskrze w Żelaznej Kuźni. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że naprawdę tego chcesz, zanim wykonasz jego zadanie!', 'Jeśli chcesz dowiedzieć się więcej o gnomiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych majstrowi Nadiskrze w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3633, 'plPL', 'Goblińska inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie odrębne dyscypliny: gnomią i goblińską. Rzecz jasna, goblińska inżynieria to wybór wszystkich błyskotliwych inżynierów. Naucz się podporządkowywać sobie świat rozważnym użyciem silnych materiałów wybuchowych i fantastycznego sprzętu!$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz się nauczyć goblińskiej inżynierii, zanieś go Nixxowi Sprężynotrybowi w Gadżetonie. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że właśnie tego chcesz, zanim wykonasz jego zadanie.', 'Jeśli chcesz dowiedzieć się więcej o goblińskiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych Nixxowi Sprężynotrybowi w Gadżetonie w Tanaris.', '', '', '', '', '', '', 0),
(3635, 'plPL', 'Gnomia inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie dyscypliny: gnomią i goblińską. Choć moim zdaniem to strata czasu, $gpowinieneś:powinnaś; wiedzieć o gnomiej specjalizacji. Gnomy robią przedmioty i gadżety, które podobno mają zmienić świat, ale rzadko kiedy działają.$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz się nauczyć robić metalowe przyciski do papieru, zanieś go Oglethorpe\'owi Obnoticusowi w Łupieżczej Zatoce. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że naprawdę tego chcesz, zanim wykonasz jego zadanie.', 'Jeśli chcesz dowiedzieć się więcej o gnomiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych Oglethorpe\'owi Obnoticusowi w Łupieżczej Zatoce.', '', '', '', '', '', '', 0),
(3636, 'plPL', 'Nieś Światłość', 'Plaga to nieustanne zagrożenie dla Przymierza, o czym z pewnością dobrze wiesz. Ostatnio dokonaliśmy bardzo osobliwych odkryć, $N.$B$BNa Pustkowiach leży okropna plątanina ciernistych pnączy zwana Kurhanami Brzytwoskórych. Niegdyś był to dom zwykłych kolcozwierzy, lecz teraz stało się jasne, że zawarto tam pakt z Plagą, z którego zrodziły się istoty o wiele gorsze... Rządzi nimi teraz lisz, Amnennar Zwiastun Chłodu.$B$BStań po stronie Światłości, $N; połóż kres temu złowrogiemu sojuszowi.', 'Arcybiskup Benedykt chce, żebyś $gzabił:zabiła; Amnennara Zwiastuna Chłodu w Kurhanach Brzytwoskórych.', '', 'Wróć do arcybiskupa Benedykta na Placu Katedralnym w Wichrogrodzie.', '', '', '', '', 0),
(3637, 'plPL', 'Gnomia inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie dyscypliny: gnomią i goblińską. Choć moim zdaniem to strata czasu, $gpowinieneś:powinnaś; wiedzieć o gnomiej specjalizacji. Gnomy robią przedmioty i gadżety, które podobno mają zmienić świat, ale rzadko kiedy działają.$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz się nauczyć robić metalowe przyciski do papieru, zanieś go Oglethorpe\'owi Obnoticusowi w Łupieżczej Zatoce. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że naprawdę tego chcesz, zanim wykonasz jego zadanie.', 'Jeśli chcesz dowiedzieć się więcej o gnomiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych Oglethorpe\'owi Obnoticusowi w Łupieżczej Zatoce.', '', '', '', '', '', '', 0),
(3763, 'plPL', 'Pomoc arcydruidowi Jeleniorogiemu', 'Przepraszam, $N, ale jeśli to możliwe, chciałabym zająć ci tylko chwilę.$B$BKrąg Cenariona w Darnassus szuka doświadczonych poszukiwaczy przygód, takich jak ty, którzy wsparliby ważny projekt badawczy. Nie znam szczegółów, ale mogę ci powiedzieć, że na czele tych badań stoi nie kto inny jak sam arcydruid Fandral Jeleniorogi.$B$BProszę – jeśli cię to interesuje, porozmawiaj z nim osobiście w Enklawie Cenariona w samym Darnassus.', 'Porozmawiaj z arcydruidem Fandralem Jeleniorogim w Darnassus.', '', '', '', '', '', '', 0),
(3765, 'plPL', 'Splugawienie za morzem', 'Wichrogród – cóż za tętniące życiem miejsce.$b$bPrzybyłem z daleka, by szukać pomocy. Często słyszy się, że po ulicach tego miasta przechadzają się dzielni poszukiwacze przygód.$b$bMój brat, Gershala, potrzebuje pomocy na Mrocznym Wybrzeżu. Mieszka w nadmorskim miasteczku Auberdine.$b$bPodróż jest długa i pełna przygód. Dlatego właśnie proszę o pomoc kogoś tak doświadczonego jak ty.', 'Udaj się do Gershali Nocnego Szeptu w Auberdine.', '', '', '', '', '', '', 0),
(3787, 'plPL', 'Prośba Jonespyre\'a', 'Przepraszam, $gprzyjacielu:przyjaciółko;...$B$BMój znajomy chciałby z tobą porozmawiać o badaniach, które prowadzisz wspólnie z Kręgiem Cenariona. To druid o imieniu Quintis Jonespyre, mieszka w Warowni Lunopiórej w Feralas. Chciałby omówić z tobą sprawę jutroziarna... i bardzo mu zależy, żeby nasza rozmowa nie dotarła do uszu arcydruida.$B$BJeśli cię to interesuje, porozmawiaj z nim; bez wątpienia wszystko się wtedy wyjaśni.', 'Porozmawiaj z Quintisem Jonespyre\'em w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(3789, 'plPL', 'Pomoc arcydruidowi Jeleniorogiemu', 'Przepraszam, $N, ale jeśli to możliwe, chciałabym zająć ci tylko chwilę.$B$BKrąg Cenariona w Darnassus szuka doświadczonych poszukiwaczy przygód, takich jak ty, którzy wsparliby ważny projekt badawczy. Nie znam szczegółów, ale mogę ci powiedzieć, że na czele tych badań stoi nie kto inny jak sam arcydruid Fandral Jeleniorogi.$B$BProszę – jeśli cię to interesuje, porozmawiaj z nim osobiście w Enklawie Cenariona w samym Darnassus.', 'Porozmawiaj z arcydruidem Fandralem Jeleniorogim w Darnassus.', '', '', '', '', '', '', 0),
(3790, 'plPL', 'Pomoc arcydruidowi Jeleniorogiemu', 'Przepraszam, $N, ale jeśli to możliwe, chciałabym zająć ci tylko chwilę.$B$BKrąg Cenariona w Darnassus szuka doświadczonych poszukiwaczy przygód, takich jak ty, którzy wsparliby ważny projekt badawczy. Nie znam szczegółów, ale mogę ci powiedzieć, że na czele tych badań stoi nie kto inny jak sam arcydruid Fandral Jeleniorogi.$B$BProszę – jeśli cię to interesuje, porozmawiaj z nim osobiście w Enklawie Cenariona w samym Darnassus.', 'Porozmawiaj z arcydruidem Fandralem Jeleniorogim w Darnassus.', '', '', '', '', '', '', 0),
(4181, 'plPL', 'Goblińska inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie odrębne dyscypliny: gnomią i goblińską. O goblińskiej inżynierii wspominam tylko dlatego, że jestem uczciwym nauczycielem. Gobliny lubią robić rzeczy, które wybuchają, i rzadko przejmują się tym, co stoi na drodze – nawet jeśli to one same.$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz się nauczyć, jak wysadzić się w powietrze, zanieś go Nixxowi Sprężynotrybowi w Gadżetonie. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że właśnie tego chcesz, zanim wykonasz jego zadanie.', 'Jeśli chcesz dowiedzieć się więcej o goblińskiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych Nixxowi Sprężynotrybowi w Gadżetonie.', '', '', '', '', '', '', 0),
(4738, 'plPL', 'W poszukiwaniu Menary Rozdzieraczki Pustki', 'Wyjaśnijmy sobie jedno, $N: nie uważam, żebyś $gbył gotów:była gotowa; na takie obowiązki. Nie sądzę, by nowicjusz kiedykolwiek powinien brać udział w tworzeniu przedmiotu mocy, a zwłaszcza ktoś tak niesprawdzony.$B$BAle to nie moja decyzja. Decydują o tym moce wyższe, a przynajmniej te, które pragną obdarzyć cię takimi darami.$B$BJeśli chcesz dowiedzieć się więcej, radzę ci odszukać Menarę Rozdzieraczkę Pustki w Zapadce. Zwykle przebywa w wieży nad portowym miasteczkiem.', 'Porozmawiaj z Menarą Rozdzieraczką Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(4739, 'plPL', 'W poszukiwaniu Menary Rozdzieraczki Pustki', '$N! Tak, ty!$B$BNie masz jeszcze całego rynsztunku, ale widać gołym okiem, że jesteś $ggotów:gotowa; – bije od ciebie większa pewność siebie. Tak, teraz to widzę.$B$BMenara Rozdzieraczka Pustki nauczy cię kilku rzeczy, jeśli uważasz, że jesteś $ggotów:gotowa;. Spędza czas, ucząc młodszych adeptów sztuk tajemnych. Tym, którzy przejdą jej próby, daje nawet podarunki.$B$BJeśli cię to interesuje, udaj się do Zapadki na Pustkowiach. Mieszka nad miastem, w wieży Strahada.', 'Porozmawiaj z Menarą Rozdzieraczką Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(4765, 'plPL', 'Dostawa dla Ridgewella', 'Zapakowałam klamrę Doomriggera do skrzyni, żeby można ją było wysłać do Wichrogrodu. $N, $gbyłeś:byłaś; mi ogromną pomocą – czy mogę cię prosić o ostatnią przysługę?$B$BDostarcz skrzynię hrabiemu Remingtonowi Ridgewellowi. Znajdziesz go w Twierdzy Wichrogród. Jestem pewna, że bardzo się ucieszy, widząc, co dla niego masz.', 'Zanieś skrzynię Ridgewella hrabiemu Remingtonowi Ridgewellowi w Twierdzy Wichrogród w Wichrogrodzie.', '', '', '', '', '', '', 0),
(4766, 'plPL', 'Mayara Jasnoskrzydła', 'Moja agentka, Mayara Jasnoskrzydła, została wysłana na Płonące Stepy, by przeszukać zrujnowane miasto Thaurissan. To zniszczone miasto krasnoludów z Czarnorytych może skrywać przedmioty wielkiej wartości... przedmioty, które świetnie pasowałyby do naszego rodzinnego muzeum.$B$BMayara twierdzi, że coś znalazła i będzie potrzebowała pomocy, by to wydobyć, ale nie w samym Thaurissan. Konieczna będzie za to wyprawa do Iglicy Czarnej Góry.$B$BNie znam szczegółów, ale jeśli cię to interesuje, porozmawiaj z Mayarą na Płonących Stepach.', 'Porozmawiaj z Mayarą Jasnoskrzydłą w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', '', '', 0),
(4902, 'plPL', 'Dziczołaki Eluny', 'To fascynujące!$B$BZawsze zastanawiałem się, jaka jest prawda... Musisz koniecznie podzielić się tą wiedzą! Udaj się natychmiast do arcydruida Fandrala Jeleniorogiego – znajdziesz go w Darnassus, w Kręgu Cenariona. Opowiedz mu, co się wydarzyło, dokładnie tak jak mnie. Jestem pewien, że zainteresuje go to równie mocno!$B$BTo ważne informacje, $N!', 'Porozmawiaj z arcydruidem Fandralem Jeleniorogim w Darnassus.', '', '', '', '', '', '', 0),
(4968, 'plPL', 'Wiedza o Kuli Orahila', 'Hmm, $gzaszedłeś:zaszłaś; aż tak daleko... doprawdy zdumiewające. Można by pomyśleć, że skażenie płynące z władania mocą tajemną przesiąkło już do głębi twoją duszę i doprowadziło cię do szaleństwa. Może więc spróbujemy popchnąć cię jeszcze dalej?$B$BJeśli chcesz wystawić swoje umiejętności na próbę, odszukaj Menarę Rozdzieraczkę Pustki w wieży Strahada nad Zapadką. Ona cię poprowadzi.', 'Porozmawiaj z Menarą Rozdzieraczką Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(4969, 'plPL', 'Wiedza o Kuli Orahila', 'Haha! Świetnie ci idzie, $N.$B$BZ czasem infernale i upiorni władcy będą się przed tobą kłaniać!$B$BAle zanim ten czas nadejdzie, wciąż musisz polegać na broni wykutej rękami śmiertelnych ras.$B$BWyglądasz na $ggotowego:gotową; na kolejne takie dzieło, a jeśli zechcesz, Menara Rozdzieraczka Pustki chętnie z tobą porozmawia! Jest przy wieży Strahada, z której widać portowe miasteczko Zapadkę. Udaj się tam, gdy będziesz $ggotów:gotowa;.', 'Porozmawiaj z Menarą Rozdzieraczką Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(5021, 'plPL', 'Lepiej późno niż wcale', '„Paczka musi zostać dostarczona... dostarczona, zanim zostanę tu uwięziona!”$B$BKrzyki spanikowanej kobiety zdają się niemal szeptem płynącym przez dom. W kącie na piętrze kuli się zjawa kobiety. Nie wydaje się w pełni świadoma otoczenia i tylko mgliście dostrzega twoją obecność.$B$B„Czy jesteś tu, żeby dostarczyć moją paczkę? Proszę, zanim zrobi się jeszcze gorzej! Miałam stąd odjechać konno. Paczka powinna wciąż być przy moim koniu... czy już za późno?”', 'Z bełkotu upiornej kobiety wynika, że trzeba dostarczyć jakąś paczkę. Twierdziła, że jest tam, gdzie jej koń. Gdzie jest koń i dokąd paczka miała trafić – z ducha nie da się tego wydobyć.', '', '', '', '', '', '', 0),
(5022, 'plPL', 'Lepiej późno niż wcale', 'Podnosisz paczkę i ścierasz z niej cienką warstwę kurzu i brudu. Jest pośpiesznie zaadresowana do niejakiej Emmy Felstone z Wichrogrodu; termin doręczenia minął ponad cztery lata temu.$B$BNie wiadomo, czy Emma Felstone w ogóle żyje, ale powszechnie wiadomo, że Ratusz Wichrogrodu prowadzi ewidencję mieszkańców miasta. Zajmują się tym królewscy faktorzy ze spisu ludności Wichrogrodu.', 'Zasięgnij informacji u królewskich faktorów w Wichrogrodzie, by dowiedzieć się, gdzie przebywa niejaka Emma Felstone. Urzędnika spisu ludności zwykle można zastać w Ratuszu.', '', '', '', '', '', '', 0),
(5023, 'plPL', 'Lepiej późno niż wcale', 'Podnosisz paczkę i ścierasz z niej cienką warstwę kurzu i brudu. Jest pośpiesznie zaadresowana do niejakiego Jeremiaha Felstone\'a z Lordaeronu; termin doręczenia minął ponad cztery lata temu.$B$BNie wiadomo, czy Jeremiah Felstone w ogóle żyje, ale powszechnie wiadomo, że Podmiasto, niegdyś zwane Lordaeronem, prowadzi ewidencję mieszkańców miasta. Zajmują się tym królewscy nadzorcy ze spisu ludności Podmiasta.', 'Zasięgnij informacji u królewskich nadzorców w Podmieście, by dowiedzieć się, gdzie przebywa niejaki Jeremiah Felstone. Urzędnika spisu ludności zwykle można zastać w pobliżu miejsca rejestracji gildii i tabardów.', '', '', '', '', '', '', 0),
(5048, 'plPL', 'Poczciwa Emma', 'Jest trochę zrzędliwa i całkiem możliwe, że ma nie po kolei w głowie... ale według ewidencji Stara Emma pasuje do tego, kim mogłaby być Emma Felstone.$B$BMoże $gwidziałeś:widziałaś;, jak Stara Emma wałęsa się po mieście – mówi do siebie, najczęściej jakieś bezsensowne trele-morele. Mimo to nikomu i niczemu nie szkodzi, więc ludzie raczej dają jej spokój.$B$BBiorąc wszystko pod uwagę, powiedziałbym, że Stara Emma to w istocie Emma Felstone. Możesz spróbować ją zapytać, czy rzeczywiście nazywa się Felstone.', 'Odszukaj Starą Emmę w Wichrogrodzie i sprawdź, czy to rzeczywiście Emma Felstone. Jeśli tak, może zechce przyjąć paczkę, którą przygotowała dla niej Janice Felstone.', '', '', '', '', '', '', 0),
(5050, 'plPL', 'Amulet szczęścia', 'Najwyraźniej niesłusznie cię oceniono, $N, i za to należą ci się przeprosiny. Moja siostra przysłała mi sporo osobistych rzeczy, w tym – co dość zabawne – akt własności gospodarstwa Felstone\'ów. Chyba na razie nie będę się starać o jego odzyskanie.$B$BJeśli duch mojej siostry pozostaje przywiązany do gospodarstwa i nie może zaznać spokoju, proszę... czy możesz jej to oddać? To połówka amuletu szczęścia, który miała; drugą połówkę miał jej mąż.$B$BMoże świadomość, że te rzeczy są teraz u mnie, pozwoli jej duszy wreszcie spocząć.', 'Oddaj połówkę amuletu szczęścia Janice Felstone na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5066, 'plPL', 'Do broni: Plagowiska!', 'Słuchajcie, słuchajcie! Niechaj wszyscy bohaterowie wysłuchają tych słów!$B$BKrólestwo Wichrogrodu wzywa do broni! Wszyscy zdolni do walki proszeni są o chwycenie za oręż przeciwko mrocznemu zagrożeniu ze strony Plagi w północnych krainach Wschodnich Królestw! Krążą pogłoski o nowych zagrożeniach powstających z ruin Plagowisk!$B$BBohaterowie królestwa – odszukajcie dowódcę Ashlama Mężnopięść, który założył swoją bazę w Obozie Zimnych Wichrów, na północ od Gór Alterak!', 'Odszukaj dowódcę Ashlama Mężnopięść. Jego baza mieści się w Obozie Zimnych Wichrów, na północ od Gór Alterak.', '', '', '', '', '', '', 0),
(5090, 'plPL', 'Do broni: Plagowiska!', 'Słuchajcie, słuchajcie! Niechaj wszyscy bohaterowie wysłuchają tych słów!$B$BKrólestwo Wichrogrodu wzywa do broni! Wszyscy zdolni do walki proszeni są o chwycenie za oręż przeciwko mrocznemu zagrożeniu ze strony Plagi w północnych krainach Wschodnich Królestw! Krążą pogłoski o nowych zagrożeniach powstających z ruin Plagowisk!$B$BBohaterowie królestwa – odszukajcie dowódcę Ashlama Mężnopięść, który założył swoją bazę w Obozie Zimnych Wichrów, na północ od Gór Alterak!', 'Odszukaj dowódcę Ashlama Mężnopięść. Jego baza mieści się w Obozie Zimnych Wichrów, na północ od Gór Alterak.', '', '', '', '', '', '', 0),
(5091, 'plPL', 'Do broni: Plagowiska!', 'Słuchajcie, słuchajcie! Niechaj wszyscy bohaterowie wysłuchają tych słów!$B$BKrólestwo Wichrogrodu wzywa do broni! Wszyscy zdolni do walki proszeni są o chwycenie za oręż przeciwko mrocznemu zagrożeniu ze strony Plagi w północnych krainach Wschodnich Królestw! Krążą pogłoski o nowych zagrożeniach powstających z ruin Plagowisk!$B$BBohaterowie królestwa – odszukajcie dowódcę Ashlama Mężnopięść, który założył swoją bazę w Obozie Zimnych Wichrów, na północ od Gór Alterak!', 'Odszukaj dowódcę Ashlama Mężnopięść. Jego baza mieści się w Obozie Zimnych Wichrów, na północ od Gór Alterak.', '', '', '', '', '', '', 0),
(5095, 'plPL', 'Do broni: Plagowiska!', 'Bohaterowie królestwa, posłuchajcie mnie – Horda wzywa was do szybkiego działania!$B$BOgłoszono wezwanie do broni dla wszystkich zdolnych do walki, by chwycili za oręż przeciw Pladze! Krążą plotki o nowych zagrożeniach, które powstają z ruin Wschodnich Królestw. Czają się na wschód od Podmiasta, w północnych rubieżach krain znanych dziś jako Plagowiska!$B$BBohaterowie królestwa – odszukajcie najwyższego egzekutora Derringtona, który rozbił obóz przy Barykadzie, na wschód od Gajów Tirisfalskich!', 'Odszukaj najwyższego egzekutora Derringtona. Jego obóz znajduje się przy Barykadzie, na wschód od Gajów Tirisfalskich i Podmiasta.', '', '', '', '', '', '', 0),
(5923, 'plPL', 'Odpowiedź na wezwanie', 'Przepraszam, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Mathrengyl Niedźwiedzi Krok rozesłał wieść, iż chce z tobą porozmawiać. Wygląda na to, że twoje druidzkie szkolenie nabierze nowego życia, a on sam będzie cię szkolić. Mathrengyl jest bezpośrednim pomocnikiem samego arcydruida i jednym z najmądrzejszych i najdostojniejszych druidów, jakich spotkasz na Teldrassilu.$B$BZnajdziesz go w Enklawie Cenariona w Darnassus, na piętrze drzewa Fandrala Jeleniorogiego.', 'Porozmawiaj z Mathrengylem Niedźwiedzim Krokiem w Enklawie Cenariona w Darnassus.', '', '', '', '', '', '', 0),
(5924, 'plPL', 'Odpowiedź na wezwanie', 'Przepraszam, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Mathrengyl Niedźwiedzi Krok rozesłał wieść, iż chce z tobą porozmawiać. Wygląda na to, że twoje druidzkie szkolenie nabierze nowego życia, a on sam będzie cię szkolić. Mathrengyl jest bezpośrednim pomocnikiem samego arcydruida i jednym z najmądrzejszych i najdostojniejszych druidów, jakich spotkasz na Teldrassilu.$B$BZnajdziesz go w Enklawie Cenariona w Darnassus, na piętrze drzewa Fandrala Jeleniorogiego.', 'Porozmawiaj z Mathrengylem Niedźwiedzim Krokiem w Enklawie Cenariona w Darnassus.', '', '', '', '', '', '', 0),
(5925, 'plPL', 'Odpowiedź na wezwanie', 'Przepraszam, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Mathrengyl Niedźwiedzi Krok rozesłał wieść, iż chce z tobą porozmawiać. Wygląda na to, że twoje druidzkie szkolenie nabierze nowego życia, a on sam będzie cię szkolić. Mathrengyl jest bezpośrednim pomocnikiem samego arcydruida i jednym z najmądrzejszych i najdostojniejszych druidów, jakich spotkasz na Teldrassilu.$B$BZnajdziesz go w Enklawie Cenariona w Darnassus, na piętrze drzewa Fandrala Jeleniorogiego.', 'Porozmawiaj z Mathrengylem Niedźwiedzim Krokiem w Enklawie Cenariona w Darnassus.', '', '', '', '', '', '', 0),
(6071, 'plPL', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Dazalara w Dolanaar. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Dazalarem w Dolanaar na Teldrassilu.', '', '', '', '', '', '', 0),
(6072, 'plPL', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Dazalara w Dolanaar. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Dazalarem w Dolanaar na Teldrassilu.', '', '', '', '', '', '', 0),
(6073, 'plPL', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Dazalara w Dolanaar. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Dazalarem w Dolanaar na Teldrassilu.', '', '', '', '', '', '', 0),
(6074, 'plPL', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Grifa Serce Dziczy w Kharanos. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Grifem Serce Dziczy w Kharanos w Dun Morogh.', '', '', '', '', '', '', 0),
(6075, 'plPL', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Grifa Serce Dziczy w Kharanos. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Grifem Serce Dziczy w Kharanos w Dun Morogh.', '', '', '', '', '', '', 0),
(6076, 'plPL', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Grifa Serce Dziczy w Kharanos. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Grifem Serce Dziczy w Kharanos w Dun Morogh.', '', '', '', '', '', '', 0),
(6141, 'plPL', 'Brat Anton', 'Mój towarzysz broni, brat Anton, usłyszał pogłoski o inwazji nieumarłych w dalekim Kalimdorze, w krainie zwanej Mrocznym Pustkowiem. Anton natychmiast wykupił rejs w tamte strony, by odnaleźć i zniszczyć nieumarłe zagrożenie!$B$BSzuka ludzi dość odważnych i zdeterminowanych, by mu pomóc. Jeśli twoje serce jest szczere, porozmawiaj z Antonem. Przebywa w Mrocznym Pustkowiu, w osadzie Przymierza zwanej Punktem Nijela.', 'Porozmawiaj z bratem Antonem w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(6182, 'plPL', 'Pierwszy i ostatni', 'Nathanos Marris był pierwszym i ostatnim ludzkim lordem tropicieli. Uczeń Sylwany Bieżywiatr, obecnie Królowej Banshee Porzuconych.$B$BSądziliśmy, że Nathanos poległ pięć lat temu w obronie Lordaeronu. Choć jego ciała nigdy nie odnaleziono, zakładano, że nie wydostał się ze Wschodnich Plagowisk.$B$BMathias Shaw bada sprawę jego zniknięcia i może mieć nowe informacje. Natychmiast się u niego zamelduj. Przebywa na Starym Mieście, w koszarach.', 'Porozmawiaj z Mathiasem Shawem na Starym Mieście w Wichrogrodzie. Przebywa w koszarach.', '', '', '', '', '', '', 0),
(6183, 'plPL', 'Uczczenie zmarłych', 'Sprawę Marrisa przydzielono pięciu moim najlepszym agentom terenowym. Wrócił jeden, tylko po to, by trzy dni później umrzeć we śnie.$B$BTo niewiele, co zdołaliśmy z niego wyciągnąć, było bezładnym bełkotem. Rozróżniliśmy dwa słowa: „Nathanos” i „Herold Plagi”.$B$BNie mam wolnych ludzi, by kontynuować to śledztwo, a Krukowisko nam nie pomoże. Musimy dotrzeć do sedna tej sprawy – choćby po to, by rodziny zmarłych mogły zamknąć ten rozdział. Pomożesz?', 'Jeśli chcesz przyjąć jego zadanie, porozmawiaj ponownie z Mathiasem Shawem.', '', '', '', '', '', '', 0),
(6184, 'plPL', 'Flint Shadowmore', 'Jedyne, co zatem na razie wiemy, to że Nathanos Marris mógł zginąć z rąk tego Herolda Plagi. Zakładamy, że Herold Plagi to ten sam potwór, który rozprawił się z moimi agentami.$B$BFlint Shadowmore, inny agent WW:7, stacjonuje w obozie Przymierza w Punkcie Zimnych Wichrów na Zachodnich Plagowiskach. Odszukaj go; zapozna cię z obecną sytuacją na Plagowiskach i przydzieli ci zadanie.$B$BPowodzenia, $N.', 'Udaj się do Obozu Zimnych Wichrów na Zachodnich Plagowiskach i spotkaj się ze swoim łącznikiem, Flintem Shadowmore\'em.$B', '', '', '', '', '', '', 0),
(6186, 'plPL', 'Nadchodzi Herold Plagi', '<Wygląda na to, że z twarzy Flinta odpłynęła cała krew.>$B$BNa... Nathanos to zrobił? Nathanos jest Heroldem Plagi?$B$BDlaczego? On był... był taki szlachetny – lord tropicieli szanowany przez wszystkich. Jedyny człowiek, któremu kiedykolwiek pozwolono szkolić się u wysokich elfów. A teraz bezwzględny agent Porzuconych?$B$BPrzy... przykro mi, że cię o to proszę, $N, ale król Wrynn musi natychmiast dowiedzieć się o tym obrocie spraw. Proszę, wróć do Wichrogrodu i przekaż mu te wieści.', 'Wróć do Wichrogrodu i powiadom króla Variana Wrynna o losie Nathanosa Marrisa.', '', '', '', '', '', '', 0),
(6187, 'plPL', 'Trzeba przywrócić porządek', 'Wiesz, ilu lordów tropicieli jest na tym świecie? Ilu ludzkich lordów tropicieli było kiedykolwiek?$B$BDokonania Nathanosa były bezprecedensowe. Był geniuszem taktyki, któremu Przymierze zawdzięczało zwycięstwa w ciągu dekady walk.$B$BA teraz... czempion Porzuconych.$B$BNie. Tak być nie może. Trzeba przywrócić porządek.$B$BZbierz armię, $N. Wróć ze swoją armią na Plagowiska i zniszcz Herolda Plagi.$B$BŻyczę ci szczęścia, $N. Naprawdę będzie ci potrzebne w tej bitwie.', 'Zbierz armię i wyrusz na Wschodnie Plagowiska. Przypuść zmasowany atak na Nathanosa Herolda Plagi i wszelkie plugastwo Hordy, które spróbuje go chronić.$B$BZachowaj czujność, $N. Horda będzie bronić lorda tropicieli za cenę własnego życia.', '', 'Wróć do króla Variana Wrynna w Kniei Elwynn.', '', '', '', '', 0),
(6261, 'plPL', 'Dungar Długołyk', '$N, zebrałem w tej skrzyni wszystko, o co prosił Lewis. Zaniesiesz mu ją?$B$BJeśli już $grozmawiałeś:rozmawiałaś; z Thorem w Zachodnim Skraju, możesz polecieć do niego gryfem. Dungar Długołyk to nasz mistrz gryfów, tam, w Dzielnicy Handlowej.$B$BPorozmawiaj z Dungarem, a potem jak najszybciej dostarcz tę skrzynię Lewisowi. Nie chcemy, żeby nasi żołnierze i żołnierki w Zachodnim Skraju zostali bez nowego ekwipunku!', 'Zanieś skrzynię Osrica mistrzowi gryfów Dungarowi Długołykowi.', '', '', '', '', '', '', 0),
(6281, 'plPL', 'Dalej do Wichrogrodu', 'Za niewielką opłatą możesz polecieć gryfem do Wichrogrodu i dostarczyć liścik Lewisa Osricowi. Szybciej się tam nie dostaniesz.$B$BJeśli ci to odpowiada, po prostu porozmawiaj ze mną ponownie, gdy będziesz $ggotów:gotowa; do lotu. Wezmę od ciebie trochę grosza, ale uwierz mi, będzie warto!', 'Wykup lot gryfem u mistrza gryfów Thora, a następnie zanieś liścik Lewisa Osricowi Strangowi do sklepu „Ograniczona Odporność” na Starym Mieście w Wichrogrodzie.', '', '', '', '', '', '', 0),
(6285, 'plPL', 'Powrót do Lewisa', 'Mistrzem gryfów w Zachodnim Skraju jest Thor. Jeśli już z nim $grozmawiałeś:rozmawiałaś;, możesz polecieć do niego jednym z moich gryfów.$B$BTo dobra lekcja: gryfy zawsze są wyszkolone, by latać do swojej stolicy, ale do odległego mistrza gryfów zabiorą cię dopiero wtedy, gdy już tam $gbyłeś:byłaś;.$B$BU Thora już $gbyłeś:byłaś;, więc po prostu porozmawiaj ze mną ponownie, gdy będziesz $ggotów:gotowa; polecieć gryfem do Zachodniego Skraju. Na miejscu możesz oddać skrzynię Osrica kwatermistrzowi Lewisowi.', 'Wykup u mistrza gryfów Dungara Długołyka lot gryfem na Wzgórze Strażnicze, a następnie zanieś skrzynię Osrica Lewisowi na Wzgórzu Strażniczym.', '', '', '', '', '', '', 0),
(6402, 'plPL', 'Spotkanie w Wichrogrodzie', 'Masz spotkać się z Windsorem u bram Wichrogrodu.$B$BTo, co Windsor zamierza ujawnić, wstrząśnie samymi fundamentami królestwa!$B$BNie próbuj wyruszać tam w pojedynkę, $N. Musisz zebrać armię! Zgromadź swoich towarzyszy. Do broni!$B$B', 'Udaj się do Wichrogrodu i idź do bram miasta. Porozmawiaj z giermkiem Rowe\'em, by mógł powiadomić marszałka Windsora o twoim przybyciu.', '', '', '', '', '', '', 0),
(6403, 'plPL', 'Wielka maskarada', 'To była nie lada przygoda, $gprzyjacielu:przyjaciółko;. Mam wobec ciebie ogromny dług wdzięczności. Może, kiedy już będzie po wszystkim...$B$BJak zapewne już się $gzorientowałeś:zorientowałaś;, lady Prestor to Onyxia, pomiot Śmiercioskrzydłego, siostra bliźniaczka Nefariana, tyrana Iglicy.$B$BZbyt długo więziła nasze królestwo swoim urzekającym spojrzeniem. Nawet najwyższym lordem steruje za pomocą swoich podstępów – jest jej marionetką. Dziś to wszystko się skończy... Czar zostanie złamany.$B$BNie martw się, bo razem zwyciężymy!$B$BCzy jesteś $ggotów:gotowa;?', 'Podążaj za Reginaldem Windsorem przez Wichrogród. Chroń go przed niebezpieczeństwem!', 'Marsz Reginalda', '', '', '', '', '', 0),
(6501, 'plPL', 'Smocze oko', 'Mogę ci dać jedynie odłamek strzaskanego medalionu.$B$BMusisz odnaleźć kogoś innego ze smoczej krwi, kto zechce pomóc ci wykuć nowy klucz. Gdy zdobędziesz ten klucz, musisz udać się na Żmijowe Trzęsawisko na Pyłowym Bagnisku. To tam znajdziesz jej leże, $N.$B$BGdzie szukać innych stad skłonnych do pomocy? Niestety, nie wiem... Mówi się, że istnieją. Niektórzy mogą nawet pracować i żyć wśród nas, przebrani za przedstawicieli ras humanoidalnych. Życzę ci szczęścia.$B', 'Musisz przemierzyć świat w poszukiwaniu istoty zdolnej przywrócić moc odłamkowi smoczego oka. Jedyne, co wiesz o takiej istocie, to że istnieje.', '', '', '', '', '', '', 0),
(6722, 'plPL', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Dazalara w Dolanaar. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Dazalarem w Dolanaar na Teldrassilu.', '', '', '', '', '', '', 0),
(7023, 'plPL', 'Praojciec Mróz przybył!', 'Cudownej Zimowej Uczty, $gprzyjacielu:przyjaciółko;! Koniecznie przywitaj się z Praojcem Mrozem, który gości właśnie w Żelaznej Kuźni! Jeśli w tym roku $gbyłeś grzeczny:byłaś grzeczna;, w dzień Zimowej Uczty dostaniesz cudowne smakołyki. Nie zapomnij mu powiedzieć, co chcesz dostać w tym roku!$B$BZaopatrz się też w smakołyki dla tych, którzy byli w tym roku grzeczni. Mamy wspaniały wybór. Prosto z naszej farmy na twój talerz – zdrowe smakołyki od Wędzonych Pastwisk!', 'Porozmawiaj z Praojcem Mrozem; znajdziesz go w Żelaznej Kuźni, w pobliżu stoisk Wędzonych Pastwisk.', '', '', '', '', '', '', 0),
(7493, 'plPL', 'Podróż dopiero się zaczęła', '', '', '', '', '', '', '', '', 0),
(7494, 'plPL', 'Warownia Lunopiórej', '$N! Twoja pomoc jest potrzebna w Feralas!$B$BWyjęta spod prawa magini, Lethtendris, uciekła do starożytnych elfich ruin Eldre\'thalas, zwanych dziś Srogomłotami. Podobno ma przy sobie przedmiot o niebezpiecznej energii magicznej, który trzeba odzyskać.$B$BLatronicus Księżycowa Włócznia szuka śmiałków, którzy wejdą do Srogomłotów i odbiorą ten przedmiot Lethtendris.$B$BSłuż Przymierzu! Odszukaj Latronicusa w Warowni Lunopiórej w Feralas.', 'Porozmawiaj z Latronicusem Księżycową Włócznią w Warowni Lunopiórej w Feralas.', '', '', '', '', '', '', 0),
(7495, 'plPL', 'Zwycięstwo Przymierza', '$GDokonałeś:Dokonałaś; niemożliwego. Matka Czarnego Stada smoków leży martwa u twoich stóp. Weź jej głowę i zanieś ją królowi Varianowi Wrynnowi.', 'Zanieś głowę Onyxii królowi Varianowi Wrynnowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(7496, 'plPL', 'Czas świętowania', 'Odszukaj majora Mattingly\'ego w Dolinie Bohaterów, $N. Będzie na ciebie czekał...', 'Odszukaj majora Mattingly\'ego w Dolinie Bohaterów.', '', '', '', '', '', '', 0),
(7497, 'plPL', 'Podróż dopiero się zaczęła', '', '', '', '', '', '', '', '', 0),
(7562, 'plPL', 'Mor\'zul Zwiastun Krwi', '$N, głęboko $gzgłębiłeś:zgłębiłaś; mroczne sztuki. Twoja władza nad istotami z innych światów jest już tak silna... że może jesteś $ggotów:gotowa;, by związać ze sobą jednego z osławionych upiornych rumaków.$B$BRytuał przyzwania bestii z jej rodzimego świata wymaga wielkiej mocy i zasobów, ale jeśli pragniesz zapanować nad tym epickim wierzchowcem, porozmawiaj z Mor\'zulem Zwiastunem Krwi. Obozuje w pobliżu Ołtarza Burz na Płonących Stepach.$B$BIdź, $N. To zadanie będzie niebezpieczne, ale $gczarnoksiężnik twojej rangi nie ucieka:czarnoksiężniczka twojej rangi nie ucieka; przed niebezpieczeństwem!', 'Porozmawiaj z Mor\'zulem Zwiastunem Krwi przy Ołtarzu Burz na Płonących Stepach.', '', '', '', '', '', '', 0),
(7637, 'plPL', 'Przede wszystkim poświęcenie', 'Aby przygotować się do tego zadania, musisz najpierw wykazać się należytym poświęceniem i osądem... przede wszystkim poświęceniem.$B$BDo tego zadania musisz zdobyć kadzielnicę egzorcyzmu wielkiego kapłana Rohana. Choć zostanie użyta w dobrej i słusznej sprawie, należy się za nią odpowiednia rekompensata.$B$BUdaj się do Żelaznej Kuźni i porozmawiaj z wielkim kapłanem. Jeśli przyniesiesz dość monet, by wynagrodzić mu utratę kadzielnicy, wykażesz się należytym poświęceniem.$B$BIdź już, $N, czas nagli.', 'Udaj się do Żelaznej Kuźni i zdobądź kadzielnicę egzorcyzmu wielkiego kapłana Rohana. Aby ją otrzymać, musisz przekazać datek w wysokości 150 sztuk złota.', '', '', '', '', '', '', 0),
(7638, 'plPL', 'Lord Grayson Cieniołamacz', 'Nadszedł czas, $N, byś $gdowiedział:dowiedziała; się, czego wymaga zdobycie czegoś, na co bez wątpienia długo $gczekałeś:czekałaś;... twojego szarżownika.$B$BPorozmawiaj z lordem Graysonem Cieniołamaczem tutaj, w Dzielnicy Katedralnej Wichrogrodu. To on wprowadzi cię nie tylko w tajniki najwierniejszego wierzchowca paladyna, ale i w zadania, które czekają cię na drodze do zdobycia własnego.$B$BŻyczę ci powodzenia w tej próbie. Za Światłość, $gszlachetny bracie:szlachetna siostro;!', 'Porozmawiaj z lordem Graysonem Cieniołamaczem w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7639, 'plPL', 'Należyty osąd', 'Weź kadzielnicę z moim błogosławieństwem. Sam używałem jej podczas kilku egzorcyzmów i powinna ci dobrze służyć w trudnych zadaniach, które cię czekają.$B$BWróć teraz do lorda Graysona Cieniołamacza w Wichrogrodzie, $N. To u niego będziesz kontynuować swoją misję.', 'Zanieś kadzielnicę egzorcyzmu lordowi Graysonowi Cieniołamaczowi w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7640, 'plPL', 'Egzorcyzmy w Dolinie Grozy', 'Dodałem do kadzielnicy szczyptę ziemi ze skażonego gruntu Doliny Grozy na Wschodnich Plagowiskach. Użyjesz jej teraz, by odnaleźć tam miejsca, w których widać oznaki duchowego wzburzenia i niepokoju. Szukaj zielonych aur przenikających ziemię tam, gdzie świat materialny ugina się pod udręką królestwa duchów, i użyj kadzielnicy, by wypędzić złe duchy.$B$BGdy wydasz dostateczny osąd na tamtejsze duchy, będziesz $ggotów:gotowa; do dalszej drogi.', 'Użyj kadzielnicy egzorcyzmu, by wypędzić duchy dręczące Dolinę Grozy. Gdy zabijesz 25 duchów z Doliny Grozy, wróć do lorda Graysona Cieniołamacza w Dzielnicy Katedralnej Wichrogrodu.', '', 'Wróć do lorda Graysona Cieniołamacza w Wichrogrodzie.', '', '', '', '', 0),
(7641, 'plPL', 'Dzieło Grimanda Elmore\'a', 'Szarżownik paladyna bez odpowiedniej zbroi końskiej jest niczym więcej niż zwierzęciem jucznym. Zbroja twojego szarżownika musi być nie tylko wykonana z najlepszych możliwych materiałów, ale ze względu na okoliczności musi też być dostatecznie dostrojona do królestwa duchów.$B$BPo kolei, $N – najpierw trzeba wykonać twoją zbroję. W Dzielnicy Krasnoludów w Wichrogrodzie mieszka jeden z najlepszych żyjących rzemieślników, Grimand Elmore. Jego praca nie będzie tania, ale szukamy właśnie takiej jakości. Porozmawiaj z nim.', 'Porozmawiaj z Grimandem Elmore\'em w Dzielnicy Krasnoludów w Wichrogrodzie.', '', '', '', '', '', '', 0),
(7642, 'plPL', 'Zbiórka materiałów', 'Do zbroi potrzebujesz czterech rzeczy – runicznej tkaniny na podszycie, sztabek arkanitu na płyty, Łez Arthasa do dostrojenia duchowego i wody święconej ze Stratholmu do duchowego nasycenia. Właściwie potrzebujesz pięciu rzeczy... złota na moją zapłatę. Obejmuje ona całą robociznę, a także ręcznie robione siodło i strzemiona.$B$BGdy wszystko zdobędziesz, będę w stanie dokończyć twoją zbroję. Do tego czasu, kiedy ty będziesz zbierać materiały, mogę już zacząć nad niektórymi rzeczami pracować.', 'Przynieś 40 sztuk runicznej tkaniny, 6 sztabek arkanitu, 10 Łez Arthasa, 5 fiolek wody święconej ze Stratholmu i 150 sztuk złota Grimandowi Elmore\'owi w Dzielnicy Krasnoludów w Wichrogrodzie.', '', 'Wróć do Grimanda Elmore\'a w Kniei Elwynn.', '', '', '', '', 0),
(7643, 'plPL', 'Pradawny duch konia', 'Twoja zbroja potrzebuje szczególnego błogosławieństwa, udzielonego przez odpowiedniego ducha. W Srogomłotach przebywa taki duch – Pradawny duch konia. Obecnie więzi go zepsuty drzewiec, Tendris Spaczodrzew. Wydaj osąd na tę plugawą bestię, $N.$B$BWiedz jedno: samo uwolnienie nie wystarczy. Zanim otrzymasz błogosławieństwo, musisz ukoić ducha. Do tego potrzebna jest specjalna pasza dla koni. Najpierw udaj się do Południowego Brzegu i porozmawiaj o tym z Merideth Carlson... i przygotuj się na kolejne poświęcenie.', 'Zdobądź specjalną paszę, którą karmi się duchy koni. Podobno można ją dostać u Merideth Carlson w Południowym Brzegu.$B$BUdaj się do lochów Srogomłotów w Feralas i zabij Tendrisa Spaczodrzewa. W ten sposób uwolnisz Pradawnego ducha konia. Nakarm go specjalną paszą, by go ukoić. Na koniec daj mu arkanitową zbroję końską, by ją pobłogosławił.', '', '', '', '', '', '', 0),
(7644, 'plPL', 'Błogosławiona arkanitowa zbroja końska', 'Gdy zbroja spoczywa na grzbiecie Pradawnego ducha konia, zaczyna lekko jaśnieć. Przez krótką chwilę powietrze gęstnieje od mocy, a potem zbroja znika z grzbietu konia i leży już bezpiecznie w twoim plecaku.$B$BWygląda na to, że zbroja została pobłogosławiona. Zgodnie z poleceniem lorda Cieniołamacza $gpowinieneś:powinnaś; teraz wrócić z nią do niego do Wichrogrodu.', 'Zanieś błogosławioną arkanitową zbroję końską lordowi Graysonowi Cieniołamaczowi w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7646, 'plPL', 'Wróżbiarska kula', 'Teraz musimy złożyć wróżbiarską kulę – to od niej rozpocznie się próba, dzięki której odkupisz poległego szarżownika. Właściwie twoja kula jest prawie gotowa. Jej katalizatorem jest kadzielnica egzorcyzmu, której $gużywałeś:używałaś; w Dolinie Grozy, a ja wykonam dla niej odpowiednią oprawę.$B$BOstatnimi potrzebnymi składnikami są jednak dwa diamenty. Muszą być tak przeciwstawne w blasku, jak i w przeznaczeniu – azerothiański i nieskazitelny czarny. Te dwa kamienie będą latarnią, dzięki której kula przebije cienie!', 'Przynieś azerothiański diament i nieskazitelny czarny diament lordowi Graysonowi Cieniołamaczowi w Dzielnicy Katedralnej Wichrogrodu.', '', 'Wróć do lorda Graysona Cieniołamacza w Wichrogrodzie.', '', '', '', '', 0),
(7647, 'plPL', 'Osąd i odkupienie', 'Weź tę sakwę – są w niej przedmioty, których będziesz potrzebować.$B$BUżyj wróżbiarskiej kuli w samym sercu podziemi Wielkiego Ossuarium, by przywołać przeklęte duchy, które trzeba osądzić. Rozważnie korzystaj z osądów podczas tej próby – okażą się potężniejsze, niż myślisz. Po duchach pojawi się rycerz śmierci; pokonaj go i odzyskaj utraconą duszę szarżownika. Dopiero wtedy, $N, będziesz $gmógł:mogła; go odkupić i założyć zbroję na swojego nowego wierzchowca!$B$BPowodzenia!', 'Użyj wróżbiarskiej kuli w samym sercu podziemi Wielkiego Ossuarium w Scholomancjum. Przywoła ona duchy, które musisz osądzić. Pokonanie tych duchów przyzwie rycerza śmierci Mrocznego Łupieżcę. Pokonaj go i odzyskaj utraconą duszę poległego szarżownika.$B$BOddaj odkupioną duszę szarżownika i błogosławioną arkanitową zbroję końską poległemu szarżownikowi Mrocznego Łupieżcy.', '', 'Wróć do poległego szarżownika Mrocznego Łupieżcy.', '', '', '', '', 0),
(7648, 'plPL', 'Najlepsze dzieło Grimanda', '<Grimand ociera pot z czoła, promieniejąc z dumy.>$B$BProszę bardzo, $gprzyjacielu:przyjaciółko;. To jedno z moich najlepszych dzieł – równie dobre jak zbroja, którą osobiście wykonałem dla lorda Cieniołamacza, gdy zdobywał własnego szarżownika. Dziękuję, że $gzaufałeś:zaufałaś; mi, że zapewnię ci to, co najlepsze.$B$BGrayson na pewno też zechce obejrzeć tę robotę. Zanieś mu zbroję i przekaż podziękowania za uczciwe interesy.', 'Zanieś arkanitową zbroję końską do obejrzenia lordowi Graysonowi Cieniołamaczowi w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7666, 'plPL', 'Znów do Wielkiego Ossuarium', '', '', '', '', '', '', '', '', 0),
(7669, 'plPL', 'Znów do Wielkiego Ossuarium', '', '', '', '', '', '', '', '', 0),
(7670, 'plPL', 'Lord Grayson Cieniołamacz', 'Nadszedł czas, $N, byś $gdowiedział:dowiedziała; się, czego wymaga zdobycie czegoś, na co bez wątpienia długo $gczekałeś:czekałaś;... twojego szarżownika.$B$BPorozmawiaj z lordem Graysonem Cieniołamaczem w Dzielnicy Katedralnej Wichrogrodu. To on wprowadzi cię nie tylko w tajniki najwierniejszego wierzchowca paladyna, ale i w zadania, które czekają cię na drodze do zdobycia własnego.$B$BŻyczę ci powodzenia w tej próbie. Za Światłość, $gszlachetny bracie:szlachetna siostro;!', 'Porozmawiaj z lordem Graysonem Cieniołamaczem w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7781, 'plPL', 'Władca Czarnej Góry', 'Powraca dawne uczucie. Rozkoszne ukłucie zwycięstwa rozbrzmiewa w całym twoim jestestwie. Przed tobą leży monumentalna, poznaczona bliznami bitew głowa Nefariana. Zanieś ją królowi Varianowi Wrynnowi, $gczempionie:czempionko;.', 'Zanieś głowę Nefariana królowi Varianowi Wrynnowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(7782, 'plPL', 'Władca Czarnej Góry', 'Udaj się do Doliny Bohaterów i porozmawiaj z feldmarszałkiem Afrasiabim.', 'Udaj się do Doliny Bohaterów w Wichrogrodzie i porozmawiaj z feldmarszałkiem Afrasiabim.', '', '', '', '', '', '', 0),
