INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(24658, 'plPL', 'Dobra robota, $gmały:mała;. Coś ci się za to należy. I słuchaj, wpadnij jutro, jeśli znajdziesz czas; może będę miał dla ciebie robotę.', 0),
