(24663, 'plPL', 'Dobra robota, $gmały:mała;. Coś ci się za to należy. I słuchaj, wpadnij jutro, jeśli znajdziesz czas; może będę miał dla ciebie robotę.', 0),
(24664, 'plPL', 'Dobra robota, $gmały:mała;. Coś ci się za to należy. I słuchaj, wpadnij jutro, jeśli znajdziesz czas; może będę miał dla ciebie robotę.', 0),
(24665, 'plPL', 'Dobra robota, $gmały:mała;. Coś ci się za to należy. I słuchaj, wpadnij jutro, jeśli znajdziesz czas; może będę miał dla ciebie robotę.', 0),
(24666, 'plPL', 'Dobra robota, $gmały:mała;. Coś ci się za to należy. I słuchaj, wpadnij jutro, jeśli znajdziesz czas; może będę miał dla ciebie robotę.', 0),
(24745, 'plPL', 'Co tam masz?$B$BOho, to gruba sprawa. Naprawdę gruba. Większość tych wariackich szczegółów w jednej paczuszce. Dzięki – naprawdę nam $gpomogłeś:pomogłaś; wszystko to poskładać. Dobrze się z tobą pracowało.', 0),
(24792, 'plPL', 'Fantastycznie. Pomoc to dokładnie to, czego mi trzeba.', 0),
(24793, 'plPL', 'Fantastycznie. Pomoc to dokładnie to, czego mi trzeba.', 0),
(24804, 'plPL', 'Hej. Masz trochę wolnego czasu? Przydałby mi się ktoś taki jak ty.', 0),
(24805, 'plPL', 'Hej. Masz trochę wolnego czasu? Przydałby mi się ktoś taki jak ty.', 0),
(24848, 'plPL', 'Ty... Ty nie jesteś Snivel. To on cię przysyła? Tak bardzo się spóźnia, że zaczynałam już tracić nadzieję...$B$B<Gdy kobieta uświadamia sobie, że nie masz dla niej wiadomości od Snivela, w jej oczach wzbierają łzy.>$B$BTo niepodobne do mojego Snivela, ale jakie mam wyjście?', 0),
(24849, 'plPL', 'Mówił tylko o tym, że wyjeżdża z miasta ze wszystkimi swoimi pieniędzmi? Czyli naprawdę mnie porzucił, prawda?$B$BOch, $N. Byłam taka głupia, że się w nim zakochałam, ale jak mogłam się oprzeć? Był taki nieodparty!', 0),
(25180, 'plPL', 'Czemu Młot Zmierzchu interesuje się tymi tablicami? Sam Brann napisał, że ledwie rozumie ich znaczenie, choć wspomniał coś o stawaniu się jednym z ziemią. Muszę naradzić się z uczonymi z Ligi Odkrywców, żeby jak najszybciej je odczytać.$B$BDziękuję, $N. Gdyby nie twoja pomoc, te tablice wpadłyby w ręce wroga.', 0),
(25181, 'plPL', 'Czemu Młot Zmierzchu interesuje się tymi tablicami? Ich treść jest zagadką dla naszych najtęższych uczonych, a odczytanie ich zajmie trochę czasu. Skoro Młot Zmierzchu wie o tych reliktach i ich pragnie, co jeszcze knuje?$B$BMamy wielkie szczęście, że $guchroniłeś:uchroniłaś; je przed wrogiem, $N.', 0),
(25253, 'plPL', '<Anton przegląda zebrane przez ciebie zwoje.>$B$BKtokolwiek przygotował te ulotki, wie, jak przyciągnąć uwagę, a sądząc po tym, co się dzieje na Starym Mieście, zainteresowania nie brakuje. Musimy działać, zanim zdobędą w mieście liczne grono zwolenników. Obawiam się, że wykorzystają swoje wpływy, by siać panikę w całym mieście i nas sparaliżować.$B$BMusimy przeniknąć do tej organizacji i dowiedzieć się jak najwięcej.', 0),
(25254, 'plPL', 'Dobra robota, $N. Teraz musimy się skupić na tym, by dowiedzieć się więcej o tym kulcie i uwolnić ludzi, których podstępem nakłonił do przyłączenia się.', 0),
(25282, 'plPL', 'Dobra robota, $N. Teraz musimy się skupić na tym, by dowiedzieć się więcej o tym kulcie i uwolnić ludzi, których podstępem nakłonił do przyłączenia się.', 0),
(25288, 'plPL', 'Witaj, $gprzyjacielu:przyjaciółko;. To dla nas zaszczyt, że $gpostanowiłeś:postanowiłaś; przyjąć prawdę i do nas dołączyć. Chodź, na rozmowy przyjdzie jeszcze czas, a musisz się wiele nauczyć.', 0),
(25290, 'plPL', 'Witaj, $gprzyjacielu:przyjaciółko;. To dla nas zaszczyt, że $gpostanowiłeś:postanowiłaś; przyjąć prawdę i do nas dołączyć. Chodź, na rozmowy przyjdzie jeszcze czas, a musisz się wiele nauczyć.', 0),
(25414, 'plPL', 'Więc ich $gznalazłeś:znalazłaś;? Dlaczego zaginieni mężczyźni i kobiety nie wrócili z tobą?$B$B<Mówisz kapitanowi, że z różnych powodów byli zdecydowani zostać.>$B$BW takim razie nie możemy zmusić ich do powrotu do domu. Mogę tylko mieć nadzieję, że z czasem kultyści zrozumieją, jaką krzywdę wyrządzają, i postanowią wrócić do normalnego życia.$B$BDziękuję za twoje starania, $N. Powiem rodzinom, czego się $gdowiedziałeś:dowiedziałaś;.', 0),
(25417, 'plPL', '<Wręczasz kapitanowi Antonowi urządzenia, które dała ci nadzorczyni, i wyjaśniasz plany kultu.>$B$BTo Cho\'gall przewodzi kultowi? W takim razie to musi być Młot Zmierzchu! Podejrzewaliśmy, że spróbują uderzyć znowu, ale nikt nie wiedział, jaką formę przybierze atak.$B$BŚwietnie się $gspisałeś:spisałaś;, demaskując ten spisek. Niestety nie tylko ciebie wysłano do miasta, by rozmieścić te urządzenia.', 0),
(25418, 'plPL', 'Doskonała robota, $N. Młot Zmierzchu zastanowi się dwa razy, zanim znów spróbuje obrócić przeciw nam naszych własnych ludzi.$B$BNiepokoi mnie tylko, ilu mieszkańców przyłączyło się do ich ruchu, nie zastanawiając się nad pustymi obietnicami kultu. Czy czasy są aż tak ciężkie, że ludzie porzucają Światłość dla obietnic mocy i nieśmiertelności?', 0),
(25425, 'plPL', '<Na twarzy króla maluje się niepokój, a potem gniew, gdy opisujesz spisek Młota Zmierzchu, który miał zniszczyć Wichrogród.>$B$BJak śmią atakować Wichrogród? Jak śmią podburzać mieszkańców tego miasta przeciw nam i Przymierzu! Gdyby nie twoje męstwo tego dnia, $N, nasze miasto nie odkryłoby tego spisku Młota Zmierzchu. Jesteś $gprawdziwym bohaterem:prawdziwą bohaterką; Wichrogrodu i Przymierza.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(97, 'plPL', 'Tak, $N?', 0),
(98, 'plPL', 'Tak, $N?', 0),
(120, 'plPL', 'Co tam masz?', 0),
(121, 'plPL', 'Czy generał przysłał wieści? Czy posiłki są w drodze?', 0),
(135, 'plPL', 'Jaką masz do mnie sprawę? Jestem bardzo zajętym człowiekiem...', 0),
(141, 'plPL', 'Czy mistrz Shaw rzucił na tę sprawę jakieś światło?', 0),
(167, 'plPL', '$GZnalazłeś:Znalazłaś; jakiś ślad mojego brata? Czy po tak długim czasie jest jeszcze jakaś nadzieja?', 0),
(168, 'plPL', 'Udało ci się odzyskać legitymacje Związku Górników moich dawnych towarzyszy z pracy?', 0),
(171, 'plPL', 'Miło cię znowu widzieć, $N. Czy $gwywiązałeś:wywiązałaś; się z obowiązków, których $gpodjąłeś:podjęłaś; się w Tygodniu Dziecka?', 0),
(212, 'plPL', '$N! Masz ten udziec? Muszę wkrótce zacząć go przyrządzać, bo inaczej bankiet będzie zrujnowany!', 0),
(269, 'plPL', 'Odpocznij, $gbracie:siostro;. Widzę, że $gprzebyłeś:przebyłaś; długą drogę i dźwigasz ciężkie brzemię. Powiesz mi, co rzuca na ciebie ten mroczny cień?', 0),
(293, 'plPL', 'Co to za kula? Wygląda na... splugawioną.', 0),
(322, 'plPL', 'W czym mogę ci służyć swoim rzemiosłem, $N?', 0),
(325, 'plPL', 'Witaj, $N. Nie było cię niedługo, ale widzę w twoich oczach ogień, którego wcześniej nie widziałem.', 0),
(332, 'plPL', 'Witaj, $N, rozgość się. $GPróbowałeś:Próbowałaś; już któregoś z naszych wybornych win?', 0),
(333, 'plPL', 'Masz wieści od pana Bagleya?', 0),
(334, 'plPL', '$GPrzyszedłeś:Przyszłaś; kupić ubrania?', 0),
(335, 'plPL', 'Wishock wkrótce zbierze dość poparcia, by narobić nam mnóstwo kłopotów. Udało ci się już zdobyć Łzę Tilloi albo korzeń piżmaka?', 0),
(336, 'plPL', 'Nie widzisz, że jestem zajęty? Moje słowa muszą zostać wysłuchane! Jestem bardzo ważny dla przyszłości tego królestwa!$B$BO... a co ty tam masz? Ależ to wygląda na orzeźwiający napój...', 0),
(337, 'plPL', 'Ooo! Co to za stara księga? Mogę ją zobaczyć??', 0),
(353, 'plPL', '$GPrzybyłeś:Przybyłaś; aż z Wichrogrodu? Słyszałem, że na ludzkich ziemiach robi się niebezpiecznie – wszędzie grasują rozbójnicy i orkowie. Idealne miejsce, by $c $gmógł:mogła; się wykazać!', 0),
(373, 'plPL', 'Tak? Mogę ci w czymś pomóc?', 0),
(387, 'plPL', 'Kazamaty wciąż są w rękach więźniów! Te szczury z Nieskornych muszą się przekonać, że nie będziemy tolerować ich wybryków. Wracaj tam na dół i pokaż im siłę!', 0),
(388, 'plPL', 'Widzę, że $gwróciłeś:wróciłaś;, $N. $GZebrałeś:Zebrałaś; już 10 czerwonych wełnianych chust od tych szumowin z Nieskornych w Kazamatach?', 0),
(391, 'plPL', 'Albo przyniesiesz mi głowę Thredda, albo ja wezmę twoją, rozumiesz, $N?', 0),
(392, 'plPL', 'Tak, $N? Co $gznalazłeś:znalazłaś;?', 0),
(393, 'plPL', 'Witaj. W czym mogę ci służyć, $N?', 0),
(396, 'plPL', '$N, tak? Baros Alexston zapowiedział mi twoje przybycie. Muszę przyznać, że bardzo mnie ciekawi, co masz do powiedzenia.', 0),
(399, 'plPL', '$N! Udało się?', 0),
(434, 'plPL', 'Tak, $N? Wszystko idzie dobrze z Tyrionem? Wprowadził mnie w sytuację, a ja pomogłem mu podstępem ściągnąć Marzona do zamku.$B$BMarzon był solą w oku wielu ludzi w Wichrogrodzie, a spośród nich wielu to moi bliscy przyjaciele. Nikt nie zadziera z moimi przyjaciółmi... jeśli wie, co jest dla niego zdrowe.$B$BSzkoda tylko, że przy okazji pośrednio wyświadczam przysługę Shawowi i WW:7. Cóż, żaden plan nie jest idealny.', 0),
(540, 'plPL', 'Chciałbym sam przeszukać ruiny, ale obawiam się, że te stare kości nie wytrzymałyby wspinaczki w góry. Jak idą twoje poszukiwania wiedzy, $N?', 0),
(542, 'plPL', '$N, $gwróciłeś:wróciłaś;! Jak ci poszła wyprawa do Alterak? $GPrzyniosłeś:Przyniosłaś; coś ze sobą?', 0),
(543, 'plPL', 'Uszanowanie, $N. Postaraj się nie deptać mi po mankietach spodni. Ten strój jest świeżo uszyty.', 0),
(563, 'plPL', 'Witaj, $gobywatelu:obywatelko;. W czym może ci pomóc straż miejska Wichrogrodu?', 0),
(579, 'plPL', 'Król Varian przywiązuje wielką wagę do nauki, dlatego przeznaczył fundusze na sporządzanie kopii rozmaitych ksiąg i pism, które udostępniamy wszystkim mieszkańcom. To bardzo proste. Przynosisz mi kwit biblioteczny, a ja daję ci kopię jednej z dostępnych książek.', 0),
(697, 'plPL', 'Tak? Wyglądasz jakoś znajomo. Najmocniej przepraszam, ale czy myśmy się już spotkali? Mam tyle zajęć, że wszystko mi się myli.', 0),
(1076, 'plPL', 'Witaj, $N. $GZnalazłeś:Znalazłaś; składnik, którego potrzebuję?', 0),
(1077, 'plPL', 'Haha! Jesteś z powrotem! Masz to? Masz zaklęcie?', 0),
(1078, 'plPL', 'Witaj ponownie, $N.$B$BCzyżbyś już $gwrócił:wróciła; ze Zwęglonej Doliny z tymi łuskami?', 0),
(1241, 'plPL', 'Hmpf, lepiej, żebyś $gmiał:miała; dobry powód, by przeszkadzać człowiekowi w łowieniu ryb. Nie przepadam za domokrążcami, a co dopiero za żebrakami.', 0),
(1242, 'plPL', 'Witaj, $N. Czym mogę służyć? Może skosztujesz naszego specjalnego cheddara od Triasa? Albo kostki darnasyjskiego sera pleśniowego?', 0),
(1243, 'plPL', 'Wędrówki po tych lasach nie są zbyt bezpieczne, $N. Uważaj na siebie, a jeśli zobaczysz coś podejrzanego albo groźnego, natychmiast daj znać wartownikom. Nie próbuj niczym zajmować się na własną rękę. Nie odpowiadamy za nic złego, co może cię spotkać.$B$BAle przecież wiemy, że i tak mnie zignorujesz i będziesz walczyć ze wszystkim, co wylezie z ciemności, prawda? Haha, no tak, wy, poszukiwacze przygód... wszyscy jednacy.', 0),
(1244, 'plPL', 'Uważaj na siebie, $N. Wiem, że to Trias cię tu przysłał, ale to nie znaczy, że w lasach nie czai się nic, co mogłoby ci narobić kłopotów... zwłaszcza że węszysz wokół Nieskornych.', 0),
(1245, 'plPL', 'Widzę, że $gwróciłeś:wróciłaś; w jednym kawałku. Dobrze wiemy, że nie przychodzisz tu po ser, więc darujmy sobie uprzejmości. Czy Backus na coś się przydał, czy może jeszcze nawet nie $gwyruszyłeś:wyruszyłaś; do Kniei Zmierzchu?', 0),
(1249, 'plPL', 'Wymknął ci się? Wyglądał dość podejrzanie, tak się na nas gapiąc.', 0),
(1265, 'plPL', 'Tak, $N?', 0),
(1324, 'plPL', 'Witaj ponownie, $N. Mam nadzieję, że nie masz nam za złe tej pomocy, ale nie mogliśmy pozwolić, żeby Hendel uciekł albo, co gorsza, zginął.', 0),
(1338, 'plPL', 'List z krasnoludzkich ziem? Ciekawe, kto pisze z tak daleka, z północy...$B$BPozwól, że rzucę okiem na to zamówienie.', 0),
(1364, 'plPL', 'Co cię sprowadza do Strażnicy Otchłani?', 0),
(1447, 'plPL', 'Nie chciałem cię urazić tym gadaniem, że $gjesteś tępy:jesteś tępa;. Kumple jesteśmy, nie? Bez urazy?', 0),
(1448, 'plPL', 'Przemierzyłem świat od dżungli Azeroth po ośnieżone szczyty Khaz Modan.$B$BNigdy wcześniej nie prosiłem nikogo o pomoc w moich wyprawach. Ale moje stare kości są już zmęczone.$B$BNic nie dałoby mi większej satysfakcji niż świadomość, że ukończyłem ostatnią wyprawę dla Ligi Odkrywców.$B$BJeśli zechcesz pomóc mi w poszukiwaniach Świątyni Atal\'Hakkar, będę ci niezmiernie wdzięczny.$B$BPrzeczesz Moczary Smutków i wróć z tym, czego się dowiesz!', 0),
(1469, 'plPL', 'Nareszcie $gwróciłeś:wróciłaś;, $N. Sporo czasu minęło od naszej ostatniej rozmowy. Myślałem już, że $gzapomniałeś:zapomniałaś; o mojej wyprawie.$B$BCzy $godnalazłeś:odnalazłaś; tego przebiegłego jeźdźca gryfów? Miał coś do zameldowania?', 0),
(1475, 'plPL', 'Gdy nad moją karierą powoli zapada zmierzch, zwracam się do ciebie, $N, byś $gpomógł:pomogła; mi w ostatniej wyprawie dla Ligi Odkrywców. Gdyby moje stare kości znalazły w sobie dość siły, by stawić czoła Moczarom Smutków i zatopionej świątyni, walczyłbym ramię w ramię z tobą.$B$BDuma nie pozwala mi łatwo prosić cię o pomoc w zbieraniu tabliczek Atal\'ai. Ale starość zmusza mnie do tego.$B$BProszę, pomóż mi, $N. Chcę odejść z Ligi Odkrywców na zasłużony odpoczynek, wykonawszy jej ostatnie zlecenie.', 0),
(1644, 'plPL', 'Mam nadzieję, że mój John ma więcej szczęścia w Żelaznej Kuźni. Tak nie lubi tam jeździć, bo zostawia mnie i dzieci samych, ale wie, że to konieczne. Ma takie dobre serce.$B$BBywały lata lżejsze i cięższe, ale ten jest zdecydowanie najcięższy. Jakby coś w powietrzu zwiastowało wielką zmianę. Ale kto to wie?', 0),
(1665, 'plPL', 'Widziałem twoją walkę z Bartlebym. Nieźle! $GZdobyłeś:Zdobyłaś; jego kufel?', 0),
(1688, 'plPL', 'Nawet starszych i mądrzejszych potrafią pozbawić rozsądku powaby młodości i urody, $N. Tę radę warto pamiętać przez całe życie.', 0),
(1689, 'plPL', 'Nie pokażę ci, jak panować nad wędrowcem Pustki, dopóki żadnego nie ujarzmisz.', 0),
(1700, 'plPL', 'Witaj, dobrze cię widzieć. W czym mogę ci pomóc?', 0),
(1701, 'plPL', 'Jak idą poszukiwania, $N? Masz surowce?', 0),
(1702, 'plPL', 'Witaj! Sucho dziś, nie sądzisz?', 0),
(1703, 'plPL', 'Pozdrawiam cię, $N.', 0),
(1704, 'plPL', 'Dzień dobry, a może dobry wieczór. Stąd, z samego dołu, nie poznam, która pora. Masz do mnie jakiś interes?', 0),
(1705, 'plPL', '$N, masz płonącą krew i skałę? Potrzebuję ich, żeby dokończyć zbroję.', 0),
(1738, 'plPL', 'Twoje poszukiwania zakończyły się sukcesem, $N?', 0),
(1739, 'plPL', 'Czasem się zastanawiam, czy Surena nie była sukkubem w przebraniu, zesłanym, by wypaczyć i omotać mój umysł... Ha! Chyba przypisuję jej za dużo zasług.', 0),
(1861, 'plPL', 'Masz próbkę, $N? Przepływ magii w Wichrogrodzie i Elwynn uległ zmianie, a ja muszę wiedzieć, czy nie przesącza się do wody.', 0),
(1920, 'plPL', '$GSchwytałeś:Schwytałaś; te stwory, $n? Trzeba je zbadać, żeby ustalić, dlaczego się tu pojawiły.', 0),
(1921, 'plPL', 'Witaj, $N. Jennea mówiła, że przyjdziesz. Masz coś dla mnie?', 0),
(1938, 'plPL', 'Masz tę księgę, $N? Jej tajemnice nie są przeznaczone dla niewyszkolonych, a zgłębianie ich może prowadzić do zguby i ruiny.', 0),
(1940, 'plPL', 'Ach, tak. Magowie z sanktuarium czarodziejów mówili, że się do mnie zgłosisz. Masz potrzebny jedwab?', 0),
(2040, 'plPL', '$GZnalazłeś:Znalazłaś; Gnoam Sprecklesprocket, $N?', 0),
(2206, 'plPL', 'Z każdą chwilą, którą marnujesz, obijając się w koszarach, ubywa ci życia, $N.', 0),
(2359, 'plPL', 'Jakieś wieści od agentki Kearnen?', 0),
(2746, 'plPL', 'Od paru tygodni obserwuję Lescovara. Trias nigdy mu nie ufał, ale nie podejrzewaliśmy, że ma cokolwiek wspólnego z Bractwem Nieskornych. Szliśmy tropem, który łączył go z Młotem Zmierzchu. Tak czy inaczej, stał się zbyt groźny, by miasto mogło sobie z nim poradzić, i tu wkraczamy my.$b$bZdobądź mi te rzeczy, a wprowadzimy mój plan w życie.', 0),
(2757, 'plPL', 'Rzadki z ciebie okaz, kamracie. Pokaż no tę odznakę.', 0),
(2758, 'plPL', 'Czyżbyś $gmiał zostać kolejnym podopiecznym:miała zostać kolejną podopieczną; Galvana?', 0),
(2759, 'plPL', 'Rzadki z ciebie okaz, kamracie. Pokaż no tę odznakę.', 0),
(2874, 'plPL', 'Czy Stoley wyskoczył z mojej gorzały?', 0),
(2928, 'plPL', 'Gdyby to był wyścig, $gprzegrałbyś:przegrałabyś; już dawno.', 0),
(3526, 'plPL', 'Świeżych rekrutów wyczuwam tak samo jak doskonały proch strzelniczy – z odległości mili. $GPrzyszedłeś:Przyszłaś; zgłębić sztukę wybuchów?', 0),
(3629, 'plPL', 'Świeżych rekrutów wyczuwam tak samo jak doskonały proch strzelniczy – z odległości mili. $GPrzyszedłeś:Przyszłaś; zgłębić sztukę wybuchów?', 0),
(3630, 'plPL', 'Tak, tak, w czym mogę ci dziś pomóc? Oczywiście mam na to czas, skoro jedyne, co robię, to stoję tutaj, podczas gdy nasze ukochane miasto spowija chmura napromieniowanej śmierci.', 0),
(3632, 'plPL', 'Tak, tak, w czym mogę ci dziś pomóc? Oczywiście mam na to czas, skoro jedyne, co robię, to stoję tutaj, podczas gdy nasze ukochane miasto spowija chmura napromieniowanej śmierci.', 0),
(3633, 'plPL', 'Świeżych rekrutów wyczuwam tak samo jak doskonały proch strzelniczy – z odległości mili. $GPrzyszedłeś:Przyszłaś; zgłębić sztukę wybuchów?', 0),
(3634, 'plPL', 'Tak, tak, w czym mogę ci dziś pomóc? Oczywiście mam na to czas, skoro jedyne, co robię, to stoję tutaj, podczas gdy nasze ukochane miasto spowija chmura napromieniowanej śmierci.', 0),
(3636, 'plPL', 'Amnennar musi zostać unicestwiony. Idź, szybko.', 0),
(4181, 'plPL', 'Świeżych rekrutów wyczuwam tak samo jak doskonały proch strzelniczy – z odległości mili. $GPrzyszedłeś:Przyszłaś; zgłębić sztukę wybuchów?', 0),
(4765, 'plPL', 'Powiedziano mi, że przybędzie posłaniec. Z darem z Iglicy Czarnej Góry.$B$BCzy to ty?', 0),
(5022, 'plPL', 'Witaj w biurze spisu ludności Wichrogrodu. Jeśli potrzebujesz informacji o naszych mieszkańcach, mogę ci pomóc.', 0),
(5048, 'plPL', 'Kazałabym ci zejść z mojego trawnika, ale jak widzisz, nie mam trawnika.', 0),
(5050, 'plPL', 'John, skarbie... to ty? Nagle zrobiło mi się tak zimno...', 0),
(5502, 'plPL', 'Miło cię znowu widzieć, $N. Czy $gwywiązałeś:wywiązałaś; się z obowiązków, których $gpodjąłeś:podjęłaś; się w Tygodniu Dziecka?', 0),
(6187, 'plPL', '<Król Varian Wrynn jest pogrążony w myślach.>', 0),
(6261, 'plPL', 'Czy to pot na twoim czole, $gchłopcze:dziewczyno;? Za dużo biegasz. Następnym razem leć gryfem!', 0),
(6281, 'plPL', 'Podróżowało się, co? $GByłeś:Byłaś; w jakimś ciekawym miejscu?', 0),
(6285, 'plPL', '$GWróciłeś:Wróciłaś; z Wichrogrodu? Osric przysłał zbroje?', 0),
(6403, 'plPL', 'Ja... ja... byłem bezsilny.', 0),
(6501, 'plPL', 'Wyczuwam złą aurę, która od ciebie bije, $N. Co takiego możesz mieć przy sobie, że emanuje taką aurą?', 0),
(7495, 'plPL', 'Na brodę Uthera!', 0),
(7637, 'plPL', 'Witaj, $gszlachetny:szlachetna; $N! Napełniłem moją zaufaną kadzielnicę najświeższym kadzidłem i trzykrotnie ją pobłogosławiłem, abyś $gmógł:mogła; jej użyć. Twój datek pomoże nam w Żelaznej Kuźni nie tylko sprawić nową kadzielnicę, ale też uzupełnić kurczące się zapasy żywności dla potrzebujących.', 0),
(7639, 'plPL', 'Witaj z powrotem, $N. Czy masz już kadzielnicę egzorcyzmu?', 0),
(7640, 'plPL', 'Dobrze cię znów widzieć, $N. Czy $gskończyłeś:skończyłaś; swoją pracę w Dolinie Grozy?', 0),
(7642, 'plPL', 'Ach, to ty. Nie dokończę twojej zbroi bez rzeczy, o których mówiłem. $GZebrałeś:Zebrałaś; już wszystko?', 0),
(7643, 'plPL', 'Pradawny duch konia patrzy na ciebie wyczekująco, jakby czegoś od ciebie chciał.', 0),
(7644, 'plPL', '$N, $gwróciłeś:wróciłaś;! Czy udało ci się załatwić sprawę z Merideth Carlson i Tendrisem Spaczodrzewem? Szczerze mówiąc, czasem nie jestem pewien, które z nich jest groźniejsze...', 0),
(7646, 'plPL', '$GPrzebyłeś:Przebyłaś; tak długą drogę, $N. Twoja ostatnia ofiara z doczesnych dóbr da początek jednemu z twoich największych osiągnięć. Czuję to każdą cząstką swojej istoty!', 0),
(7647, 'plPL', 'Duch poległego szarżownika spogląda na ciebie żałośnie. Smutne, niemal puste oczy patrzą tak, jakby straciły wszelką nadzieję.', 0),
(7648, 'plPL', 'Dobrze ci idzie, $N. Gdy już będziesz $gmiał:miała; swoją zbroję, będziesz na dobrej drodze do następnego zadania.', 0),
(7781, 'plPL', 'Nie do wiary!', 0),
(7791, 'plPL', 'Jeśli masz przy sobie sześćdziesiąt sztuk wełnianego płótna i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7792, 'plPL', 'Jeśli masz przy sobie sześćdziesiąt sztuk wełnianego płótna i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7793, 'plPL', 'Taki szczodry dar jak jedwab – pozwolę sobie dodać – z pewnością podniesie twoją pozycję w miejscowej społeczności! Jeśli masz przy sobie sześćdziesiąt sztuk jedwabnego płótna i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7794, 'plPL', 'Jeśli masz przy sobie sześćdziesiąt sztuk tkaniny magów i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7795, 'plPL', '$n, bardzo $gprzysłużyłeś:przysłużyłaś; się naszej zbiórce tkanin. Choć ciężko pracujemy nad uzupełnieniem zapasów, jednej tkaniny wciąż rozpaczliwie brakuje – runicznej. Bardzo jej potrzebujemy i mamy nadzieję, że pomożesz nam tak jak dotąd!$b$bJeśli zechcesz, przynieś mi tyle runicznej tkaniny, ile możesz oddać. Na początek przyjmiemy jednorazowy dar sześćdziesięciu sztuk, a potem zobaczymy.', 0),
(7796, 'plPL', 'Gdy tylko zechcesz oddać porcję runicznej tkaniny, przyjmę ją.', 0),
(7798, 'plPL', 'Taki szczodry dar jak jedwab – pozwolę sobie dodać – z pewnością podniesie twoją pozycję w miejscowej społeczności! Jeśli masz przy sobie sześćdziesiąt sztuk jedwabnego płótna i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7799, 'plPL', 'Jeśli masz przy sobie sześćdziesiąt sztuk tkaniny magów i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7800, 'plPL', '$n, bardzo $gprzysłużyłeś:przysłużyłaś; się naszej zbiórce tkanin. Choć ciężko pracujemy nad uzupełnieniem zapasów, jednej tkaniny wciąż rozpaczliwie brakuje – runicznej. Bardzo jej potrzebujemy i mamy nadzieję, że pomożesz nam tak jak dotąd!$b$bJeśli zechcesz, przynieś mi tyle runicznej tkaniny, ile możesz oddać. Na początek przyjmiemy jednorazowy dar sześćdziesięciu sztuk, a potem zobaczymy.', 0),
(7801, 'plPL', 'Gdy tylko zechcesz oddać porcję runicznej tkaniny, przyjmę ją.', 0),
(7806, 'plPL', 'Gdy tylko zechcesz oddać porcję runicznej tkaniny, przyjmę ją.', 0),
(7809, 'plPL', 'Jeśli masz przy sobie sześćdziesiąt sztuk tkaniny magów i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
