INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(344, 0, 'plPL', 'Kim jest ten $c, który staje przed Sądem Jeziernych Włości w Królestwie Wichrogrodu? Wyłóż, jaką masz sprawę w tym miasteczku. Zagrożenie ze strony orków jest dla królestwa zbyt wielkie, by trwonić czas na próżne pogawędki.', 0),
(656, 0, 'plPL', 'Wszędzie byli złodzieje! $b$bTo było straszne. Jaskinia zawaliła się na nas. Chyba cała ekipa górników nie żyje, łącznie z moim bratem, brygadzistą.', 0),
(1092, 0, 'plPL', 'Witaj, $n.', 0),
(1141, 0, 'plPL', 'Jeśli przychodzisz tu dla jedzenia, to witaj! Lepszej kuchni nie znajdziesz w całym Wichrogrodzie... ani w całym Azeroth!$B$BJeśli zaś sprowadzają cię inne sprawy, to proszę, streszczaj się. Mam w przygotowaniu tuzin dań i każdego muszę doglądać.', 0),
(1284, 0, 'plPL', 'Witaj, $n.', 0),
(1343, 0, 'plPL', 'No proszę, $gmłody:młoda;, $gpełen:pełna; zapału $c, bez wątpienia $gprzyciągnięty:przyciągnięta; tu opowieściami o moich wyczynach na polach bitew!$B$BTeraz nie ma czasu na historie, bo czekają wielkie, ważne czyny! Jeśli więc szukasz chwały, to los ci dziś sprzyja...', 0),
(1428, 0, 'plPL', 'Witaj, $n.', 0),
(1646, 0, 'plPL', 'Witaj, jestem Baros Alexston, architekt miejski Wichrogrodu.', 0),
(1719, 0, 'plPL', 'Tutaj, ty nicponiu...! Jeśli chcesz się na coś przydać, słuchaj uważnie!', 0),
(1748, 0, 'plPL', 'Jestem Bolvar Fordragon, najwyższy lord Wichrogrodu.', 0),
(2086, 0, 'plPL', 'Witaj, $n.', 0),
(2277, 0, 'plPL', 'Mam mnóstwo pracy. $GPrzyszedłeś:Przyszłaś; pomóc mi w badaniach?', 0),
(2285, 0, 'plPL', 'Moja rodzina szczyci się najwspanialszą kolekcją biżuterii i dzieł sztuki spośród wszystkich szlachciców Wichrogrodu!$B$BI zawsze chętnie ją powiększamy...', 0),
(4077, 0, 'plPL', 'Jeśli zdobędę odpowiednie składniki, zrobimy materiały wybuchowe, które nie tylko pozwolą mi zaszkodzić interesom spółki Gitgeszeft, ale też odwrócą uwagę.$B$BWiem, że robi to na tobie wrażenie, ale będzie jeszcze lepiej... Wkrótce powiem ci więcej.', 0),
(4078, 0, 'plPL', 'Witaj, $gprzyjacielu:przyjaciółko;. Co mogę dla ciebie zrobić?', 0),
(4080, 0, 'plPL', 'Witaj, $n.', 0),
(4201, 0, 'plPL', 'Witaj, $n.', 0),
(4454, 0, 'plPL', 'Witaj, $n.', 0),
(4630, 0, 'plPL', 'Witaj, $n.', 0),
(4794, 0, 'plPL', 'Prowadzenie badań w Theramore to ciekawe zajęcie, ale w tym mieście naprawdę trudno o miękkie łóżko!', 0),
(5636, 0, 'plPL', 'Witaj, $n.', 0),
(6169, 0, 'plPL', 'Jestem na wyprawie. Na wyprawie! Na wyprawie po nowe stopy i twardsze metale do największego wynalazku wszech czasów!!', 0),
(6179, 0, 'plPL', 'Paladyna Światłości czeka wiele prób, $N. Bądź $gpewien:pewna;, że nasze ścieżki jeszcze nieraz się skrzyżują, jeśli zachowasz żarliwość i wierność cnotom, które wysławiamy.', 0),
(6569, 0, 'plPL', 'Tam, gdzie krążą troggi i trędowate gnomy, stoi nasz dom – Gnomoregan.$B$BNasze rodziny zaginione, domy utracone. Rozproszeni.$B$BOch, jakże tęsknię za dniami beztroskiego życia w Gnomoregan, ale te dni minęły. Musimy stawić opór! Musimy ocalić Gnomoregan!', 0),
(6579, 0, 'plPL', 'Za Gnomoregan!', 0),
(16478, 0, 'plPL', 'Dzień dobry, $gobywatelu:obywatelko;. Chcesz nam pomóc w walce z Plagą?', 0),
(16494, 0, 'plPL', 'Dzień dobry, $gobywatelu:obywatelko;. Chcesz nam pomóc w walce z Plagą?', 0),
(16786, 0, 'plPL', 'Witaj, $n. Jeśli przyniesiesz mi nekrotyczne kamienie od nieumarłych najeźdźców, udostępnię ci zapasy Argentowego Brzasku.', 0),
(16787, 0, 'plPL', 'Witaj, $n. Jeśli przyniesiesz mi nekrotyczne kamienie od nieumarłych najeźdźców, udostępnię ci zapasy Argentowego Brzasku.', 0);
