(2676, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">STOPNIE WOJSKOWE PRZYMIERZA</H1><BR/>\n<P align="center">OFICEROWIE</P><BR/>\n<P align="center">Wielki marszałek</P>\n<P align="center">Feldmarszałek</P>\n<P align="center">Marszałek</P>\n<P align="center">Komandor</P>\n<P align="center">Komandor porucznik</P>\n<P align="center">Rycerz-czempion</P>\n<P align="center">Rycerz-kapitan</P>\n<P align="center">Rycerz-porucznik</P>\n<P align="center">Rycerz</P><BR/>\n<P align="center">PODOFICEROWIE I SZEREGOWI</P><BR/>\n<P align="center">Chorąży</P>\n<P align="center">Starszy sierżant</P>\n<P align="center">Sierżant</P>\n<P align="center">Kapral</P>\n<P align="center">Szeregowy</P><BR/>\n</BODY>\n</HTML>', 0),
