(2855, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">PODOFICEROWIE I SZEREGOWI HORDY</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Pierwszy sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Starszy sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Siepacz</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Zwiadowca</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(2856, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">STOPNIE OFICERSKIE PRZYMIERZA</H1><BR/>\n<P align="center">Część 2</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">Rycerz-czempion</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">Rycerz-kapitan</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">Rycerz-porucznik</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">Rycerz</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(3039, 'plPL', 'Nie stój nad moim grobem we łzach, nie ma mnie tam, nie śpię w prochach.\nJestem w tysiącu wiatrów, co w dal lecą, nad śniegi Północnej Grani, co jasno świecą.\nJestem łagodnym deszczem nad polami, nad Zachodniego Skraju złotymi łanami.\nJestem w ciszy o świcie, co trwa w Cierniodławach, w zielonej dżungli, w jej bujnych trawach.\nJestem w bębnach, co biją wielko i dumnie, w grzmocie kopyt, co przez Nagrand pędzą tłumnie.\nJestem gwiazdami, co ciepło jaśnieją nad Darnassus, śniącym cicho z nadzieją.\nJestem w ptakach, co śpiewają o świcie, w każdej pięknej rzeczy, co tętni życiem.\nNie stój nad moim grobem, nie płacz przy nim, nie ma mnie tam. Ja nie umieram.', 0),
(3106, 'plPL', '1. Jeśli moc trucizny ci nie odpowiada, podwój składniki albo zmniejsz je o połowę.\n2. Jeśli trucizna nie działa tak, jak chcesz, zawsze mylisz się bardziej, niż ci się wydaje.\n3. Prototypy, prototypy, prototypy (gnomy świetnie nadają się na obiekty doświadczalne).\n4. Po truciznę powinno się łatwo sięgać, a trudno z niej zrezygnować.\n5. Proste składniki współgrają, tworząc ciekawą złożoność.', 0),
(3536, 'plPL', 'Wasza Królewska Mość,$B$Bo miłosierny królu, niech Światłość powstrzyma Twą dłoń i umocni Twe serce. Wstrzymaj swój osąd nad $gtym upadłym czempionem:tą upadłą czempionką; – choćby na chwilę – i wysłuchaj moich słów.$B$B$gOkaziciel:Okazicielka; tego listu to $gdawny bohater:dawna bohaterka; Przymierza. Choć niesie ze sobą odór śmierci i wygląda jak sługa Plagi, ma duszę czempiona. Duszę, która dopiero niedawno połączyła się z ciałem.$B$B', 0),
(3537, 'plPL', '$N reprezentuje nowy, zjednoczony front przeciwko Królowi Liszowi, zwany Rycerzami Hebanowego Miecza. Tak, Wasza Królewska Mość, rycerze śmierci zwrócili się przeciwko swemu dawnemu panu. Przewodzi im syn lorda Alexandrosa Mograine\'a – Spopielacza. Pragną tego, czego i my pragniemy, czego pragniemy wszyscy: końca Plagi.$B$BNie proszę, by $N i Rycerze Hebanowego Miecza zostali przyjęci do Przymierza, a jedynie o to, byś okazał im tolerancję.$B', 0),
(3538, 'plPL', 'Pamiętaj, panie: krwią i honorem wszyscy służymy.$B$BZ wyrazami szacunku$B$BNajwyższy lord Tirion Fordring$B', 0),
(3611, 'plPL', 'Gdzie będziesz, gdy płomienie pochłoną Azeroth?\n\nWiemy, że nikt nie lubi rozmyślać o nadciągającej zagładzie, ale warto się zastanowić, gdzie spędzisz wieczność.\n\nNasi mędrcy przepowiedzieli, że koniec świata jest bliski i że przetrwają tylko przygotowani. Możemy pomóc ci przetrwać szalejące piekło, które oczyści ten świat z niegodziwców. Czy nie czas zaznać spokoju ducha?', 0),
(3612, 'plPL', 'Bez wątpienia $gsłyszałeś:słyszałaś; powiedzenie „wszystko, co dobre, kiedyś się kończy” – i tak też jest z twoim życiem w Azeroth. Już niedługo świat pogrąży się w chaosie, gdy żywioły upomną się o swoje przyrodzone prawa.\n\nAle w tych przerażających czasach nie musisz się bać. Nie musisz umierać. Możemy pomóc ci wznieść się ku nowemu życiu – poza śmiercią, poza strachem i poza bezsilnością śmiertelnego bytu. Dołącz do nas już dziś.', 0),
(3613, 'plPL', 'Żyjemy w burzliwych czasach. Wojna, najazdy i głód przetoczyły się przez świat, lecz prawdziwa próba dopiero nadchodzi: koniec samego Azeroth.\n\nJak zniesiesz utratę i zniszczenie wszystkiego, co ci drogie? Odpowiedź brzmi: nie musisz. Przyprowadź przyjaciół i rodzinę na jedno z naszych spotkań i dowiedz się, jak możecie przetrwać apokalipsę razem – z nami.', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(1244, 'plPL', 'No proszę, kogo my tu mamy! Ktoś młody i pełen zapału, bez wątpienia $gzwabiony:zwabiona; opowieściami o moich wyczynach na polach bitew!$B$BNie czas teraz na historie, bo czekają wielkie i ważne czyny do dokonania! Jeśli więc szukasz chwały, to los ci dziś sprzyja...', 'No proszę, kogo my tu mamy! Ktoś młody i pełen zapału, bez wątpienia $gzwabiony:zwabiona; opowieściami o moich wyczynach na polach bitew!$B$BNie czas teraz na historie, bo czekają wielkie i ważne czyny do dokonania! Jeśli więc szukasz chwały, to los ci dziś sprzyja...', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(4782, 'plPL', 'Witaj, $gbracie:siostro;. Jeśli przychodzisz się szkolić, z radością cię wyszkolę.$B$BKrążą plotki o niesnaskach w Kręgu Cenariona, ale nie zwracaj uwagi na takie gadanie. Nasz arcydruid, Fandral Jeleniorogi, prowadzi nas i cały Teldrassil ku chwale!', 'Witaj, $gbracie:siostro;. Jeśli przychodzisz się szkolić, z radością cię wyszkolę.$B$BKrążą plotki o niesnaskach w Kręgu Cenariona, ale nie zwracaj uwagi na takie gadanie. Nasz arcydruid, Fandral Jeleniorogi, prowadzi nas i cały Teldrassil ku chwale!', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50026, 'plPL', 'Jeśli zdobędę odpowiednie składniki, zrobimy materiały wybuchowe, dzięki którym nie tylko zaszkodzę interesom spółki Gitgeszeft, ale też odwrócę uwagę.$B$BWiem, że robi to na tobie wrażenie, ale będzie jeszcze lepiej... Wkrótce powiem ci więcej.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
