INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(131, 'plPL', 'Myślisz, że są tu jakieś ryby?', 'Myślisz, że są tu jakieś ryby?', 0),
(132, 'plPL', 'W zeszłym tygodniu złapałem wielką rybę, miała troje oczu!', 'W zeszłym tygodniu złapałem wielką rybę, miała troje oczu!', 0),
(133, 'plPL', 'Mój tata mówi, że w oceanie są ryby tak wielkie, że mogłyby połknąć cały statek.', 'Mój tata mówi, że w oceanie są ryby tak wielkie, że mogłyby połknąć cały statek.', 0),
(134, 'plPL', 'Mój tata złowi więcej ryb niż twój tata!', 'Mój tata złowi więcej ryb niż twój tata!', 0),
(135, 'plPL', 'Patrz! Patrz! Coś złapałem! Eee... to tylko stary, śmierdzący but.', 'Patrz! Patrz! Coś złapałem! Eee... to tylko stary, śmierdzący but.', 0),
(136, 'plPL', 'A właśnie że nie.', 'A właśnie że nie.', 0),
(138, 'plPL', 'Kłamczuch!', 'Kłamczuch!', 0),
(139, 'plPL', 'Słyszałem, że są takie wielgachne ryby, które potrafią chodzić po lądzie, polują i zjadają ludzi!', 'Słyszałem, że są takie wielgachne ryby, które potrafią chodzić po lądzie, polują i zjadają ludzi!', 0),
(140, 'plPL', 'A raz na obozie złapałem rybę większą ode mnie!!', 'A raz na obozie złapałem rybę większą ode mnie!!', 0),
(141, 'plPL', 'Słyszałem opowieść o złotej rybce – kto ją złowi, temu spełni trzy życzenia!', 'Słyszałem opowieść o złotej rybce – kto ją złowi, temu spełni trzy życzenia!', 0),
(142, 'plPL', 'Gdybyś łowił tak dobrze, jak gadasz, w oceanie nie zostałaby ani jedna ryba.', 'Gdybyś łowił tak dobrze, jak gadasz, w oceanie nie zostałaby ani jedna ryba.', 0),
(143, 'plPL', 'Ciii! Płoszysz ryby.', 'Ciii! Płoszysz ryby.', 0),
(144, 'plPL', 'Zmyślasz.', 'Zmyślasz.', 0),
(145, 'plPL', 'Gdybyś złowił rybę tak wielką jak twoja gęba, już nigdy nie bylibyśmy głodni.', 'Gdybyś złowił rybę tak wielką jak twoja gęba, już nigdy nie bylibyśmy głodni.', 0),
(146, 'plPL', 'Może chodźmy łowić na most.', 'Może chodźmy łowić na most.', 0),
(147, 'plPL', 'Naprawdę?', 'Naprawdę?', 0),
(149, 'plPL', 'I właśnie tak Lothar zabił trzydziestu sześciu orków gołymi rękami!', 'I właśnie tak Lothar zabił trzydziestu sześciu orków gołymi rękami!', 0),
(150, 'plPL', 'I tak rycerze stanęli naprzeciw szarżującej Hordy i nie ustąpili ani o krok, gdy przez dolinę waliło tysiąc oszalałych orków.', 'I tak rycerze stanęli naprzeciw szarżującej Hordy i nie ustąpili ani o krok, gdy przez dolinę waliło tysiąc oszalałych orków.', 0),
(151, 'plPL', 'Mówią, że czasem potrafi zamienić się w kruka.', 'Mówią, że czasem potrafi zamienić się w kruka.', 0),
(152, 'plPL', 'Wiesz, czemu orkom oczy świecą na czerwono? Bo piją krew!', 'Wiesz, czemu orkom oczy świecą na czerwono? Bo piją krew!', 0),
(153, 'plPL', 'Łyżka nie istnieje.', 'Łyżka nie istnieje.', 0),
(154, 'plPL', 'Słowo daję, ludzie naprawdę ich widzieli. Pandareni naprawdę istnieją!', 'Słowo daję, ludzie naprawdę ich widzieli. Pandareni naprawdę istnieją!', 0),
(155, 'plPL', 'A wtedy królik po prostu odgryzł mu głowę... słowo daję.', 'A wtedy królik po prostu odgryzł mu głowę... słowo daję.', 0),
(156, 'plPL', 'Wiesz, że w Kanałach żyją krokoliszki? Ktoś przywiózł je z bagien jako zwierzaki, a potem wyrzucił do kanałów.', 'Wiesz, że w Kanałach żyją krokoliszki? Ktoś przywiózł je z bagien jako zwierzaki, a potem wyrzucił do kanałów.', 0),
(157, 'plPL', 'Łał.', 'Łał.', 0),
(158, 'plPL', 'A tak, słyszałem o tym.', 'A tak, słyszałem o tym.', 0),
(166, 'plPL', 'Oj, daj spokój, to nieprawda.', 'Oj, daj spokój, to nieprawda.', 0),
(167, 'plPL', 'Ale fajnie.', 'Ale fajnie.', 0),
(168, 'plPL', 'Mój ojciec mówi, że to tylko bajka.', 'Mój ojciec mówi, że to tylko bajka.', 0),
(169, 'plPL', 'Wyobrażasz to sobie?', 'Wyobrażasz to sobie?', 0),
(170, 'plPL', 'To mi wygląda na jedną z rybackich bajek Billy\'ego.', 'To mi wygląda na jedną z rybackich bajek Billy\'ego.', 0),
(171, 'plPL', 'Chyba coś słyszałem.', 'Chyba coś słyszałem.', 0),
(172, 'plPL', 'Chyba coś widzę.', 'Chyba coś widzę.', 0),
(173, 'plPL', 'Fuj... to nie jest ryba!', 'Fuj... to nie jest ryba!', 0),
(174, 'plPL', 'Mam na butach flaki z robaka.', 'Mam na butach flaki z robaka.', 0),
(175, 'plPL', 'Coś tu dziwnie pachnie.', 'Coś tu dziwnie pachnie.', 0),
(176, 'plPL', 'Mam nadzieję, że to była ryba!', 'Mam nadzieję, że to była ryba!', 0),
(177, 'plPL', 'W tych kanałach chyba nie ma żadnych ryb.', 'W tych kanałach chyba nie ma żadnych ryb.', 0),
(178, 'plPL', 'Robak idzie na haczyk, haczyk idzie do wody. Ryba jest w wodzie, nasza ryba.', 'Robak idzie na haczyk, haczyk idzie do wody. Ryba jest w wodzie, nasza ryba.', 0),
(179, 'plPL', 'Poratujesz jakim groszem?', '', 0),
(181, 'plPL', 'Datek dla ubogiego?', '', 0),
(182, 'plPL', 'Chętnie oddam ci we wtorek za dzisiejszego hamburgera.', '', 0),
(183, 'plPL', 'Poratujesz biedaka?', '', 0),
(184, 'plPL', 'Grosik dla biednego ślepca? ...Jak to nie jestem ślepy? ...NIE JESTEM ŚLEPY! WIDZĘ!! To cud!', '', 0),
(185, 'plPL', 'Wypucuję ci zbroję za miedziaka.', '', 0),
(186, 'plPL', 'To wszystko ich wina, tej głupiej armii Przymierza. Musieli postawić te swoje wieże akurat za moją farmą.', '', 0),
(187, 'plPL', 'To wszystko ich wina, tych głupich orków. Musieli puścić moją farmę z dymem.', '', 0),
(201, 'plPL', '', 'Gdybyśmy odwróciły przepływy esencji, może udałoby się zmienić polaryzację.', 0),
(203, 'plPL', '', 'Wtedy układ zaklęć przeszedłby kaskadowo w reakcję łańcuchową dodatnio naładowanych energii.', 0),
(204, 'plPL', '', 'Portal lekko się przesunie, a jeśli w tym momencie rzucisz prosty czar wiążący, utrwalisz go w miejscu.', 0),
(205, 'plPL', '', 'Gdy energie o dodatnim ustawieniu zderzają się z energiami naładowanymi ujemnie, wcale się nie znoszą.', 0),
(206, 'plPL', '', 'Maginor mówi, że splatanie naprzemiennych przepływów dodatniej energii daje w rzeczywistości znacznie stabilniejszy przepływ.', 0),
(207, 'plPL', '', 'W tym punkcie strumień energii powinien wspierać magiczne osłony na tyle, by utrzymały tę istotę.', 0),
(208, 'plPL', '', 'A czemu nie możemy po prostu przesunąć układu, żeby wyrównać wahania strumienia?', 0),
(209, 'plPL', '', 'Dwanaście ośrodków skupienia mogłoby pozwolić magicznym energiom uformować się trwalej, a to dałoby potrzebną stabilność.', 0),
(210, 'plPL', '', 'A co, jeśli wynikowe przesunięcie częstotliwości pośle magiczne sprzężenie zwrotne w górę przepływów?', 0),
(211, 'plPL', '', 'Czy splot się wtedy nie rozplecie, jeśli nie zakotwiczy się go porządnie przed rozpoczęciem zaklęcia?', 0),
(212, 'plPL', '', 'Ale czy to nie oznacza skrzyżowania strumieni? To chyba bardzo źle?', 0),
(213, 'plPL', '', 'Tylko że wynikowe energie mogą się zapaść, a wtedy powstanie strumień energii, po którym migrena trzyma tygodniami.', 0),
(214, 'plPL', '', 'Ale czy nie od tego właśnie zaczęły się problemy z magicznymi formułami adeptki Sylerii?', 0),
(215, 'plPL', '', 'Raczej nie, nie mam ochoty znowu wylecieć w powietrze.', 0),
(216, 'plPL', '', 'Ale to zaburzy równowagę magicznego skupienia i wywoła odwrotne drgania w eterze.', 0),
(217, 'plPL', '', 'To chyba mogłoby się udać, gdybyśmy miały dwadzieścia osób do rzucenia zaklęcia.', 0),
(218, 'plPL', '', 'A gdyby tak użyć trzech ognisk skupienia we wzorze tyreańskim? To powinno załatwić sprawę.', 0),
(219, 'plPL', '', 'Ale jeśli ustabilizujemy to nicią kotwiczącą w odpowiednim węźle energii, powinno zadziałać.', 0),
(220, 'plPL', '', 'Zawsze taka pesymistka. Szanse, że tak się stanie, mieszczą się między zerem a niczym.', 0),
(221, 'plPL', '', 'Jeśli zastosujemy właściwą sekwencję, nic nam nie będzie. Trzeba tylko porządnie się pouczyć, zanim zaczniemy.', 0),
(222, 'plPL', '', 'No, no, tyle zachodu dla eliksiru miłości. Oby był tego wart.', 0),
(223, 'plPL', '', 'Według teorii suriańskiej tak, ale przy podejściu y\'seriańskim już nie.', 0),
(224, 'plPL', '', 'Przynajmniej nie będzie nas już na świecie, więc nie my będziemy po tym sprzątać.', 0),
(225, 'plPL', '', 'Tylko wtedy, gdybyśmy nie zachowały właściwych procedur inicjacji.', 0),
(253, 'plPL', '', 'Corbett, kochanie. Harlan potrzebuje partii dzierganych koszul i spodni, najszybciej jak się da.', 0),
(254, 'plPL', '', 'Corbett, jesteś tam? Harlan potrzebuje kolejnej partii dzianin. Zaniesiesz mu?', 0),
(261, 'plPL', 'Ach, bardzo dziękuję, Corbett. Zaraz powiesimy je na wieszakach.', '', 0),
(262, 'plPL', 'Ach, tak, i dostarczone w samą porę. Jak zawsze, przyjemnie robić z tobą interesy, Corbett.', '', 0),
(286, 'plPL', '', 'Dzień dobry, Corbett. Oto twój ser, świeżo zrobiony dziś rano! A jak tam w twoim sklepie?', 0),
(287, 'plPL', '', 'Cześć, Corbett! Proszę bardzo! Mam nadzieję, że w twoim sklepie z odzieżą interes się kręci...?', 0),
(322, 'plPL', 'Czas na moją medytację, zostaw mnie.', '', 0),
(323, 'plPL', 'Nareszcie jesteś. Jakie wieści z Zachodniego Skraju?', '', 0),
(324, 'plPL', 'VanCleef przesyła wiadomość, że plany są w toku. Ale doszły go plotki, że ktoś tu węszy.', '', 0),
(326, 'plPL', 'Hmm, to może być ten wścibski Shaw. Zobaczę, czego się dowiem. A teraz odejdź. Wkrótce znów się z tobą skontaktuję.', '', 0),
(387, 'plPL', 'Ojej, ten stout z Czarnego Szponu ma niezłego kopa!', '', 0),
(388, 'plPL', 'Coś mi się... kręci w głowie. Ale tu... jest... gorąco...', '', 0),
(587, 'plPL', '', 'Witaj, Charys. Mam tu listę – podasz mi to wszystko? Zwłaszcza ostatni składnik.', 0),
(588, 'plPL', '', 'Mamusiu? Mogę pogłaskać Syczka?', 0),
(589, 'plPL', '', 'Pewnie, Paige. Tylko delikatnie.', 0),
(590, 'plPL', '', 'Dziękuję, Charys. Chodź, Paige, skarbie.', 0),
(693, 'plPL', 'Ha, ha! Mam Betsy!', '', 0),
(694, 'plPL', '', 'Oddawaj moją lalę!!', 0),
(695, 'plPL', '', 'Betsy! Oddaj mi Betsy!', 0),
(696, 'plPL', '', 'Nie rób krzywdy Betsy, ty wstręciuchu!', 0),
(697, 'plPL', '', 'BUUUUU!!!', 0),
(698, 'plPL', '', 'Powiem mamie!', 0),
(699, 'plPL', '', 'Przestań wyrywać jej włosy!', 0),
(700, 'plPL', '', 'To ją boli!', 0),
(701, 'plPL', '', 'Przestań! Urwiesz jej głowę!', 0),
(705, 'plPL', 'Ciekawe, czy twoja lala umie pływać!', '', 0),
(706, 'plPL', 'Mam twoją lalę! Tere-fere!', '', 0),
(707, 'plPL', 'A co będzie, jak zrobię tak?!', '', 0),
(708, 'plPL', 'Jak chcesz ją odzyskać, musisz ładnie poprosić!', '', 0),
(709, 'plPL', 'Beksa! Beksa!', '', 0),
(710, 'plPL', 'Dzidzia chce swoją lalę!', '', 0),
(711, 'plPL', 'Ups!', '', 0),
(794, 'plPL', 'Hep!', '', 0),
(1086, 'plPL', 'Chodź, spróbujemy gdzie indziej.', 'Chodź, spróbujemy gdzie indziej.', 0),
(1091, 'plPL', 'Billy mówi, że Syczek był kiedyś wielkim czarodziejem. Ale jedno zaklęcie mu nie wyszło i zamieniło go w królika.', 'Billy mówi, że Syczek był kiedyś wielkim czarodziejem. Ale jedno zaklęcie mu nie wyszło i zamieniło go w królika.', 0),
(1093, 'plPL', 'Czemu idziemy tędy?', 'Czemu idziemy tędy?', 0),
(1094, 'plPL', 'Dokąd idziemy?', 'Dokąd idziemy?', 0),
(1095, 'plPL', 'Chce mi się siku.', 'Chce mi się siku.', 0),
(1097, 'plPL', 'Chcę zobaczyć wieżę magów.', 'Chcę zobaczyć wieżę magów.', 0),
(1098, 'plPL', 'To prawda? W kanałach naprawdę są krokoliszki?', 'To prawda? W kanałach naprawdę są krokoliszki?', 0),
(1099, 'plPL', 'Bolą mnie nogi.', 'Bolą mnie nogi.', 0),
(1100, 'plPL', 'Czemu zawsze chodzimy tą samą drogą?', 'Czemu zawsze chodzimy tą samą drogą?', 0),
(1102, 'plPL', 'Ciepły, pożywny chleb!', '', 0),
(1103, 'plPL', 'Bułki, rogale i chleb. Prosto z pieca!', '', 0),
(1104, 'plPL', 'Świeżo upieczony chleb na sprzedaż!', '', 0),
(1105, 'plPL', '', '„Gdzie woda, Emmo?” „Przynieś wodę, Emmo!” Gdyby nie ja, ta banda nie wiedziałaby nawet, jak woda wygląda.', 0),
(1106, 'plPL', '', 'Jakbym na stare lata nie miała nic lepszego do roboty niż noszenie wiader z wodą.', 0),
(1107, 'plPL', '', 'Chyba ze sto razy dziennie łażę aż do studni po wodę. Żadnego szacunku dla starszych, mówię ci.', 0),
(1108, 'plPL', '', 'No pewnie, że gadam do siebie. Tylko tak można w tym mieście porządnie pogadać.', 0),
(1109, 'plPL', '', 'Któregoś dnia utopię go w tej jego niebieskiej szacie. I wszystkie jego miotły też.', 0),
(1110, 'plPL', '', 'Jack i Jill, akurat, a mój pomarszczony zadek! To ja tu dźwigam całą wodę.', 0),
(1111, 'plPL', '', 'Chyba zaczynam wydeptywać koleinę w bruku.', 0),
(1112, 'plPL', '', 'Déjà vu. Przez chwilę myślałam, że znów jestem w domu... sprzed zarazy...', 0),
(1129, 'plPL', '', 'Oto Katedra Światła, ośrodek duchowego oświecenia tu, w Wichrogrodzie.', 0),
(1130, 'plPL', 'A po co w ogóle mamy się tego uczyć?', 'A po co w ogóle mamy się tego uczyć?', 0),
(1131, 'plPL', 'To lepsze niż obrazki w księgach do historii.', 'To lepsze niż obrazki w księgach do historii.', 0),
(1132, 'plPL', 'Chcę zobaczyć szkielet smoka w wielkiej bibliotece.', 'Chcę zobaczyć szkielet smoka w wielkiej bibliotece.', 0),
(1133, 'plPL', 'Proszę pani, a kiedy zobaczymy tę błyszczącą wieżę magów?', 'Proszę pani, a kiedy zobaczymy tę błyszczącą wieżę magów?', 0),
(1134, 'plPL', 'Słyszałem, że pod spodem wciąż leżą pogrzebani orkowie.', 'Słyszałem, że pod spodem wciąż leżą pogrzebani orkowie.', 0),
(1136, 'plPL', 'Proszę pani, muszę siku!', 'Proszę pani, muszę siku!', 0),
(1138, 'plPL', 'Proszę pani, a czy w Wichrogrodzie są nocne elfy? Jeszcze nigdy nie widziałem nocnego elfa.', 'Proszę pani, a czy w Wichrogrodzie są nocne elfy? Jeszcze nigdy nie widziałem nocnego elfa.', 0),
(1139, 'plPL', 'Proszę pani, on mnie ciągle szturcha!', 'Proszę pani, on mnie ciągle szturcha!', 0),
(1140, 'plPL', '', 'Oto Twierdza Wichrogród. Wzniesiono ją na ruinach zamku Wichrogrodu, który Horda zburzyła podczas pierwszej Wielkiej Wojny.', 0),
(1153, 'plPL', 'To prawda, że tutaj szkolą się paladyni?', 'To prawda, że tutaj szkolą się paladyni?', 0),
(1154, 'plPL', '', 'Tak, to prawda. Za murami Katedry zarówno paladyni, jak i kapłani doskonalą swoje umiejętności i zgłębiają wielkie prawdy.', 0),
(1155, 'plPL', '', 'Dzieci, proszę za mną – teraz pójdziemy obejrzeć twierdzę, w której na tronie zasiada sam król Varian Wrynn.', 0),
(1161, 'plPL', '', 'Gdy Horda została rozbita, ludzie wrócili tutaj i zaczęli odbudowywać wspaniałe niegdyś miasto – na świadectwo tego, że przetrwaliśmy.', 0),
(1162, 'plPL', '', 'Tak, no cóż... chodźmy teraz do pomnika ku czci bohaterów obu Wielkich Wojen – do Doliny Bohaterów. Za mną.', 0),
(1163, 'plPL', '', 'Czyż to nie zdumiewające, dzieci? Każdy, kto wchodzi do miasta, musi przejść pod czujnym okiem największych bohaterów naszych ziem.', 0),
(1165, 'plPL', '', 'Zapiera dech w piersiach. Dzieci, po powrocie do szkoły każde z was wygłosi referat o jednej z tych legendarnych postaci.', 0),
(1166, 'plPL', '', 'A teraz przyjrzyjcie się jeszcze raz uważnie, zanim ruszymy do Świętej Dzielnicy i wielkiej Katedry Światła.', 0),
(1192, 'plPL', 'Zapytaj mnie, jak dostać darmowego drinka w „Błękitnym Samotniku”!', '', 0),
(1193, 'plPL', 'Darmowe drinki w „Błękitnym Samotniku”!', '', 0),
(1194, 'plPL', 'Wpadnij do „Błękitnego Samotnika”. Tam, gdzie wszyscy znają twoje imię!', '', 0),
(1195, 'plPL', 'Najlepsze trunki w Wichrogrodzie!', '', 0),
(1196, 'plPL', 'Przyjdź na piwo, zostań dla atmosfery!', '', 0),
(1197, 'plPL', 'Nauka magii przegrzewa ci mózg? Odpręż się w „Błękitnym Samotniku”!', '', 0),
(1198, 'plPL', 'Jedyne miejsce w Wichrogrodzie, gdzie czary mieszają się z czarkami – przyjdź do „Błękitnego Samotnika”!', '', 0),
(1199, 'plPL', 'Doskwiera ci samotność? Wpadnij do „Błękitnego Samotnika” na dobrą zabawę!', '', 0),
(1200, 'plPL', '', 'Gorąco ci? Schłódź się czymś w „Świni i Gwizdku”!', 0),
(1201, 'plPL', '', 'Bójki co wieczór i świetne trunki! Wszystko to w „Świni i Gwizdku”!', 0),
(1202, 'plPL', '', 'Darmowe piwo w „Świni i Gwizdku”!', 0),
(1203, 'plPL', '', 'Porozmawiaj ze mną, a dostaniesz darmowe piwo w „Świni i Gwizdku”!', 0),
(1205, 'plPL', '', 'Gładsze niż elf, mocniejsze niż ork! W całym Wichrogrodzie nie ma lepszych trunków!', 0),
(1206, 'plPL', '', 'Masz dość tych słabiutkich drineczków dla magików? Spróbuj czegoś mocniejszego w „Świni i Gwizdku”!', 0),
(1207, 'plPL', '', 'Wracasz z długiej podróży? Odpocznij i zrelaksuj się w „Świni i Gwizdku”!', 0),
(1208, 'plPL', '', 'Najlepsze trunki w Wichrogrodzie!', 0),
(1401, 'plPL', '%s nie jest pod wrażeniem.', '%s nie jest pod wrażeniem.', 0),
(1402, 'plPL', 'Przeciągasz strunę, $n.', 'Przeciągasz strunę, $n.', 0),
(1403, 'plPL', 'Nie zmuszaj mnie, żebym się z tobą policzył po średniowiecznemu.', 'Nie zmuszaj mnie, żebym się z tobą policzył po średniowiecznemu.', 0),
(1404, 'plPL', 'Jeszcze raz, $n, a wbiję ci trochę manier do głowy.', 'Jeszcze raz, $n, a wbiję ci trochę manier do głowy.', 0),
(1521, 'plPL', '', '%s odwzajemnia niegrzeczny gest – $n ma za swoje.', 0),
(1529, 'plPL', '', 'Co mogę dla ciebie zrobić?', 0),
(1530, 'plPL', '', 'Na co masz ochotę, $gpanie:panienko;?', 0),
(1531, 'plPL', '', 'No proszę, witaj, $n, co ci dziś podać?', 0),
(1532, 'plPL', '', 'Ciężki dzień? Dobre piwo szybko rozwieje te zmartwienia.', 0),
(1533, 'plPL', '', 'Cześć, co podać?', 0),
(1534, 'plPL', '', 'Dzień dobry. Co podać?', 0),
(1535, 'plPL', '', 'Patrzcie, kogo tu przywiało. Co ci podać, $n?', 0),
(1536, 'plPL', '', 'Myślisz, że powinnam przypiąć sobie więcej przypinek?', 0),
(1657, 'plPL', 'Ach, szeregowy Hendel. Cóż za przyjemność poznać jednego z tych, którzy dla dumy zdradziliby własne królestwo.', '', 0),
(1658, 'plPL', 'Co ja mam zrobić?', '', 0),
(1659, 'plPL', 'Jeśli kapitan się dowie, będzie po mnie.', '', 0),
(1660, 'plPL', 'Jak to się mogło stać?', '', 0),
(1661, 'plPL', 'Nagle byli wszędzie.', '', 0),
(1662, 'plPL', 'Ktoś musiał im pomagać.', '', 0),
(1663, 'plPL', 'Może zajmiemy się tobą od razu, Hendel? Lady Proudmoore porozmawia z tobą w wieży.', '', 0),
(1678, 'plPL', '', 'Widzę, że czujesz się lepiej.', 0),
(1679, 'plPL', '', 'Wypij to, pomoże.', 0),
(1680, 'plPL', '', 'To powinno złagodzić ból.', 0),
(1681, 'plPL', '', 'Trochę tej maści powinno pomóc.', 0),
(1682, 'plPL', '', 'Wszystko będzie dobrze.', 0),
(1683, 'plPL', '', 'Weź to i wypij do dna.', 0),
(1684, 'plPL', '', 'Nie martw się, wszystkie palce u rąk i nóg zostaną na swoim miejscu.', 0),
(1685, 'plPL', '', 'Pozwól, że opatrzę te rany.', 0),
(1712, 'plPL', 'Dobra, dobra! Dość walki. Nikt więcej nie musi oberwać.', '', 0),
(1713, 'plPL', 'W porządku, chłopaki. Odpuśćcie. Wystarczy. Spotkamy się później.', '', 0),
(1718, 'plPL', 'Niech żyje $n, $c wielkiej wartości!', '', 0),
(1719, 'plPL', 'Patrzcie! „Błękitny Samotnik” wydaje ucztę na $gjego:jej; cześć!', '', 0),
(1733, 'plPL', 'Hura, $n!', '', 0),
(1735, 'plPL', 'Brawo, brawo!', '', 0),
(1736, 'plPL', 'Niech żyje $n!', '', 0),
(1743, 'plPL', 'Dobra, dobra! Nie trzeba od razu przemocy. Powiem. Wszystko powiem!', '', 0),
(1744, 'plPL', 'Mam u siebie parę notatek z tamtej roboty. Pójdę po nie, a potem spotkamy się w karczmie.', '', 0),
(1751, 'plPL', 'Idź z gracją i niech chroni cię magia naszej pani.', '', 0),
(1759, 'plPL', 'Proszę... proszę... panno Proudmoore. Ja nie chciałem...', '', 0),
(1761, 'plPL', 'Przepraszam, że zjawiam się tak późno. Chciałem, żeby lady Proudmoore także była obecna.', '', 0),
(1808, 'plPL', 'Możemy zostać tylko chwilę, potem wracamy do wieży. Jeśli zechcesz jeszcze z nami porozmawiać, znajdziesz nas tam.', '', 0),
(1828, 'plPL', 'To nie moja wina, mistrzu Mazenie!', '', 0),
(1829, 'plPL', 'To była zwykła pomyłka. Po prostu źle skręciłem, naprawdę!', '', 0),
(1830, 'plPL', 'Na tych bagnach było okropnie! Byłem taki... taki... przerażony!', '', 0),
(1831, 'plPL', 'Mam szczęście, że żyję!', '', 0),
(1950, 'plPL', 'Czas przyrządzić Kalimdorski Koktajl! Hep!', '', 0),
(1951, 'plPL', 'To powinno wystarczyć! Hep!', '', 0),
(1952, 'plPL', '%s wypija swój trunek duszkiem.', '', 0),
(1953, 'plPL', 'Hep!', '', 0),
(1954, 'plPL', 'Dobra, kto mnie przewrócił? To ty, $n? Niech ktoś zapali z powrotem światło. Hep!', '', 0),
(1955, 'plPL', 'Jeszcze łyczek starej ognistej wody i będę gotów gadać. Hep! Zdrówko!', '', 0),
(1956, 'plPL', 'No więc, $n, jestem gotów opowiedzieć ci, co się stało na Moczarach Smutków. Hep!', '', 0),
(1961, 'plPL', 'Teraz dostaniesz za swoje, $n!', '', 0),
(1986, 'plPL', 'Kto śmie przyzywać moc Pustki?', '', 0),
(1987, 'plPL', 'Za to zaznasz wiecznych mąk, $gżałosny czarnoksiężniku:żałosna czarnoksiężniczko;.', '', 0),
(1991, 'plPL', '', 'Interesujące... To więcej, niż się spodziewałam. Pyszne...', 0),
(2306, 'plPL', '%s zabiera się do pracy...', '', 0),
(2307, 'plPL', 'Gotowe. Mam twoją broń, $n.', '', 0),
(2308, 'plPL', '$n $gprzeszedł:przeszła; ścieżkę zdrowia! Trzykrotne hura na cześć $n!', '', 0),
(2309, 'plPL', 'Hip, hip, hura!', '', 0),
(2310, 'plPL', 'Tysiąc lat temu nieśmiertelne elfy, półbogowie lasu i smoki walczyli z Legionem na zboczach Hyjal.', '', 0),
(2311, 'plPL', 'Anathera i Latherion walczyli plecami do siebie tam, gdzie bitwa wrzała najmocniej. Dwoje kochanków zdecydowanych razem przetrwać wojnę.', '', 0),
(2312, 'plPL', 'Ale nie było im to pisane. Gdy wrogowie napierali, spaczone ostrze demona przebiło zbroję Anathery. W wirze bitwy nic nie mogło jej ocalić.', '', 0),
(2314, 'plPL', 'Nie zważając na szalejącą wokół bitwę, Latherion opuścił gardę, by tulić ukochaną w jej ostatnich chwilach. Lecz demony nie okazały mu litości i szybko go powaliły.', '', 0),
(2317, 'plPL', 'Tam, gdzie padli kochankowie, wyrosło drzewo. Elfy nazywają je sercodrzewem. Z pewnością posłuży twoim celom.', '', 0),
(2342, 'plPL', 'Skończone! A wyniki są zdumiewające. Muszę przekazać je moim wspólnikom: Grimandowi, Mathielowi i Klockmortowi!', '', 0),
(2343, 'plPL', 'Twój pancerz jest gotowy, $n.', '', 0),
(2345, 'plPL', 'Hura, hura! $n! Gotowe!', '', 0),
(2349, 'plPL', 'Gotowe. $n, twój pancerz czeka.', '', 0),
(2358, 'plPL', '', 'Udało się! Wygraliśmy!', 0),
(2360, 'plPL', '', 'Do domu! Trzymaj się blisko mnie, cokolwiek się stanie! Mam tam strzelbę i amunicję!', 0),
(2369, 'plPL', '', 'Kolejny z głowy!', 0),
(2370, 'plPL', 'Mam nadzieję, że jesteś $ggotów:gotowa;, $n. Chodź za mną.', '', 0),
(2374, 'plPL', 'Chodźcie, moi akolici. Weźcie pręty kanalizowania i utwórzcie wielki krąg przyzywania.', '', 0),
(2382, 'plPL', '%s rozpoczyna zaklęcie przyzwania...', '', 0),
(2383, 'plPL', 'Chodź za mną, $n. Wkrótce rozpocznę przyzwanie...', '', 0),
(2501, 'plPL', 'Bierzmy się do roboty, $n!', '', 0),
(2504, 'plPL', 'Proszę bardzo, $n.', '', 0),
(2527, 'plPL', 'Witaj. Jestem nieumarłym nauczycielem magów, a ty jesteś $gmagiem:magini;.', 'Witaj. Jestem nieumarłym nauczycielem magów, a ty jesteś $gmagiem:magini;.', 0),
(2529, 'plPL', 'Witaj. Czyżbyś $gprzybył:przybyła;, by poznać ukryte sztuki?', 'Witaj. Czyżbyś $gprzybył:przybyła;, by poznać ukryte sztuki?', 0),
(2530, 'plPL', 'Witaj, witaj. Żal mi takich jak ty, bo sekrety prawdziwej magii są poza twoim zasięgiem...', 'Witaj, witaj. Żal mi takich jak ty, bo sekrety prawdziwej magii są poza twoim zasięgiem...', 0),
(2546, 'plPL', 'Za przyzwoleniem lady Sylwany szeregi tropicieli śmierci rosną. Więcej ostrzy, które uderzą w naszych wrogów, gdy najmniej się tego spodziewają.', 'Za przyzwoleniem lady Sylwany szeregi tropicieli śmierci rosną. Więcej ostrzy, które uderzą w naszych wrogów, gdy najmniej się tego spodziewają.', 0),
(2553, 'plPL', '%s zostaje wessany do szkatuły!', '', 0),
(2564, 'plPL', '%s ucieka w Pustkę!', '', 0),
(2602, 'plPL', 'Strzaskana Dłoń przywróci Hordzie dawną chwałę.', 'Strzaskana Dłoń przywróci Hordzie dawną chwałę.', 0),
(2603, 'plPL', 'Potrzebuję szkolenia.', 'Potrzebuję szkolenia.', 0),
(2624, 'plPL', '', 'Powodzenia, $n.', 0),
(2629, 'plPL', '', 'Przygotuj się, $n, bo demon zamknięty w tej kuli to plugawa bestia.', 0),
(2634, 'plPL', 'Twój pancerz jest gotowy, $n.', '', 0),
(2647, 'plPL', '', 'To świetne materiały, $n. Zabiorę się do twojej szaty.', 0),
(2648, 'plPL', '', 'Gotowe! Wszystko skończone, $n.', 0),
(2649, 'plPL', '', 'No dobrze, do roboty!', 0),
(2650, 'plPL', '', 'Aha! Tu jest.', 0),
(2651, 'plPL', '', 'Gdzie ja położyłam tę srebrną szpulę...', 0),
(2656, 'plPL', '', 'Muszę jeszcze tylko coś sprawdzić...', 0),
(2657, 'plPL', '', 'Gotowe! Zadziałało!', 0),
(2658, 'plPL', '', 'Dziękuję za cierpliwość, $n.', 0),
(2659, 'plPL', '', 'Przechowam to tutaj, dopóki nie będzie potrzebne...', 0),
(2663, 'plPL', '', 'Dobrze, zróbmy tę kulę...', 0),
(2664, 'plPL', '', 'No dobrze. Gotowe!', 0),
(2682, 'plPL', '', 'Weź skrzynię szkatuł izolujących i inkantację manifestacji, $n. Będą ci potrzebne w twojej misji.', 0),
(2708, 'plPL', '', 'Odsuń się i... wstrzymaj oddech. Dawno tego nie robiłam.', 0),
(2709, 'plPL', '', 'Zadziałało! Niesamowite! Chyba jeszcze nie wyszłam z wprawy...', 0),
(2823, 'plPL', 'Pokaż mi swoje towary.', 'Pokaż mi swoje towary.', 0),
(2930, 'plPL', 'Z każdym dniem jest coraz grubszy i bardziej zepsuty. Czuć smród, co od niego bije. Brudny on jest, a nie chodzi mi tylko o to, że przydałoby mu się umyć.$B$BDość już gadania Hulfdana. Skąd przybywasz i jak mogę ci pomóc?', 'Z każdym dniem jest coraz grubszy i bardziej zepsuty. Czuć smród, co od niego bije. Brudny on jest, a nie chodzi mi tylko o to, że przydałoby mu się umyć.$B$BDość już gadania Hulfdana. Skąd przybywasz i jak mogę ci pomóc?', 0),
(2931, 'plPL', 'Dzień dobry, Hulfdanie, szukam szkolenia.', 'Dzień dobry, Hulfdanie, szukam szkolenia.', 0),
(3074, 'plPL', '%s wpada w gniew i atakuje!', '', 0),
(3090, 'plPL', '', 'Spotkajmy się przy sadzie – muszę tylko odłożyć strzelbę.', 0),
(3146, 'plPL', 'Przychodzisz na szkolenie? Czy tylko po to, żeby marnować czas wojownika?', 'Przychodzisz na szkolenie? Czy tylko po to, żeby marnować czas wojownika?', 0),
(3265, 'plPL', 'Więc chcesz zostać $gkowalem:kowalką;, co? Bierz fartuch i młot, $gchłopcze:dziewczyno;, zobaczymy, co potrafisz.', '', 0),
(3276, 'plPL', 'Nie widzisz, że jestem zajęty? Lepiej, żeby to było coś ważnego.', '', 0),
(3277, 'plPL', 'Rozum ci odjęło? To nie broń, to nożyk do masła. Nie szkolę amatorów.', '', 0),
(3336, 'plPL', 'Mam nadzieję, że przerywasz mi w słusznej sprawie, bo właśnie zajmowała mnie ważna praca.', 'Mam nadzieję, że przerywasz mi w słusznej sprawie, bo właśnie zajmowała mnie ważna praca.', 0),
(3337, 'plPL', '$gKolejny zielarz:Kolejna zielarka;, hmm. Wątpię, żeby twoje umiejętności dorównywały moim, więc może nauczę cię kilku porządnych technik.', '$gKolejny zielarz:Kolejna zielarka;, hmm. Wątpię, żeby twoje umiejętności dorównywały moim, więc może nauczę cię kilku porządnych technik.', 0),
(3340, 'plPL', 'Witaj w Wichrogrodzie. Odbudowa trwała długo, ale było warto. Przybywasz w odwiedziny czy w interesach?', 'Witaj w Wichrogrodzie. Odbudowa trwała długo, ale było warto. Przybywasz w odwiedziny czy w interesach?', 0),
(3341, 'plPL', 'Niewielu kucharzy przychodzi tu po naukę, ale chyba mogę cię czegoś nauczyć, jeśli jesteś $ggotów:gotowa;.', 'Niewielu kucharzy przychodzi tu po naukę, ale chyba mogę cię czegoś nauczyć, jeśli jesteś $ggotów:gotowa;.', 0),
(3342, 'plPL', 'Czy wyglądam na kogoś, kto ma czas i siłę niańczyć każdego turystę, który zabłąka się do mojego sklepu? Mów, czego potrzebujesz, i to szybko.', 'Czy wyglądam na kogoś, kto ma czas i siłę niańczyć każdego turystę, który zabłąka się do mojego sklepu? Mów, czego potrzebujesz, i to szybko.', 0),
(3351, 'plPL', 'Wielkie wojny może i się skończyły, przynajmniej na razie, ale wciąż musimy szlifować umiejętności!', 'Wielkie wojny może i się skończyły, przynajmniej na razie, ale wciąż musimy szlifować umiejętności!', 0),
(3353, 'plPL', 'Witaj. Szukasz nauki w sztuce wojennej?', 'Witaj. Czy szukasz nauki w sztuce wojennej?', 0),
(3354, 'plPL', 'Choćby nie wiem ile się nauczyć, zawsze jest coś więcej do poznania.', 'Choćby nie wiem ile się nauczyć, zawsze jest coś więcej do poznania.', 0),
(3355, 'plPL', 'Rolą wojownika jest ochrona. Tak jak w bitwie chronimy naszych towarzyszy, tak samo musimy chronić interesy Porzuconych.', 'Rolą wojownika jest ochrona. Tak jak w bitwie chronimy naszych towarzyszy, tak samo musimy chronić interesy Porzuconych.', 0),
(3356, 'plPL', 'Och, $gkolega lekarz:koleżanka lekarka;. Chętnie nauczę cię wszystkiego, co pomoże ci w podróżach.', 'Och, $gkolega lekarz:koleżanka lekarka;. Chętnie nauczę cię wszystkiego, co pomoże ci w podróżach.', 0),
(3357, 'plPL', 'Tak, $gsynu:córko;? W czym mogę ci pomóc?', 'Tak, $gsynu:córko;? W czym mogę ci pomóc?', 0),
(3362, 'plPL', 'No? Przerywasz mi, więc lepiej miej cholernie dobry powód.', 'No? Przerywasz mi, więc lepiej miej cholernie dobry powód.', 0),
(3368, 'plPL', 'Od upadku Dalaranu i zniszczenia Quel\'Thalas o takie towary jest trudno. Ale Lucan Cordell i paru innych naszych handlarzy świetnie się spisują, zaopatrując nas w porządny towar.', 'Od upadku Dalaranu i zniszczenia Quel\'Thalas o takie towary jest trudno. Ale Lucan Cordell i paru innych naszych handlarzy świetnie się spisują, zaopatrując nas w porządny towar.', 0),
(3369, 'plPL', 'Sprzedaję tylko najlepszy magiczny ekwipunek, wykonany przez rzemieślników i magów tu, w Wichrogrodzie.', 'Sprzedaję tylko najlepszy magiczny ekwipunek, wykonany przez rzemieślników i magów tu, w Wichrogrodzie.', 0),
(3371, 'plPL', 'Od upadku Dalaranu i zniszczenia Quel\'Thalas o takie towary jest trudno. Ale Lucan Cordell i paru innych naszych handlarzy świetnie się spisują, zaopatrując nas w porządny towar.', 'Od upadku Dalaranu i zniszczenia Quel\'Thalas o takie towary jest trudno. Ale Lucan Cordell i paru innych naszych handlarzy świetnie się spisują, zaopatrując nas w porządny towar.', 0),
(3372, 'plPL', 'Sprzedaję tylko najlepszy magiczny ekwipunek, wykonany przez rzemieślników i magów tu, w Wichrogrodzie.', 'Sprzedaję tylko najlepszy magiczny ekwipunek, wykonany przez rzemieślników i magów tu, w Wichrogrodzie.', 0),
(3373, 'plPL', 'Wykonane przez najlepszych rzemieślników z całego Teldrassilu i przeniesione ręcznie z Kalimdoru do Azeroth na znak rosnącego przymierza między ludem Wielkiego Drzewa a ludźmi tej krainy. Jeśli czegoś potrzebujesz, wystarczy poprosić.', 'Wykonane przez najlepszych rzemieślników z całego Teldrassilu i przeniesione ręcznie z Kalimdoru do Azeroth na znak rosnącego przymierza między ludem Wielkiego Drzewa a ludźmi tej krainy. Jeśli czegoś potrzebujesz, wystarczy poprosić.', 0),
(3374, 'plPL', 'Od upadku Dalaranu i zniszczenia Quel\'Thalas o takie towary jest trudno. Ale Lucan Cordell i paru innych naszych handlarzy świetnie się spisują, zaopatrując nas w porządny towar.', 'Od upadku Dalaranu i zniszczenia Quel\'Thalas o takie towary jest trudno. Ale Lucan Cordell i paru innych naszych handlarzy świetnie się spisują, zaopatrując nas w porządny towar.', 0),
(3375, 'plPL', 'Sprzedaję tylko najlepszy magiczny ekwipunek, wykonany przez rzemieślników i magów tu, w Wichrogrodzie.', 'Sprzedaję tylko najlepszy magiczny ekwipunek, wykonany przez rzemieślników i magów tu, w Wichrogrodzie.', 0),
(3376, 'plPL', 'Najlepsze okazje w całym Wichrogrodzie, przyjacielu, lepszych nie znajdziesz. No więc, w czym mogę pomóc?', 'Najlepsze okazje w całym Wichrogrodzie, przyjacielu, lepszych nie znajdziesz. No więc, w czym mogę pomóc?', 0),
(3377, 'plPL', 'Najlepsze okazje w całym Wichrogrodzie, przyjacielu, lepszych nie znajdziesz. No więc, w czym mogę pomóc?', 'Najlepsze okazje w całym Wichrogrodzie, przyjacielu, lepszych nie znajdziesz. No więc, w czym mogę pomóc?', 0),
